}

/* --------------------------------------------------- */
/* 4. الأرقام (أسود صريح وواضح تماماً) */
/* --------------------------------------------------- */
.widget.number-widget-box .widget-value,
.widget.number-widget-box .number-card-value,
.widget.number-widget-box .number,
.widget.number-widget-box h1,
.widget.number-widget-box h2,
.widget.number-widget-box .value {
    color: #000000 !important;
    font-size: 38px !important;
    font-weight: 900 !important;
    display: block !important;
    visibility: visible !important;
    opacity: 1 !important;
    text-align: right !important;
    line-height: 1.2 !important;
    margin: 10px 0 !important;
    font-family: 'Inter', 'Cairo', sans-serif !important;
    position: relative !important;
    z-index: 2 !important;
}

/* --------------------------------------------------- */
/* 5. النصوص السفلية ومؤشر النسبة */
/* --------------------------------------------------- */
.widget.number-widget-box .card-stats,
.widget.number-widget-box .stat-text,
.widget.number-widget-box .text-muted {
