    padding: 12px 16px;
    max-width: 500px; /* تحديد العرض ليكون صغيراً */
    font-size: 13px;
    box-shadow: 0 1px 2px rgba(0,0,0,0.05);
}

.erp-card-header {
    display: flex;
    align-items: center;
    gap: 8px;
    margin-bottom: 12px;
    padding-bottom: 8px;
    border-bottom: 1px solid #f0f0f0;
}

.erp-card-header .title {
    font-weight: 600;
    color: #111827;
}

.erp-content-grid {
    display: flex;
    flex-direction: column;
    gap: 10px;
}

.erp-row {
    display: flex;
    justify-content: space-between;
    align-items: center;
    gap: 10px;
}

.erp-row .label {
    color: #64748b;
}

/* تصميم الأزرار ليشبه أزرار ERPNext الأصلية */
.erp-btn-outline {
    background: #ffffff;
    border: 1px solid #d1d8dd;
    color: #1f2937;
    padding: 4px 12px;
    border-radius: 6px;
    cursor: pointer;
    font-size: 12px;
    text-decoration: none;
    transition: background 0.2s;
}

.erp-btn-outline:hover {
    background: #f4f5f6;
    border-color: #b1b8bd;
}

.erp-btn-dark {
    background: #1f2937;
    color: #ffffff;
    border: none;
    padding: 6px 12px;
    border-radius: 6px;
    width: 100%;
    cursor: pointer;
    font-size: 12px;
}

.erp-btn-dark:hover {
    background: #111827;
}

.secondary-row {
    background: #f9fafb;
    padding: 8px;
    border-radius: 6px;
    border: 1px dashed #d1d8dd;
}

/* تصميم الفيديو ليكون متجاوباً */
.video-wrapper {
    margin-top: 10px;
    position: relative;
    padding-bottom: 56.25%; /* 16:9 aspect ratio */
    height: 0;
    overflow: hidden;
    border-radius: 6px;
    border: 1px solid #d1d8dd;
}

.video-wrapper iframe {
    position: absolute;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
}

.erp-fade-in {
    animation: erp-slide-down 0.3s ease-out;
}

@keyframes erp-slide-down {
    from { opacity: 0; transform: translateY(-5px); }
    to { opacity: 1; transform: translateY(0); }
}

.arm-workspace-header-bw {
    background-color: #ffffff; /* خلفية بيضاء نقية */
    border: 1px solid #e5e5e5; /* إطار رمادي فاتح جداً يحدد المساحة */
    border-right: 6px solid #000000; /* خط أسود سميك وحاد على اليمين للهوية */
    border-radius: 8px; /* حواف شبه حادة تناسب الطابع المعماري */
    padding: 24px 30px;
    margin-bottom: 24px;
    box-shadow: 0 4px 15px rgba(0, 0, 0, 0.03); /* ظل خفيف جداً للعمق */
    direction: rtl;
    text-align: right;
    font-family: 'Cairo', 'Tajawal', system-ui, -apple-system, sans-serif;
    position: relative;
    overflow: hidden;
    transition: all 0.3s ease;
}

.arm-workspace-header-bw:hover {
    box-shadow: 0 8px 25px rgba(0, 0, 0, 0.06);
    transform: translateY(-2px);
    border-right-color: #333333;
}

.arm-workspace-header-bw .header-content {
    display: flex;
    align-items: center;
    justify-content: flex-start;
    gap: 20px;
    position: relative;
    z-index: 2; /* لإبقاء النص فوق الخطوط الهندسية */
}

.arm-workspace-header-bw .icon-container {
    background-color: #fafafa;
    border: 1px solid #eaeaea;
    padding: 16px;
    border-radius: 8px;
    display: flex;
    align-items: center;
    justify-content: center;
    transition: background-color 0.3s ease;
}

.arm-workspace-header-bw:hover .icon-container {
    background-color: #f0f0f0;
}

.arm-workspace-header-bw .text-content {
    display: flex;
    flex-direction: column;
    justify-content: center;
}

.arm-workspace-header-bw .main-title {
    color: #000000; /* أسود صريح */
    font-size: 26px;
    font-weight: 800; /* خط عريض جداً لإبراز الأهمية */
    margin: 0 0 4px 0;
    line-height: 1.2;
    letter-spacing: -0.5px;
}

.arm-workspace-header-bw .sub-title {
    color: #666666; /* رمادي داكن للعنوان الفرعي للتباين المريح للعين */
    font-size: 15px;
    margin: 0;
    font-weight: 600;
}

/* لمسة إبداعية: خطوط مائلة تشبه المخططات الهندسية (Blueprint Hatching) تظهر في أقصى اليسار */
.arm-workspace-header-bw .architectural-lines {
    position: absolute;
    left: 0;
    top: 0;
    width: 200px;
    height: 100%;
    background: repeating-linear-gradient(
        45deg,
        transparent,
        transparent 10px,
        rgba(0, 0, 0, 0.03) 10px,
        rgba(0, 0, 0, 0.03) 12px
    );
    z-index: 1;
    pointer-events: none;
}

/* تجاوب الشاشات */
@media (max-width: 768px) {
    .arm-workspace-header-bw {
        padding: 20px;
    }
    .arm-workspace-header-bw .main-title {
        font-size: 22px;
    }
    .arm-workspace-header-bw .icon-container {
        padding: 12px;
    }
}

script:
// World-Class Clean Script for Bir Waqf Dashboard Block v16
window.openBirFilteredList = function(doctype, filters, filterName, sort_field, sort_order) {
    if (typeof frappe === 'undefined') return;

    frappe.route_options = Object.assign({}, filters || {});

    function applyFiltersToListView(listview) {
        if (!listview || !listview.filter_area) return;

        listview.filter_area.clear().then(function() {
            if (filters && Object.keys(filters).length > 0) {
                for (var key in filters) {
                    var val = filters[key];
                    if (Array.isArray(val) && val[0] === 'in') {
                        listview.filter_area.add(doctype, key, 'in', val[1]);
                    } else {
                        listview.filter_area.add(doctype, key, '=', val);
                    }
                }
            }
            if (sort_field) {
                listview.sort_by = sort_field;
                listview.sort_order = sort_order || 'desc';
            }
            listview.refresh();
        });
    }

    var route = frappe.get_route();
    if (route && route[0] === 'List' && route[1] === doctype) {
        var listview = frappe.views.listview_instances[doctype];
        if (listview) {
            applyFiltersToListView(listview);
            if (filterName && frappe.show_alert) {
                frappe.show_alert({
                    message: __('تم تصفية القائمة المعروضة حسب: ') + filterName,
                    indicator: 'green'
                }, 4);
            }
            return;
        }
    }

    frappe.set_route('List', doctype).then(function() {
        setTimeout(function() {
            var listview = frappe.views.listview_instances[doctype];
            if (listview) {
                applyFiltersToListView(listview);
            }
        }, 400);
    });

    if (filterName && frappe.show_alert) {
        frappe.show_alert({
            message: __('جاري فتح القائمة المفلترة: ') + filterName,
            indicator: 'green'
        }, 4);
    }
};

(function(wrapper) {
	if (!wrapper) wrapper = document;

	function renderClock() {
		var now = new Date();
		var clock = wrapper.querySelector('.bir-hu-clock');
		if (clock) {
			clock.innerText = now.toLocaleTimeString('ar-LY', { hour: '2-digit', minute: '2-digit', second: '2-digit' });
		}
	}
	setInterval(renderClock, 1000);
	renderClock();

	function fetchStats() {
		frappe.call({
			method: 'bir_waqf.api.get_dashboard_stats',
			callback: function(r) {
				if (r && r.message) {
					var stats = r.message;

					// 1. Total Amount
					var amtEl = wrapper.querySelector('.val-total-amount');
					if (amtEl) {
						var val = (stats.total_donations || 0).toLocaleString('ar-LY', {minimumFractionDigits:2, maximumFractionDigits:2});
						amtEl.innerHTML = val + ' <small>د.ل</small>';
					}

					// 2. Total Count
					var cntEl = wrapper.querySelector('.val-total-count');
					if (cntEl) {
						cntEl.innerText = (stats.total_transactions || 0).toLocaleString('ar-LY') + ' معاملة مدخلة';
					}

					// 3. Transactions Input
					var inputEl = wrapper.querySelector('.val-transactions-input');
					if (inputEl) {
						inputEl.innerText = (stats.total_transactions || 0).toLocaleString('ar-LY');
					}

					// 4. Matched Count & Pct
					var matchEl = wrapper.querySelector('.val-matched-count');
					if (matchEl) {
						matchEl.innerText = (stats.matched_transactions || 0).toLocaleString('ar-LY');
					}
					var pct = stats.total_transactions > 0 ? Math.round((stats.matched_transactions / stats.total_transactions) * 100) : 0;
					var pctEl = wrapper.querySelector('.val-matched-pct');
					if (pctEl) {
						pctEl.innerText = pct + '% نسبة المطابقة';
					}

					// 5. Exceptions
					var excEl = wrapper.querySelector('.val-exceptions-count');
					if (excEl) {
						excEl.innerText = (stats.exceptions_count || 0).toLocaleString('ar-LY');
					}

					// 6. Max Single
					var maxSingleEl = wrapper.querySelector('.val-max-single');
					if (maxSingleEl) {
						var msVal = (stats.max_single || 0).toLocaleString('ar-LY', {minimumFractionDigits:2, maximumFractionDigits:2});
						maxSingleEl.innerHTML = msVal + ' <small>د.ل</small>';
					}

					// 7. Max Basket
					var maxBasketEl = wrapper.querySelector('.val-max-basket');
					if (maxBasketEl) {
						var mbVal = (stats.max_basket || 0).toLocaleString('ar-LY', {minimumFractionDigits:2, maximumFractionDigits:2});
						mbVal.innerHTML = mbVal + ' <small>د.ل</small>';
					}

					var bskSubEl = wrapper.querySelector('.val-basket-count-sub');
					if (bskSubEl) {
						bskSubEl.innerText = (stats.basket_count || 0).toLocaleString('ar-LY') + ' معاملة سلة بالمشاريع';
					}

					// 8. Top Projects List
					var projContainer = wrapper.querySelector('.bir-wc-projects-list');
					if (projContainer) {
						if (stats.top_projects && stats.top_projects.length > 0) {
							var projHtml = '';
							stats.top_projects.forEach(function(p, idx) {
								var rankBadge = '<span class="bir-v8-rank">#' + (idx + 1) + '</span>';
								var pVal = (p.total || 0).toLocaleString('ar-LY', {minimumFractionDigits:2, maximumFractionDigits:2});
								projHtml += '<div class="bir-v8-proj-row">' +
									'<div class="bir-v8-proj-info">' + rankBadge + '<span class="bir-v8-proj-title">' + (p.project_name || 'مشروع وقفي') + '</span></div>' +
									'<div class="bir-v8-proj-amount">' + pVal + ' <small>د.ل</small></div>' +
								'</div>';
							});
							projContainer.innerHTML = projHtml;
						} else {
							projContainer.innerHTML = '<div class="bir-v8-empty" style="text-align:center;padding:12px;color:#94a3b8;font-size:11.5px;">لا توجد بيانات مشاريع سلة حالياً</div>';
						}
					}
				}
			}
		});
	}

	setTimeout(fetchStats, 100);
})(typeof root_element !== 'undefined' ? root_element : document);

style:
/* ---------------------------------------------------
 * v17 — منصة البر الوقفية
 * هوية بصرية مُنقّحة: هدوء بصري، تباين مدروس، لمسة إسلامية أصيلة
 * أخضر زُمردي عميق + ذهبي عتيق مطفأ + عاجي دافئ بدل الأبيض البارد
 * Amiri للعناوين (حضور كلاسيكي) + Tajawal للواجهة والأرقام
 * --------------------------------------------------- */
@import url('https://fonts.googleapis.com/css2?family=Amiri:wght@400;700&family=Tajawal:wght@400;500;700;800&display=swap');

.bir-wc-dashboard {
  --wc-emerald-900: #0d3d2a;
  --wc-emerald-700: #0f5c3d;
  --wc-emerald-50:  #eef6f1;
  --wc-gold-600:    #ad8226;
  --wc-gold-700:    #8f6b1d;
  --wc-gold-50:     #faf4e4;
  --wc-ivory:       #fefcf8;
  --wc-ink:         #1e2a24;
  --wc-slate:       #6f7d75;
  --wc-border:      #e7e1d3;
  --wc-border-soft: #f0ece0;
  --wc-red:         #a3372f;
  --wc-red-50:      #fbecea;

  direction: rtl;
  font-family: "Tajawal", "Inter", -apple-system, sans-serif;
  color: var(--wc-ink);
  background: var(--wc-ivory);
  border: 1px solid var(--wc-border);
  border-radius: 18px;
  padding: 22px;
  margin-bottom: 24px;
}

/* 1. Header ------------------------------------------------- */
.bir-wc-header {
  position: relative;
  background: #ffffff;
  border: 1px solid var(--wc-border);
  border-radius: 14px;
  padding: 18px 26px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 22px;
  overflow: hidden;
  box-shadow: 0 1px 2px rgba(13, 61, 42, 0.03);
}

/* شريط علوي هندسي رفيع مستوحى من الزخرفة الإسلامية بدل اللون المصمت */
.bir-wc-header::before {
  content: "";
  position: absolute;
  top: 0;
  right: 0;
  left: 0;
  height: 4px;
  background-image:
    linear-gradient(135deg, var(--wc-gold-600) 25%, transparent 25%),
    linear-gradient(225deg, var(--wc-gold-600) 25%, transparent 25%),
    linear-gradient(45deg, var(--wc-emerald-700) 25%, transparent 25%),
    linear-gradient(315deg, var(--wc-emerald-700) 25%, transparent 25%);
  background-position: 0 0, 6px 0, 6px 0, 0 0;
  background-size: 12px 4px;
  opacity: 0.9;
}

.bir-wc-brand {
  display: flex;
  align-items: center;
  gap: 18px;
}

.bir-wc-logo-box {
  width: 118px;
  height: 68px;
  border-radius: 10px;
  background: #ffffff;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 6px;
  border: 1px solid var(--wc-border);
  flex-shrink: 0;
}

.bir-wc-logo-img {
  max-width: 100%;
  max-height: 100%;
  width: auto;
  height: auto;
  object-fit: contain;
}

.bir-wc-titles {
  display: flex;
  flex-direction: column;
}

.bir-wc-main-title {
  font-family: "Amiri", "Tajawal", serif;
  font-size: 19px;
  font-weight: 700;
  color: var(--wc-emerald-900);
  margin: 0;
  line-height: 1.35;
  letter-spacing: 0.2px;
}

.bir-wc-sub-title {
  font-size: 12.5px;
  color: var(--wc-slate);
  margin: 4px 0 0 0;
}

.bir-wc-meta {
  display: flex;
  align-items: center;
  gap: 10px;
}

.bir-wc-status-pill {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  background: var(--wc-emerald-50);
  color: var(--wc-emerald-700);
  padding: 4px 13px;
  border-radius: 20px;
  font-size: 11px;
  font-weight: 700;
}

.bir-wc-dot {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: var(--wc-emerald-700);
}

.bir-wc-clock-box {
  font-size: 12px;
  font-weight: 700;
  color: var(--wc-emerald-900);
  background: var(--wc-gold-50);
  padding: 4px 13px;
  border-radius: 8px;
  border: 1px solid var(--wc-border);
}

/* 2. KPI Grid ------------------------------------------------ */
.bir-wc-kpi-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(168px, 1fr));
  gap: 12px;
  margin-bottom: 24px;
}

.bir-wc-card {
  background: #ffffff;
  border: 1px solid var(--wc-border);
  border-radius: 12px;
  padding: 14px 17px;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  cursor: pointer;
  transition: border-color 0.18s ease, box-shadow 0.18s ease;
  min-height: 82px;
  position: relative;
}

.bir-wc-card::before {
  content: "";
  position: absolute;
  top: 0;
  right: 14px;
  left: 14px;
  height: 3px;
  border-radius: 0 0 3px 3px;
  background: var(--wc-emerald-700);
}

.bir-wc-card.gold-border::before {
  background: var(--wc-gold-600);
}

.bir-wc-card.red-border::before {
  background: var(--wc-red);
}

.bir-wc-card:hover {
  border-color: var(--wc-emerald-700);
  box-shadow: 0 3px 10px rgba(13, 61, 42, 0.08);
}

.bir-wc-card-title {
  font-size: 11.5px;
  color: var(--wc-slate);
  font-weight: 700;
  margin-bottom: 6px;
  line-height: 1.3;
}

.bir-wc-card-value {
  font-size: 1.4rem;
  font-weight: 800;
  color: var(--wc-emerald-900);
  line-height: 1.2;
}

.bir-wc-card-value.gold {
  color: var(--wc-gold-700);
}

.bir-wc-card-value.red {
  color: var(--wc-red);
}

.bir-wc-card-value small {
  font-size: 0.72rem;
  font-weight: 700;
  color: var(--wc-gold-700);
}

.bir-wc-card-caption {
  font-size: 10.5px;
  color: #a09b8c;
  font-weight: 600;
  margin-top: 5px;
}

.bir-wc-card-caption.red {
  color: var(--wc-red);
}

/* 3. Section Title -------------------------------------------- */
.bir-wc-section-header {
  font-family: "Amiri", "Tajawal", serif;
  font-size: 15px;
  font-weight: 700;
  color: var(--wc-emerald-900);
  margin-bottom: 13px;
  text-align: right;
}

/* 4. Panels & Buttons ------------------------------------------ */
.bir-wc-panels-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 16px;
}

@media (max-width: 992px) {
  .bir-wc-panels-grid {
    grid-template-columns: 1fr;
  }
}

.bir-wc-panel {
  background: #ffffff;
  border: 1px solid var(--wc-border);
  border-radius: 14px;
  padding: 18px;
  display: flex;
  flex-direction: column;
}

.bir-wc-panel-head {
  font-size: 13.5px;
  font-weight: 800;
  color: var(--wc-ink);
  padding-bottom: 11px;
  margin-bottom: 13px;
  border-bottom: 1px solid var(--wc-border-soft);
  text-align: right;
}

.bir-wc-btn-list {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.bir-wc-btn {
  background: #ffffff;
  border: 1px solid var(--wc-border);
  border-radius: 9px;
  padding: 11px 15px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  cursor: pointer;
  text-align: right;
  transition: border-color 0.18s ease, background 0.18s ease;
  color: var(--wc-ink);
  width: 100%;
}

.bir-wc-btn:hover {
  background: var(--wc-emerald-50);
  border-color: var(--wc-emerald-700);
}

.bir-wc-btn.btn-hero {
  background: var(--wc-emerald-900);
  border-color: var(--wc-emerald-900);
  color: #ffffff;
}

.bir-wc-btn.btn-hero:hover {
  background: var(--wc-emerald-700);
  border-color: var(--wc-emerald-700);
}

.bir-wc-btn-text {
  display: flex;
  flex-direction: column;
}

.bir-wc-btn-text strong {
  font-size: 12.5px;
  font-weight: 700;
  line-height: 1.3;
}

.bir-wc-btn-text small {
  font-size: 10.5px;
  color: var(--wc-slate);
  margin-top: 2px;
}

.btn-hero .bir-wc-btn-text small {
  color: #cfe7da;
}

.bir-wc-tag {
  font-size: 10px;
  font-weight: 700;
  padding: 2px 9px;
  border-radius: 5px;
  flex-shrink: 0;
}

.bir-wc-tag.white {
  background: rgba(255, 255, 255, 0.18);
  color: #ffffff;
}

.bir-wc-tag.soft-green {
  background: var(--wc-emerald-50);
  color: var(--wc-emerald-700);
}

.bir-wc-tag.soft-blue {
  background: #e8f2f6;
  color: #1c5f77;
}

.bir-wc-arrow {
  font-size: 12px;
  color: #b7b2a3;
  flex-shrink: 0;
}

/* Projects List ------------------------------------------------- */
.bir-wc-projects-list {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.bir-v8-proj-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 9px 13px;
  background: var(--wc-ivory);
  border-radius: 8px;
  border: 1px solid var(--wc-border-soft);
}

.bir-v8-proj-info {
  display: flex;
  align-items: center;
  gap: 8px;
}

.bir-v8-rank {
  background: var(--wc-gold-50);
  color: var(--wc-gold-700);
  font-size: 10px;
  font-weight: 800;
  padding: 2px 6px;
  border-radius: 5px;
}

.bir-v8-proj-title {
  font-size: 11.5px;
  font-weight: 700;
  color: var(--wc-ink);
}

.bir-v8-proj-amount {
  font-size: 12.5px;
  font-weight: 800;
  color: var(--wc-emerald-900);
}

.bir-v8-proj-amount small {
  font-size: 10px;
  color: var(--wc-slate);
  font-weight: 600;
}

.bir-wc-loading {
  text-align: center;
  padding: 16px;
  color: #b7b2a3;
  font-size: 11.5px;
}

script:
(function () {
  "use strict";

  /* ==========================================================================
   * اللوحة التنفيذية الكلاسيكية - Modular Executive Engine (Frappe Custom Block)
   * Built according to clean architecture, reliability, and security standards
   * ========================================================================== */

  var root = typeof root_element !== "undefined" ? root_element : document.querySelector(".mp-fin-dash") || document.querySelector(".mp-block") || document;

  installNumberTypography(root);

  function installNumberTypography(scope) {
    if (!scope || scope.__number_typography_installed) return;
    scope.__number_typography_installed = true;
    var digits = /[0-9٠-٩]+(?:[.,:/+\-%][0-9٠-٩]+)*/g;
    var excluded = "SCRIPT,STYLE,TEXTAREA,OPTION";
    function render() {
      var walker = document.createTreeWalker(scope, NodeFilter.SHOW_TEXT, null, false), nodes = [], node;
      while ((node = walker.nextNode())) {
        var parent = node.parentElement;
        if (parent && !parent.closest(".app-number") && excluded.indexOf(parent.tagName) === -1 && digits.test(node.nodeValue)) nodes.push(node);
        digits.lastIndex = 0;
      }
      nodes.forEach(function (textNode) {
        var fragment = document.createDocumentFragment(), value = textNode.nodeValue, last = 0;
        value.replace(digits, function (match, offset) {
          fragment.appendChild(document.createTextNode(value.slice(last, offset)));
          var span = document.createElement("span"); span.className = "app-number"; span.textContent = match;
          fragment.appendChild(span); last = offset + match.length;
        });
        fragment.appendChild(document.createTextNode(value.slice(last))); textNode.parentNode.replaceChild(fragment, textNode); digits.lastIndex = 0;
      });
    }
    var queued = false;
    new MutationObserver(function () { if (!queued) { queued = true; requestAnimationFrame(function () { queued = false; render(); }); } }).observe(scope, { childList: true, characterData: true, subtree: true });
    render();
  }

  // 1. الإعدادات والثوابت (Configuration)
  var CONFIG = {
    TIMEOUT_MS: 9000,
    ANIMATION_DURATION_MS: 650,
    ALLOWED_DOCTYPES: ["active_taq", "mak_taq", "tyac_taq", "enac_taq", "waed_info", "exam_group_date"]
  };

  // 2. إدارة الحالة (State Management)
  var STATE = {
    counts: {
      voaz: 0,
      makatib: 0,
      completed: 0
    }
  };

  // 3. خدمة البيانات (API Service)
  var APIService = {
    fetchCount: function (doctype, filters) {
      if (!window.frappe || !frappe.db || !frappe.db.count) {
        return Promise.resolve(0);
      }

      return new Promise(function (resolve) {
        var queryFilters = filters ? Object.assign({}, filters) : {};

        frappe.db.count(doctype, Object.keys(queryFilters).length > 0 ? { filters: queryFilters } : {})
          .then(function (count) {
            resolve(typeof count === "number" ? count : 0);
          })
          .catch(function () {
            resolve(0);
          });

        setTimeout(function () {
          resolve(0);
        }, CONFIG.TIMEOUT_MS);
      });
    },

    fetchAll: function () {
      return Promise.all([
        APIService.fetchCount("active_taq"),
        APIService.fetchCount("mak_taq")
      ]).then(function (results) {
        STATE.counts.voaz = results[0];
        STATE.counts.completed = results[0];
        STATE.counts.makatib = results[1];
        return STATE.counts;
      });
    }
  };

  // 4. منطق العرض والتحديث (UI Presenter)
  var UIPresenter = {
    /* تحويل الأرقام إلى الصيغة القياسية 1234 دائماً */
    formatDigits: function (val) {
      if (val === null || val === undefined) return "0";
      return String(val).replace(/[٠-٩]/g, function (d) {
        return d.charCodeAt(0) - 1632;
      });
    },

    /* تحريك العداد الرقمي بانسيابية */
    animateNumber: function (el, targetValue) {
      if (!el) return;
      el.classList.remove("is-loading");
      el.setAttribute("dir", "ltr");
      el.setAttribute("lang", "en");

      if (typeof targetValue !== "number" || isNaN(targetValue)) {
        el.textContent = "0";
        return;
      }

      var startValue = 0;
      var startTime = null;
      var animDuration = CONFIG.ANIMATION_DURATION_MS;

      function step(timestamp) {
        if (!startTime) startTime = timestamp;
        var progress = Math.min((timestamp - startTime) / animDuration, 1);
        var easeProgress = 1 - Math.pow(1 - progress, 3);
        var current = Math.round(startValue + (targetValue - startValue) * easeProgress);

        el.textContent = UIPresenter.formatDigits(current);

        if (progress < 1) {
          window.requestAnimationFrame(step);
        } else {
          el.textContent = UIPPresenter.formatDigits(targetValue);
        }
      }

      window.requestAnimationFrame(step);
    },

    setCount: function (selector, value) {
      var targetEl = root.querySelector(selector);
      if (!targetEl) return;
      var numEl = targetEl.querySelector(".mp-fin-metric-value") || targetEl.querySelector(".num") || targetEl;
      UIPresenter.animateNumber(numEl, typeof value === "number" ? value : 0);
    },

    /* تحديث اسم المستخدم وجملة الترحيب */
    updateGreeting: function () {
      var greetingEl = root.querySelector("#greeting-text");
      if (!greetingEl) return;
      var fullname = (window.frappe && frappe.session) ? (frappe.session.user_fullname || frappe.session.user) : "";
      if (fullname && fullname !== "Administrator") {
        greetingEl.textContent = "مرحباً بك، " + fullname;
      } else {
        greetingEl.textContent = "مرحباً بك";
      }
    },

    /* تحديث الوقت والتاريخ بالأرقام القياسية */
    updateDateTime: function () {
      var el = root.querySelector("#datetime-text");
      if (!el) return;
      var now = new Date();
      
      var days = ["الأحد", "الإثنين", "الثلاثاء", "الأربعاء", "الخميس", "الجمعة", "السبت"];
      var months = ["يناير", "فبراير", "مارس", "أبريل", "مايو", "يونيو", "يوليو", "أغسطس", "سبتمبر", "أكتوبر", "نوفمبر", "ديسمبر"];
      
      var dayName = days[now.getDay()];
      var dayNum = UIPresenter.formatDigits(now.getDate());
      var monthName = months[now.getMonth()];
      var yearNum = UIPresenter.formatDigits(now.getFullYear());
      
      var hours = now.getHours();
      var minutes = now.getMinutes();
      var ampm = hours >= 12 ? "م" : "ص";
      hours = hours % 12;
      hours = hours ? hours : 12;
      var formattedHours = UIPresenter.formatDigits(hours < 10 ? "0" + hours : hours);
      var formattedMinutes = UIPresenter.formatDigits(minutes < 10 ? "0" + minutes : minutes);

      el.setAttribute("dir", "rtl");
      el.innerHTML = dayName + "، <span class=\"num\">" + dayNum + "</span> " + monthName + " <span class=\"num\">" + yearNum + "</span> | <span class=\"num\">" + formattedHours + ":" + formattedMinutes + "</span> " + ampm;
    },

    renderAll: function () {
      UIPresenter.setCount("#stat-completed", STATE.counts.completed);
      UIPresenter.setCount("#stat-voaz", STATE.counts.voaz);
      UIPresenter.setCount("#stat-makatib", STATE.counts.makatib);
    }
  };

  // 5. موجه التوجيه والتنقل (Router)
  var Router = {
    handleNav: function (target) {
      var id = target.id;
      var href = target.getAttribute("href");

      // بطاقات المؤشرات
      if (id === "stat-completed" || id === "stat-voaz" || id === "link-voaz") {
        Router.routeToList("active_taq");
        return;
      }
      if (id === "stat-makatib" || id === "link-makatib") {
        Router.routeToList("mak_taq");
        return;
      }
      if (id === "link-dashboard") {
        if (window.frappe && frappe.set_route) {
          frappe.set_route("dashboard-view", "الاحصائيات والتقارير");
        } else {
          window.location.href = "/app/dashboard-view/الاحصائيات والتقارير";
        }
        return;
      }
      if (id === "link-janib") {
        Router.routeToList("tyac_taq");
        return;
      }
      if (id === "link-anawin") {
        Router.routeToList("enac_taq");
        return;
      }

      // بوابات الأقسام التخصصية: مساحات العمل المباشرة
      if (id === "link-sec-waed") {
        Router.routeToWorkspace("قسم-الوعاظ");
        return;
      }
      if (id === "link-sec-femalwaed") {
        Router.routeToWorkspace("قسم-الواعظات");
        return;
      }

      // روابط خارجية أو عادية
      if (href && href.startsWith("http")) {
        window.open(href, "_blank");
      }
    },

    /* فتح مساحة عمل Frappe Workspace المباشرة */
    routeToWorkspace: function (workspaceSlug) {
      if (window.frappe && frappe.set_route) {
        frappe.set_route(workspaceSlug);
      } else {
        window.location.href = "/app/" + encodeURIComponent(workspaceSlug);
      }
    },

    /* فتح قائمة Doctype List View */
    routeToList: function (doctype, filters) {
      if (window.frappe && frappe.set_route) {
        if (filters && Object.keys(filters).length > 0) {
          frappe.route_options = filters;
          frappe.set_route("list", doctype, filters);
        } else {
          frappe.route_options = null;
          try { delete frappe.route_options; } catch (_) {}
          frappe.set_route("list", doctype);
        }
      } else {
        var query = filters && Object.keys(filters).length > 0 ? "?" + new URLSearchParams(filters).toString() : "";
        window.location.href = "/app/" + encodeURIComponent(doctype.toLowerCase().replace(/ /g, "-")) + query;
      }
    }
  };

  // 6. إدارة الأحداث والمؤقتات (Event Controller)
  function initEvents() {
    if (root.__mp_events_bound) return;
    root.__mp_events_bound = true;

    root.addEventListener("click", function (e) {
      if (e.target.closest("#btn-main-platform")) {
        return;
      }

      var target = e.target.closest(".mp-fin-metric-card, .mp-fin-portal-item, .mp-fin-link");
      if (target) {
        e.preventDefault();
        Router.handleNav(target);
      }
    });

    root.addEventListener("keydown", function (e) {
      if (e.key === "Enter" || e.key === " ") {
        var target = e.target.closest(".mp-fin-metric-card, .mp-fin-portal-item, .mp-fin-link");
        if (target) {
          e.preventDefault();
          Router.handleNav(target);
        }
      }
    });
  }

  // 7. دورة التشغيل (Lifecycle Runner)
  function init() {
    initEvents();
    UIPresenter.updateGreeting();
    UIPresenter.updateDateTime();

    if (root.__mp_clock_interval) {
      clearInterval(root.__mp_clock_interval);
    }
    root.__mp_clock_interval = setInterval(UIPresenter.updateDateTime, 1000);

    APIService.fetchAll()
      .then(function () {
        UIPresenter.renderAll();
      })
      .catch(function (err) {
        console.warn("[Classic Financial Dashboard] Load error:", err);
      });
  }

  init();
})();

style:
@import url('https://fonts.googleapis.com/css2?family=Cairo:wght@300;400;500;600;700;800;900&display=swap');

/* ==========================================================================
   نظام الخطوط الموحد: GE SS Two للنصوص و Cairo حصرياً للأرقام القياسية (1234)
   ========================================================================== */
/* 1. ضبط مساحة الحاوية في بيئة Frappe Desk */
.root_element,
.mp-fin-dash {
  width: 100%;
}

.page-body, 
.workspace-sidebar-toggle ~ .page-container .container,
.page-container .container,
.layout-main-section-wrapper,
.codex-editor,
.codex-editor__redactor,
.ce-block,
.ce-block__content,
.ce-toolbar__content {
  max-width: 100% !important;
}

/* 2. ثوابت الخطوط والتطبيع الشامل - GE SS Two للنصوص */
.mp-fin-dash,
.mp-fin-dash *,
.mp-fin-dash *::before,
.mp-fin-dash *::after,
.mp-fin-dash h1,
.mp-fin-dash h2,
.mp-fin-dash h3,
.mp-fin-dash h4,
.mp-fin-dash p,
.mp-fin-dash span,
.mp-fin-dash a,
.mp-fin-dash div,
.mp-fin-dash strong,
.mp-fin-dash button,
.mp-fin-dash label {
  box-sizing: border-box;
  font-family: 'GE SS Two' !important;
  text-decoration: none !important;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

/* 3. استثناء الأرقام فقط: خط Cairo الصريح والأرقام القياسية 1234 دائماً */
.mp-fin-metric-value,
.mp-fin-metric-value *,
.mp-fin-clock .num,
.mp-live-time,
.mp-live-time *,
.mp-kpi-num,
.mp-kpi-num *,
.num,
.number,
.digits,
.stat-number,
[data-num] {
  font-family: 'GE SS Two' !important;
  font-feature-settings: "locl" 0, "numr" 0, "lnum" 1, "tnum" 1 !important;
  font-variant-numeric: lining-nums tabular-nums !important;
  direction: ltr !important;
  unicode-bidi: isolate !important;
  display: inline-block;
}

/* Cairo is limited to digit-only spans created by the typography runtime. */
.mp-fin-dash .app-number,
.mp-fin-dash input[type="number"],
.mp-fin-dash input[inputmode="numeric"],
.mp-fin-dash input[inputmode="decimal"],
.mp-fin-dash input[type="tel"] {
  font-family: 'Cairo' !important;
  font-feature-settings: "locl" 0, "lnum" 1, "tnum" 1 !important;
  font-variant-numeric: lining-nums tabular-nums !important;
  direction: ltr;
  unicode-bidi: isolate;
}

.mp-fin-dash a,
.mp-fin-dash a:hover,
.mp-fin-dash a:focus,
.mp-fin-dash a:visited {
  text-decoration: none !important;
}

/* ==========================================================================
   الحاوية البيضاء النقية الفاخرة (Clean White Canvas)
   ========================================================================== */
.mp-fin-dash {
  position: relative;
  width: 100%;
  border-radius: 18px;
  background: #FFFFFF !important;
  border: 1px solid #E2E8F0;
  box-shadow: 0 4px 20px -2px rgba(15, 23, 42, 0.05),
              0 1px 3px rgba(15, 23, 42, 0.03);
  overflow: hidden;
  color: #0F172A;
}

.mp-fin-wrapper {
  position: relative;
  padding: 34px 38px;
  display: flex;
  flex-direction: column;
  gap: 28px;
  background: radial-gradient(80% 120% at 100% 0%, #F0F9FF 0%, #FFFFFF 45%),
              #FFFFFF;
}

/* ==========================================================================
   1. الترويسة الرئيسية والشعار الشفاف (Classic Header & Transparent Large Logo)
   ========================================================================== */
.mp-fin-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 24px;
  padding-bottom: 24px;
  border-bottom: 1px solid #E2E8F0;
  flex-wrap: wrap;
}

.mp-fin-header__brand {
  display: flex;
  align-items: center;
  gap: 22px;
}

/* الشعار: مكبّر وخلفية شفافة تماماً */
.mp-fin-logo-wrap {
  display: flex;
  align-items: center;
  justify-content: center;
  background: transparent !important;
  border: none !important;
  box-shadow: none !important;
  padding: 0 !important;
  margin: 0 !important;
  flex-shrink: 0;
}

.mp-fin-logo {
  height: 74px;
  width: auto;
  object-fit: contain;
  background: transparent !important;
  filter: drop-shadow(0 2px 8px rgba(15, 23, 42, 0.08));
}

.mp-fin-brand-info {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.mp-fin-badge-row {
  display: flex;
  align-items: center;
  gap: 10px;
}

.mp-fin-pill {
  font-size: 11.5px;
  font-weight: 700;
  padding: 3px 10px;
  border-radius: 6px;
  letter-spacing: 0.2px;
}

.mp-fin-pill--sky {
  background: #F0F9FF;
  color: #0284C7;
  border: 1px solid #BAE6FD;
}

.mp-fin-live-status {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-size: 11.5px;
  font-weight: 600;
  color: #0284C7;
}

.mp-fin-pulse-dot {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: #0284C7;
  box-shadow: 0 0 8px rgba(2, 132, 199, 0.45);
  animation: finPulse 2s infinite ease-in-out;
}

@keyframes finPulse {
  0%, 100% { opacity: 1; transform: scale(1); }
  50% { opacity: 0.35; transform: scale(0.85); }
}

.mp-fin-main-title {
  font-size: 26px;
  font-weight: 900;
  color: #0F172A;
  margin: 2px 0 0 0;
  line-height: 1.25;
  letter-spacing: -0.3px;
}

.mp-fin-subtitle {
  font-size: 13.5px;
  color: #64748B;
  margin: 0;
  line-height: 1.6;
}

/* بطاقة المستخدم وزر المنصة الأزرق السماوي */
.mp-fin-header__meta {
  display: flex;
  align-items: center;
  gap: 16px;
  flex-wrap: wrap;
}

.mp-fin-user-card {
  display: flex;
  align-items: center;
  gap: 10px;
  background: #F8FAFC;
  border: 1px solid #E2E8F0;
  border-radius: 10px;
  padding: 8px 14px;
}

.mp-fin-user-icon {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 32px;
  height: 32px;
  border-radius: 50%;
  background: #E0F2FE;
  color: #0284C7;
}
.mp-fin-user-icon svg {
  width: 17px;
  height: 17px;
}

.mp-fin-user-text {
  display: flex;
  flex-direction: column;
  text-align: right;
}

.mp-fin-greeting {
  font-size: 13.5px;
  font-weight: 800;
  color: #0F172A;
}

.mp-fin-clock {
  font-size: 11.5px;
  font-weight: 600;
  color: #64748B;
  font-feature-settings: "locl" 0, "lnum" 1 !important;
  direction: ltr;
}

/* زر المنصة بالأزرق السماوي المحيطي */
.mp-fin-platform-btn {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  background: linear-gradient(135deg, #0284C7 0%, #0369A1 100%) !important;
  color: #FFFFFF !important;
  font-weight: 800;
  font-size: 13.5px;
  padding: 10px 20px;
  border-radius: 8px !important;
  border: 1px solid rgba(2, 132, 199, 0.3);
  box-shadow: 0 4px 14px rgba(2, 132, 199, 0.25);
  transition: all 0.25s ease;
  cursor: pointer;
}

.mp-fin-platform-btn:hover {
  background: linear-gradient(135deg, #0EA5E9 0%, #0284C7 100%) !important;
  transform: translateY(-2px);
  box-shadow: 0 8px 20px rgba(2, 132, 199, 0.35);
}

.mp-fin-btn-arrow {
  font-size: 14px;
  font-weight: 900;
  transition: transform 0.2s ease;
}
.mp-fin-platform-btn:hover .mp-fin-btn-arrow {
  transform: translateX(-3px);
}

/* ==========================================================================
   2. بطاقات المؤشرات (Financial KPI Metric Cards - White Mode)
   ========================================================================== */
.mp-fin-metrics-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 16px;
}

.mp-fin-metric-card {
  background: #FFFFFF;
  border: 1px solid #E2E8F0;
  border-radius: 12px;
  padding: 18px 20px;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  box-shadow: 0 2px 8px rgba(15, 23, 42, 0.04);
  transition: all 0.25s cubic-bezier(0.22, 1, 0.36, 1);
  cursor: pointer;
  outline: none;
}

.mp-fin-metric-card:hover,
.mp-fin-metric-card:focus-visible {
  transform: translateY(-3px);
  background: #FFFFFF;
  border-color: #38BDF8;
  box-shadow: 0 12px 24px -4px rgba(2, 132, 199, 0.12),
              0 0 0 1px #38BDF8 inset;
}

.mp-fin-metric-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 14px;
}

.mp-fin-icon-box {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 38px;
  height: 38px;
  border-radius: 8px;
}
.mp-fin-icon-box svg {
  width: 20px;
  height: 20px;
}

.mp-fin-icon--teal {
  background: #F0FDFA;
  color: #0D9488;
  border: 1px solid #99F6E4;
}

.mp-fin-icon--sky {
  background: #F0F9FF;
  color: #0284C7;
  border: 1px solid #BAE6FD;
}

.mp-fin-icon--amber {
  background: #FFFBEB;
  color: #D97706;
  border: 1px solid #FDE68A;
}

.mp-fin-metric-tag {
  font-size: 11px;
  font-weight: 700;
  padding: 3px 8px;
  border-radius: 6px;
}

.mp-fin-tag--teal {
  background: #ECFDF5;
  color: #059669;
}
.mp-fin-tag--sky {
  background: #F0F9FF;
  color: #0284C7;
}
.mp-fin-tag--amber {
  background: #FFFBEB;
  color: #D97706;
}

.mp-fin-metric-body {
  margin-bottom: 14px;
}

.mp-fin-metric-value {
  font-size: 32px;
  font-weight: 900;
  color: #0F172A;
  line-height: 1.1;
  font-feature-settings: "locl" 0, "lnum" 1 !important;
  direction: ltr;
  text-align: right;
}

.mp-fin-metric-value.is-loading {
  color: #CBD5E1;
}

.mp-fin-metric-title {
  font-size: 13.5px;
  font-weight: 700;
  color: #475569;
  margin-top: 6px;
}

.mp-fin-metric-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  font-size: 11.5px;
  font-weight: 600;
  color: #64748B;
  border-top: 1px solid #F1F5F9;
  padding-top: 10px;
  transition: color 0.2s ease;
}

.mp-fin-arrow {
  font-size: 13px;
  transition: transform 0.2s ease;
}

.mp-fin-metric-card:hover .mp-fin-metric-footer {
  color: #0284C7;
}
.mp-fin-metric-card:hover .mp-fin-arrow {
  transform: translateX(-3px);
}

/* ==========================================================================
   3. بوابات الأقسام التخصصية (2-Column Department Modules - White Mode)
   ========================================================================== */
.mp-fin-portals-section {
  display: flex;
  flex-direction: column;
  gap: 14px;
}

.mp-fin-section-bar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0 4px;
}

.mp-fin-title-group {
  display: flex;
  align-items: center;
  gap: 10px;
}

.mp-fin-sec-badge {
  font-size: 11px;
  font-weight: 800;
  color: #0284C7;
  background: #F0F9FF;
  border: 1px solid #BAE6FD;
  padding: 2px 8px;
  border-radius: 6px;
}

.mp-fin-sec-title {
  font-size: 15px;
  font-weight: 800;
  color: #0F172A;
  margin: 0;
}

.mp-fin-sec-hint {
  font-size: 12px;
  font-weight: 600;
  color: #64748B;
}

.mp-fin-portals-grid--2col {
  display: grid;
  grid-template-columns: repeat(2, 1fr) !important;
  gap: 18px;
}

.mp-fin-portal-item {
  background: #FFFFFF;
  border: 1px solid #E2E8F0;
  border-radius: 12px;
  padding: 22px;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  box-shadow: 0 2px 8px rgba(15, 23, 42, 0.04);
  transition: all 0.25s cubic-bezier(0.22, 1, 0.36, 1);
  cursor: pointer;
}

.mp-fin-portal-item:hover {
  background: #FFFFFF;
  transform: translateY(-3px);
  box-shadow: 0 12px 24px -4px rgba(2, 132, 199, 0.12);
}

.mp-fin-portal--waed:hover {
  border-color: #38BDF8;
}
.mp-fin-portal--femalwaed:hover {
  border-color: #F472B6;
}

.mp-fin-portal-head {
  display: flex;
  align-items: center;
  gap: 14px;
  margin-bottom: 12px;
}

.mp-fin-p-icon {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 44px;
  height: 44px;
  border-radius: 10px;
  flex-shrink: 0;
}
.mp-fin-p-icon svg {
  width: 24px;
  height: 24px;
}

.mp-fin-p-icon--sky {
  background: #F0F9FF;
  color: #0284C7;
  border: 1px solid #BAE6FD;
}
.mp-fin-p-icon--rose {
  background: #FFF1F2;
  color: #E11D48;
  border: 1px solid #FECDD3;
}

.mp-fin-p-titles {
  display: flex;
  flex-direction: column;
}

.mp-fin-p-cat {
  font-size: 11.5px;
  font-weight: 700;
  color: #0284C7;
}
.mp-fin-portal--femalwaed .mp-fin-p-cat {
  color: #E11D48;
}

.mp-fin-p-name {
  font-size: 17px;
  font-weight: 800;
  color: #0F172A;
  margin: 2px 0 0 0;
}

.mp-fin-p-desc {
  font-size: 13px;
  line-height: 1.7;
  color: #64748B;
  margin: 0 0 16px 0;
  min-height: 44px;
}

.mp-fin-portal-action {
  display: flex;
  align-items: center;
  justify-content: space-between;
  font-size: 13px;
  font-weight: 700;
  color: #334155;
  border-top: 1px solid #F1F5F9;
  padding-top: 12px;
  transition: color 0.2s ease;
}

.mp-fin-act-btn {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 26px;
  height: 26px;
  border-radius: 6px;
  background: #F0F9FF;
  color: #0284C7;
  font-size: 14px;
  transition: all 0.2s ease;
}

.mp-fin-portal-item:hover .mp-fin-portal-action {
  color: #0284C7;
}
.mp-fin-portal-item:hover .mp-fin-act-btn {
  background: #0284C7;
  color: #FFFFFF;
  transform: translateX(-3px);
}

/* ==========================================================================
   4. التذييل والوصول السريع للسجلات (Classic Footer Navigation - White Mode)
   ========================================================================== */
.mp-fin-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  padding-top: 20px;
  border-top: 1px solid #E2E8F0;
  flex-wrap: wrap;
}

.mp-fin-footer-label {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 12.5px;
  font-weight: 700;
  color: #0284C7;
}

.mp-fin-label-dot {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: #0284C7;
}

.mp-fin-footer-nav {
  display: flex;
  align-items: center;
  gap: 12px;
  flex-wrap: wrap;
}

.mp-fin-link {
  font-size: 13px;
  font-weight: 700;
  color: #64748B;
  transition: all 0.2s ease;
  cursor: pointer;
}

.mp-fin-link:hover {
  color: #0284C7;
}

.mp-fin-sep {
  color: #CBD5E1;
  font-size: 11px;
}

/* ==========================================================================
   التجاوب للشاشات المختلفة (Responsive Architecture)
   ========================================================================== */
@media (max-width: 1024px) {
  .mp-fin-metrics-grid {
    grid-template-columns: 1fr;
  }
  .mp-fin-portals-grid--2col {
    grid-template-columns: 1fr !important;
  }
}

@media (max-width: 768px) {
  .mp-fin-wrapper {
    padding: 24px 18px;
    gap: 22px;
  }
  .mp-fin-header {
    flex-direction: column;
    align-items: flex-start;
  }
  .mp-fin-header__brand {
    flex-direction: column;
    align-items: flex-start;
    gap: 14px;
  }
  .mp-fin-logo {
    height: 64px;
  }
  .mp-fin-header__meta {
    width: 100%;
    flex-direction: column;
    align-items: stretch;
  }
  .mp-fin-platform-btn {
    justify-content: center;
  }
  .mp-fin-footer {
    flex-direction: column;
    align-items: flex-start;
    gap: 10px;
  }
}

script:
//========================================
//      AWQAF PREMIUM HERO
//========================================

const greetingElement = root_element.querySelector("#hero-greeting");
const userElement = root_element.querySelector("#user-name");
const timeElement = root_element.querySelector("#hero-time");
const dateElement = root_element.querySelector("#hero-date");

//========================================
// اسم المستخدم
//========================================

let fullName = "";

if (frappe.session && frappe.session.user_fullname) {
    fullName = frappe.session.user_fullname;
} else if (frappe.boot && frappe.boot.user && frappe.boot.user.full_name) {
    fullName = frappe.boot.user.full_name;
} else if (frappe.session && frappe.session.user) {
    fullName = frappe.session.user;
}

userElement.textContent = fullName || "المستخدم";

//========================================
// الأشهر والأيام
//========================================

const months = [
    "يناير",
    "فبراير",
    "مارس",
    "أبريل",
    "مايو",
    "يونيو",
    "يوليو",
    "أغسطس",
    "سبتمبر",
    "أكتوبر",
    "نوفمبر",
    "ديسمبر"
];

const days = [
    "الأحد",
    "الإثنين",
    "الثلاثاء",
    "الأربعاء",
    "الخميس",
    "الجمعة",
    "السبت"
];

//========================================
// تحديث الوقت
//========================================

function updateClock() {

    const now = new Date();

    let hour = now.getHours();
    let minute = String(now.getMinutes()).padStart(2, "0");
    let second = String(now.getSeconds()).padStart(2, "0");

    let displayHour = String(hour).padStart(2, "0");

    timeElement.textContent =
        `${displayHour}:${minute}:${second}`;

    dateElement.innerHTML =
        `${days[now.getDay()]}<br>${now.getDate()} ${months[now.getMonth()]} ${now.getFullYear()}`;

    //------------------------------------
    // الترحيب حسب الوقت
    //------------------------------------

    let greeting = "";

    if (hour >= 5 && hour < 12) {

        greeting = "🌅 صباح الخير";

    }

    else if (hour >= 12 && hour < 17) {

        greeting = "☀️ طاب يومكم";

    }

    else if (hour >= 17 && hour < 21) {

        greeting = "🌇 مساء الخير";

    }

    else {

        greeting = "🌙 أسعد الله مساءكم";

    }

    greetingElement.textContent = greeting;

}

updateClock();

setInterval(updateClock, 1000);

//========================================
// تأثير بسيط عند تحريك الماوس
//========================================

const hero = root_element.querySelector(".awqaf-premium");

hero.addEventListener("mousemove", function(e) {

    const rect = hero.getBoundingClientRect();

    const x = e.clientX - rect.left;

    const y = e.clientY - rect.top;

    hero.style.backgroundPosition =
        `${50 + (x - rect.width / 2) / 40}% ${50 + (y - rect.height / 2) / 40}%`;

});

hero.addEventListener("mouseleave", function() {

    hero.style.backgroundPosition = "center";

});

