    flex-direction: column;
    align-items: flex-start;
    gap: 10px;
    padding: 16px 18px;
  }
  .tq-alert-arrow {
    display: none;
  }
}

@media (max-width: 400px) {
  .tq-actions__grid,
  .tq-actions__grid--3 {
    grid-template-columns: 1fr;
  }
  .tq-hero {
    padding: 24px 18px;
  }
  .tq-hero__title {
    font-size: 20px;
  }
}

