  font-weight: 900;
  color: var(--tq-ink);
  margin: 0 0 var(--tq-space-2) 0;
  line-height: 1.25;
}

.twd-header__subtitle {
  font-size: 0.86rem;
  font-weight: 500;
  color: var(--tq-ink-faint);
  margin: 0;
  line-height: 1.6;
}

.twd-header__seal {
