  z-index: 2;
  display: flex;
  align-items: center;
  justify-content: center;
  width: 54px;
  height: 54px;
  border-radius: var(--tq-radius-md);
  background: var(--tq-accent-subtle);
  border: 1px solid var(--tq-accent-border);
  color: var(--tq-accent);
  flex-shrink: 0;
}

.twd-header__seal svg {
  width: 28px;
  height: 28px;
}

