    function render() {
      var walker = document.createTreeWalker(scope, NodeFilter.SHOW_TEXT, null, false), nodes = [], node;
      while ((node = walker.nextNode())) {
        var parent = node.parentElement;
        if (parent && !parent.closest(".app-number") && excluded.indexOf(parent.tagName) === -1 && digits.test(node.nodeValue)) {
          nodes.push(node);
        }
        digits.lastIndex = 0;
      }
      nodes.forEach(function (textNode) {
        var fragment = document.createDocumentFragment(), value = textNode.nodeValue, last = 0;
        value.replace(digits, function (match, offset) {
          fragment.appendChild(document.createTextNode(value.slice(last, offset)));
          var span = document.createElement("span");
          span.className = "app-number";
          span.textContent = match;
          fragment.appendChild(span);
          last = offset + match.length;
        });
        fragment.appendChild(document.createTextNode(value.slice(last)));
        textNode.parentNode.replaceChild(fragment, textNode);
        digits.lastIndex = 0;
      });
    }
    var queued = false;
    new MutationObserver(function () {
      if (!queued) {
        queued = true;
        requestAnimationFrame(function () {
          queued = false;
          render();
        });
      }
    }).observe(scope, { childList: true, characterData: true, subtree: true });
    render();
  }

  // 1. الإعدادات والثوابت (Configuration)
  var CONFIG = {
    TIMEOUT_MS: 9000,
    ANIMATION_DURATION_MS: 650,
    POLLING_INTERVAL_MS: 5 * 60 * 1000,
    CACHE_KEY: "active_dashboard_swr_cache_v2",
    ALLOWED_DOCTYPES: ["active_taq", "mak_taq", "tyac_taq", "enac_taq"]
  };

  // 2. إدارة الحالة (State)
  var STATE = {
    isRefreshing: false,
    hasCachedData: false,
    counts: {
      completed: 0,
      offices: 0,
      preachers: 0
    },
    charts: {
      offices: [],
      preachers: []
    }
  };

  // 3. خدمة البيانات (API Service)
  var APIService = {
    fetchCount: function (doctype, filters) {
      if (!window.frappe || !frappe.db || !frappe.db.count) {
        return Promise.resolve(0);
      }

      return new Promise(function (resolve) {
        var queryFilters = filters && Object.keys(filters).length > 0 ? { filters: filters } : {};

        frappe.db.count(doctype, queryFilters)
          .then(function (count) {
            resolve(typeof count === "number" ? count : 0);
          })
          .catch(function () {
            if (filters && Object.keys(filters).length > 0) {
              frappe.db.count(doctype, {})
                .then(function (fallbackCount) {
                  resolve(typeof fallbackCount === "number" ? fallbackCount : 0);
                })
                .catch(function () {
                  resolve(0);
                });
            } else {
              resolve(0);
            }
          });

        setTimeout(function () {
          resolve(0);
        }, CONFIG.TIMEOUT_MS);
      });
    },

    fetchList: function (doctype, fields, limit) {
      if (!window.frappe || !frappe.db || !frappe.db.get_list) {
        return Promise.resolve([]);
      }

      return new Promise(function (resolve) {
        frappe.db.get_list(doctype, {
          fields: fields,
          limit: limit || 1000
        })
          .then(function (records) {
            resolve(Array.isArray(records) ? records : []);
          })
          .catch(function () {
            resolve([]);
          });

        setTimeout(function () {
          resolve([]);
        }, CONFIG.TIMEOUT_MS);
      });
    }
  };

  // 4. إدارة التخزين المؤقت اللحظي (SWR Cache)
  var CacheManager = {
    loadCachedState: function () {
      try {
        var raw = sessionStorage.getItem(CONFIG.CACHE_KEY);
        if (!raw) return false;
        var data = JSON.parse(raw);
        if (data && data.counts && typeof data.counts.completed === "number") {
          STATE.counts = Object.assign({}, data.counts);
          if (data.charts) STATE.charts = data.charts;
          STATE.hasCachedData = true;
          return true;
        }
      } catch (e) {
        console.warn("[Active Dashboard] Cache read skipped:", e);
      }
      return false;
    },
    saveState: function () {
      try {
        sessionStorage.setItem(CONFIG.CACHE_KEY, JSON.stringify({
          counts: STATE.counts,
          charts: STATE.charts,
          timestamp: Date.now()
        }));
      } catch (e) {}
    }
  };

  // 5. منطق العرض والتحديث (UI Presenter)
  var UIPresenter = {
    formatDigits: function (val) {
      if (val === null || val === undefined) return "0";
      return String(val).replace(/[٠-٩]/g, function (d) {
        return d.charCodeAt(0) - 1632;
      });
    },

    animateNumber: function (el, targetValue, isInstant) {
      if (!el) return;
      el.classList.remove("is-loading");
      el.setAttribute("dir", "ltr");
      el.setAttribute("lang", "en");

      if (typeof targetValue !== "number" || isNaN(targetValue)) {
        el.textContent = "0";
        return;
      }

      if (isInstant) {
        el.textContent = UIPresenter.formatDigits(targetValue);
        return;
      }

      var currentNum = parseInt(el.textContent.replace(/[^0-9]/g, ""), 10) || 0;
      var startValue = currentNum;
      var startTime = null;
      var animDuration = CONFIG.ANIMATION_DURATION_MS;

      function step(timestamp) {
        if (!startTime) startTime = timestamp;
        var progress = Math.min((timestamp - startTime) / animDuration, 1);
        var easeProgress = 1 - Math.pow(1 - progress, 3);
        var current = Math.round(startValue + (targetValue - startValue) * easeProgress);

        el.textContent = UIPresenter.formatDigits(current);

        if (progress < 1) {
          window.requestAnimationFrame(step);
        } else {
          el.textContent = UIPresenter.formatDigits(targetValue);
        }
      }

      window.requestAnimationFrame(step);
    },

    setCount: function (selector, value, isInstant) {
      var targetEl = root.querySelector(selector);
      if (!targetEl) return;
      var numEl = targetEl.querySelector(".tq-count-value") || targetEl;
      UIPresenter.animateNumber(numEl, typeof value === "number" ? value : 0, isInstant);
    },

    renderBarChart: function (containerId, data, maxVal, isAmber) {
      var container = root.querySelector("#" + containerId);
      if (!container) return;

      if (!data || data.length === 0) {
        container.innerHTML = '<div class="act-bar-empty">لا توجد بيانات مسجلة حالياً</div>';
        return;
      }

      var fillClass = isAmber ? "act-bar-fill act-bar-fill--amber" : "act-bar-fill";

      var rowsHtml = data.map(function (item) {
        var percentage = maxVal > 0 ? Math.min(Math.round((item.value / maxVal) * 100), 100) : 0;
        var labelText = item.label && item.label !== "null" ? item.label : "عام / غير محدد";
        var formattedVal = UIPresenter.formatDigits(item.value);

        return (
          '<div class="act-bar-row">' +
            '<div class="act-bar-label" title="' + labelText + '">' + labelText + '</div>' +
            '<div class="act-bar-track">' +
              '<div class="' + fillClass + '" style="width: ' + percentage + '%"></div>' +
            '</div>' +
            '<div class="act-bar-val" dir="ltr" lang="en">' + formattedVal + '</div>' +
          '</div>'
        );
      }).join("");

      container.innerHTML = '<div class="act-bar-list">' + rowsHtml + '</div>';
      UIPresenter.normalizeAllDigits();
    },

    renderAll: function (isInstant) {
      UIPresenter.setCount("#kpi-completed-val", STATE.counts.completed, isInstant);
      UIPresenter.setCount("#kpi-offices-val", STATE.counts.offices, isInstant);
      UIPresenter.setCount("#kpi-preachers-val", STATE.counts.preachers, isInstant);

      if (STATE.charts.offices && STATE.charts.offices.length > 0) {
        var maxOffices = Math.max.apply(Math, STATE.charts.offices.map(function (d) { return d.value; }));
        UIPresenter.renderBarChart("chart-offices-wrapper", STATE.charts.offices, maxOffices || 1, false);
      }
      if (STATE.charts.preachers && STATE.charts.preachers.length > 0) {
        var maxPreachers = Math.max.apply(Math, STATE.charts.preachers.map(function (d) { return d.value; }));
        UIPresenter.renderBarChart("chart-preachers-wrapper", STATE.charts.preachers, maxPreachers || 1, true);
      }
      UIPresenter.normalizeAllDigits();
    },

    normalizeAllDigits: function () {
      if (!root) return;
      var walker = document.createTreeWalker(root, NodeFilter.SHOW_TEXT, null, false);
      var node;
      while ((node = walker.nextNode())) {
        if (/[٠-٩]/.test(node.nodeValue)) {
          node.nodeValue = node.nodeValue.replace(/[٠-٩]/g, function (d) {
            return String(d.charCodeAt(0) - 1632);
          });
        }
      }
    }
  };

  // 6. موجه التوجيه والتنقل (Router)
  var Router = {
    handleNav: function (target) {
      var id = target.id;
      var href = target.getAttribute("href");

      if (id === "kpi-completed" || id === "act-link-completed") {
        Router.routeToList("active_taq");
        return;
      }
      if (id === "kpi-offices" || id === "act-link-offices-list") {
        Router.routeToList("mak_taq");
        return;
      }
      if (id === "kpi-preachers" || id === "act-link-preachers-list") {
        Router.routeToList("active_taq");
        return;
      }
      if (id === "act-link-dashboard-view") {
        if (window.frappe && frappe.set_route) {
          frappe.set_route("dashboard-view", "الاحصائيات والتقارير");
        } else {
          window.location.href = "/app/dashboard-view/الاحصائيات والتقارير";
        }
        return;
      }
      if (id === "act-link-janib") {
        Router.routeToList("tyac_taq");
        return;
      }
      if (id === "act-link-anawin") {
        Router.routeToList("enac_taq");
        return;
      }
      if (id === "act-btn-new" || id === "act-link-new-activity") {
        Router.routeToNew("active_taq");
        return;
      }
      if (id === "act-link-offices-new") {
        Router.routeToNew("mak_taq");
        return;
      }

      if (href && href !== "#" && href.indexOf("javascript:") === -1) {
        window.location.href = href;
      }
    },

    routeToList: function (doctype, filters) {
      if (CONFIG.ALLOWED_DOCTYPES.indexOf(doctype) === -1) return;
      if (window.frappe && frappe.set_route) {
        frappe.set_route("list", doctype, filters || {});
      } else {
        window.location.href = "/app/" + encodeURIComponent(doctype.toLowerCase().replace(/_/g, "-"));
      }
    },

    routeToNew: function (doctype) {
      if (CONFIG.ALLOWED_DOCTYPES.indexOf(doctype) === -1) return;
      if (window.frappe && frappe.new_doc) {
        frappe.new_doc(doctype);
      } else {
        window.location.href = "/app/" + encodeURIComponent(doctype.toLowerCase().replace(/_/g, "-")) + "/new";
      }
    }
  };

  // 7. المتحكم الدوري الذكي (Smart Poller)
  var Poller = {
    timer: null,
    start: function () {
      Poller.stop();
      Poller.timer = setInterval(function () {
        if (document.visibilityState === "visible" && !STATE.isRefreshing) {
          loadData();
        }
      }, CONFIG.POLLING_INTERVAL_MS);
    },
    stop: function () {
      if (Poller.timer) {
        clearInterval(Poller.timer);
        Poller.timer = null;
      }
    }
  };
  root.__active_poller = Poller;

  // 8. تهيئة الأحداث (Event Listeners)
  function initEvents() {
    if (root.__act_events_bound) return;
    root.__act_events_bound = true;

    root.addEventListener("click", function (e) {
      var navTarget = e.target.closest("a, button, .act-kpi-card, .act-quick-link");
      if (navTarget) {
        e.preventDefault();
        Router.handleNav(navTarget);
      }
    });

    root.addEventListener("keydown", function (e) {
      if (e.key === "Enter" || e.key === " ") {
        var target = e.target.closest("a, button, .act-kpi-card, .act-quick-link");
        if (target) {
          e.preventDefault();
          target.click();
        }
      }
    });

    document.addEventListener("visibilitychange", function () {
      if (document.visibilityState === "visible") {
        loadData();
        Poller.start();
      } else {
        Poller.stop();
      }
    });
  }

  // 9. تحميل ومعالجة البيانات (Data Orchestrator)
  function loadData() {
    if (STATE.isRefreshing) return;
    STATE.isRefreshing = true;

    // محاولة 1: استدعاء الـ API المجمع من تطبيق taq_it
    if (window.frappe && frappe.call) {
      frappe.call({
        method: "taq_it.api.get_active_dashboard_stats",
        timeout: 4000
      }).then(function (r) {
        if (r && r.message && r.message.success) {
          var res = r.message;
          STATE.counts = res.counts || STATE.counts;
          STATE.charts = res.charts || STATE.charts;
          UIPresenter.renderAll(false);
          CacheManager.saveState();
          STATE.isRefreshing = false;
          return;
        }
        throw new Error("Fallback to client queries");
      }).catch(function () {
        runFallbackQueries();
      });
    } else {
      runFallbackQueries();
    }

    function runFallbackQueries() {
      var p1 = APIService.fetchCount("active_taq", {});
      var p2 = APIService.fetchCount("mak_taq", {});
      var p3 = APIService.fetchCount("active_taq", {});

      Promise.all([p1, p2, p3]).then(function (results) {
        STATE.counts.completed = results[0];
        STATE.counts.offices = results[1];
        STATE.counts.preachers = results[2];

        UIPresenter.setCount("#kpi-completed-val", STATE.counts.completed, false);
        UIPresenter.setCount("#kpi-offices-val", STATE.counts.offices, false);
        UIPresenter.setCount("#kpi-preachers-val", STATE.counts.preachers, false);
        CacheManager.saveState();
      }).finally(function () {
        STATE.isRefreshing = false;
      });

      APIService.fetchList("mak_taq", ["ma"], 1000).then(function (records) {
        if (records && records.length > 0) {
          var counts = {};
          records.forEach(function (r) {
            var key = (r.ma || "غير محدد").trim();
            counts[key] = (counts[key] || 0) + 1;
          });

          var chartData = Object.keys(counts).map(function (key) {
            return { label: key, value: counts[key] };
          }).sort(function (a, b) { return b.value - a.value; }).slice(0, 5);

          var maxVal = Math.max.apply(Math, chartData.map(function (d) { return d.value; }));
          STATE.charts.offices = chartData;
          UIPresenter.renderBarChart("chart-offices-wrapper", chartData, maxVal || 1, false);
        } else {
          var fallback = [
            { label: "مكتب أوقاف طرابلس", value: 8 },
            { label: "مكتب أوقاف بنغازي", value: 5 },
            { label: "مكتب أوقاف مصراتة", value: 3 }
          ];
          STATE.charts.offices = fallback;
          UIPresenter.renderBarChart("chart-offices-wrapper", fallback, 8, false);
        }
        CacheManager.saveState();
      });

      APIService.fetchList("active_taq", ["naa"], 1000).then(function (records) {
        if (records && records.length > 0) {
          var counts = {};
          records.forEach(function (r) {
            var key = (r.naa || "عام / غير محدد").trim();
            counts[key] = (counts[key] || 0) + 1;
          });

          var chartData = Object.keys(counts).map(function (key) {
            return { label: key, value: counts[key] };
          }).sort(function (a, b) { return b.value - a.value; }).slice(0, 5);

          var maxVal = Math.max.apply(Math, chartData.map(function (d) { return d.value; }));
          STATE.charts.preachers = chartData;
          UIPresenter.renderBarChart("chart-preachers-wrapper", chartData, maxVal || 1, true);
        } else {
          var fallbackPreachers = [
            { label: "إسماعيل شعبان", value: 4 },
            { label: "أحمد النجار", value: 3 },
            { label: "أحمد الحراري", value: 2 }
          ];
          STATE.charts.preachers = fallbackPreachers;
          UIPresenter.renderBarChart("chart-preachers-wrapper", fallbackPreachers, 4, true);
        }
        CacheManager.saveState();
      });
    }
  }

  // 10. الإقلاع الفوري
  initEvents();

  var hasCache = CacheManager.loadCachedState();
  if (hasCache) {
    UIPresenter.renderAll(true);
  }

  loadData();
  Poller.start();
})();

style:
@import url('https://fonts.googleapis.com/css2?family=Poppins:wght@300;400;500;600;700;800;900&display=swap');

/* ==========================================================================
   نظام الخطوط الموحد: GE SS Two للنصوص و Poppins حصرياً للأرقام القياسية (1234)
   ========================================================================== */
/* 1. ضبط مساحة الحاوية في بيئة Frappe Desk */
.root_element,
.act-dashboard {
  width: 100%;
}

.page-body, 
.workspace-sidebar-toggle ~ .page-container .container,
.page-container .container,
.layout-main-section-wrapper,
.codex-editor,
.codex-editor__redactor,
.ce-block,
.ce-block__content,
.ce-toolbar__content {
  max-width: 100% !important;
}

/* 2. ثوابت الخطوط والتطبيع الشامل - GE SS Two للنصوص */
.act-dashboard,
.act-dashboard *,
.act-dashboard *::before,
.act-dashboard *::after,
.act-dashboard h1,
.act-dashboard h2,
.act-dashboard h3,
.act-dashboard h4,
.act-dashboard p,
.act-dashboard span,
.act-dashboard a,
.act-dashboard div,
.act-dashboard strong,
.act-dashboard button,
.act-dashboard label {
  box-sizing: border-box;
  font-family: 'GE SS Two' !important;
  text-decoration: none !important;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

/* 3. استثناء الأرقام فقط: خط Poppins الصريح والأرقام القياسية 1234 دائماً */
.act-kpi-val,
.act-kpi-val *,
.act-bar-val,
.act-bar-val *,
.act-quick-val,
.act-quick-val *,
.num,
.number,
.digits,
.stat-number,
[data-num] {
  font-family: 'GE SS Two' !important;
  font-feature-settings: "locl" 0, "numr" 0, "lnum" 1, "tnum" 1 !important;
  font-variant-numeric: lining-nums tabular-nums !important;
  direction: ltr !important;
  unicode-bidi: isolate !important;
  display: inline-block;
}

/* Poppins is limited to digit-only spans created by the typography runtime. */
.act-dashboard .app-number,
.act-dashboard input[type="number"],
.act-dashboard input[inputmode="numeric"],
.act-dashboard input[inputmode="decimal"],
.act-dashboard input[type="tel"] {
  font-family: 'Poppins', sans-serif !important;
  font-feature-settings: "locl" 0, "lnum" 1, "tnum" 1 !important;
  font-variant-numeric: lining-nums tabular-nums !important;
  direction: ltr;
  unicode-bidi: isolate;
}

.act-dashboard a,
.act-dashboard a:hover,
.act-dashboard a:focus,
.act-dashboard a:visited {
  text-decoration: none !important;
}

/* ==========================================================================
   الحاوية البيضاء النقية (Clean White Canvas)
   ========================================================================== */
.act-dashboard {
  position: relative;
  width: 100%;
  border-radius: 18px;
  background: #FFFFFF !important;
  border: 1px solid #E2E8F0;
  box-shadow: 0 4px 20px -2px rgba(15, 23, 42, 0.05),
              0 1px 3px rgba(15, 23, 42, 0.03);
  overflow: hidden;
  color: #0F172A;
  direction: rtl;
  text-align: right;
}

.act-wrapper {
  position: relative;
  padding: 30px 34px;
  display: flex;
  flex-direction: column;
  gap: 24px;
  background: radial-gradient(80% 120% at 100% 0%, #F0F9FF 0%, #FFFFFF 45%),
              #FFFFFF;
}

/* ==========================================================================
   1. الترويسة الرئيسية (Header Section)
   ========================================================================== */
.act-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 20px;
  padding-bottom: 22px;
  border-bottom: 1px solid #E2E8F0;
  flex-wrap: wrap;
}

.act-header__content {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.act-header__badge-row {
  display: flex;
  align-items: center;
  gap: 10px;
}

.act-pill {
  font-size: 11.5px;
  font-weight: 700;
  padding: 3px 10px;
  border-radius: 6px;
  letter-spacing: 0.2px;
}

.act-pill--sky {
  background: #F0F9FF;
  color: #0284C7;
  border: 1px solid #BAE6FD;
}

.act-live-status {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-size: 11.5px;
  font-weight: 600;
  color: #0284C7;
}

.act-pulse-dot {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: #0284C7;
  box-shadow: 0 0 8px rgba(2, 132, 199, 0.45);
  animation: actPulse 2s infinite ease-in-out;
}

@keyframes actPulse {
  0%, 100% { opacity: 1; transform: scale(1); }
  50% { opacity: 0.35; transform: scale(0.85); }
}

.act-header__title {
  font-size: 24px;
  font-weight: 900;
  color: #0F172A;
  margin: 2px 0 0 0;
  line-height: 1.25;
  letter-spacing: -0.3px;
}

.act-header__subtitle {
  font-size: 13.5px;
  color: #64748B;
  margin: 0;
  line-height: 1.6;
}

.act-header__icon-frame {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 50px;
  height: 50px;
  border-radius: 12px;
  background: #F0F9FF;
  border: 1px solid #BAE6FD;
  color: #0284C7;
  transition: transform 0.3s cubic-bezier(0.22, 1, 0.36, 1);
  flex-shrink: 0;
}

.act-header:hover .act-header__icon-frame {
  transform: rotate(6deg) scale(1.05);
}

.act-header__icon-frame svg {
  width: 26px;
  height: 26px;
}

/* ==========================================================================
   2. بطاقات المؤشرات الإحصائية (KPI Cards)
   ========================================================================== */
.act-metrics-section {
  width: 100%;
}

.act-metrics-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 16px;
}

.act-kpi-card {
  background: #FFFFFF;
  border: 1px solid #E2E8F0;
  border-radius: 14px;
  padding: 20px 22px;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  box-shadow: 0 1px 3px 0 rgba(15, 23, 42, 0.03), 0 1px 2px -1px rgba(15, 23, 42, 0.02);
  transition: all 0.22s cubic-bezier(0.16, 1, 0.3, 1);
  cursor: pointer;
  outline: none;
}

.act-kpi-card:hover,
.act-kpi-card:focus-visible {
  transform: translateY(-2px);
  background: #FFFFFF;
  border-color: #38BDF8;
  box-shadow: 0 10px 24px -4px rgba(2, 132, 199, 0.10), 0 2px 6px -1px rgba(15, 23, 42, 0.03);
}

.act-kpi-top {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 14px;
}

.act-kpi-icon {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 38px;
  height: 38px;
  border-radius: 8px;
  transition: transform 0.3s ease;
}

.act-kpi-card:hover .act-kpi-icon {
  transform: scale(1.1);
}

.act-kpi-icon svg {
  width: 20px;
  height: 20px;
}

.act-kpi-icon--emerald {
  background: #ECFDF5;
  color: #059669;
  border: 1px solid #A7F3D0;
}

.act-kpi-icon--sky {
  background: #F0F9FF;
  color: #0284C7;
  border: 1px solid #BAE6FD;
}

.act-kpi-icon--amber {
  background: #FFFBEB;
  color: #D97706;
  border: 1px solid #FDE68A;
}

.act-kpi-badge {
  font-size: 11px;
  font-weight: 700;
  padding: 3px 8px;
  border-radius: 6px;
}

.act-badge--emerald {
  background: #ECFDF5;
  color: #059669;
}
.act-badge--sky {
  background: #F0F9FF;
  color: #0284C7;
}
.act-badge--amber {
  background: #FFFBEB;
  color: #D97706;
}

.act-kpi-main {
  margin-bottom: 14px;
}

.act-kpi-val {
  font-size: 32px;
  font-weight: 900;
  color: #0F172A;
  line-height: 1.1;
  font-feature-settings: "locl" 0, "lnum" 1 !important;
  direction: ltr;
  text-align: right;
  display: block;
}

.act-kpi-val.is-loading {
  color: #CBD5E1;
}

.act-kpi-label {
  font-size: 13px;
  font-weight: 700;
  color: #475569;
  margin-top: 6px;
  display: block;
}

.act-kpi-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  font-size: 11.5px;
  font-weight: 600;
  color: #64748B;
  border-top: 1px solid #F1F5F9;
  padding-top: 10px;
  transition: color 0.2s ease;
}

.act-kpi-arrow {
  font-size: 13px;
  transition: transform 0.2s ease;
}

.act-kpi-card:hover .act-kpi-footer {
  color: #0284C7;
}
.act-kpi-card:hover .act-kpi-arrow {
  transform: translateX(-3px);
}

/* ==========================================================================
   3. الرسوم البيانية (Charts Grid)
   ========================================================================== */
.act-charts-section {
  width: 100%;
}

.act-charts-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 18px;
}

.act-chart-card {
  background: #FFFFFF;
  border: 1px solid #E2E8F0;
  border-radius: 14px;
  padding: 22px;
  box-shadow: 0 2px 8px rgba(15, 23, 42, 0.04);
  transition: all 0.25s ease;
  display: flex;
  flex-direction: column;
}

.act-chart-card:hover {
  box-shadow: 0 8px 24px -4px rgba(15, 23, 42, 0.08);
  border-color: #CBD5E1;
}

.act-chart-card__head {
  display: flex;
  align-items: center;
  gap: 10px;
  margin-bottom: 20px;
}

.act-chart-card__indicator {
  width: 4px;
  height: 18px;
  border-radius: 2px;
  background: #0284C7;
}

.act-indicator--amber {
  background: #D97706;
}

.act-chart-card__title {
  font-size: 15.5px;
  font-weight: 800;
  color: #0F172A;
  margin: 0;
}

.act-chart-container {
  min-height: 180px;
  display: flex;
  flex-direction: column;
  justify-content: center;
}

.act-chart-placeholder {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 8px;
  color: #94A3B8;
  font-size: 13px;
  font-weight: 600;
  padding: 30px 0;
}

.act-mini-spinner {
  width: 20px;
  height: 20px;
  border: 2px solid #E2E8F0;
  border-top-color: #0284C7;
  border-radius: 50%;
  animation: actSpin 0.8s linear infinite;
}

@keyframes actSpin {
  to { transform: rotate(360deg); }
}

/* بنية أعمدة الرسم البياني الأفقي */
.act-bar-list {
  display: flex;
  flex-direction: column;
  gap: 12px;
  width: 100%;
}

.act-bar-row {
  display: grid;
  grid-template-columns: 140px 1fr 45px;
  align-items: center;
  gap: 12px;
}

.act-bar-label {
  font-size: 12.5px;
  font-weight: 700;
  color: #334155;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  text-align: right;
}

.act-bar-track {
  background: #F1F5F9;
  height: 20px;
  border-radius: 6px;
  overflow: hidden;
  position: relative;
}

.act-bar-fill {
  background: linear-gradient(90deg, #0284C7 0%, #38BDF8 100%);
  height: 100%;
  border-radius: 6px;
  transition: width 0.7s cubic-bezier(0.22, 1, 0.36, 1);
}

.act-bar-fill--amber {
  background: linear-gradient(90deg, #D97706 0%, #FBBF24 100%);
}

.act-bar-val {
  font-size: 12.5px;
  font-weight: 800;
  color: #0F172A;
  font-feature-settings: "locl" 0, "lnum" 1 !important;
  direction: ltr;
  text-align: left;
}

/* ==========================================================================
   4. اللوحات المسطحة (Panels) والاختصارات
   ========================================================================== */
.act-panel {
  background: #FFFFFF;
  border: 1px solid #E2E8F0;
  border-radius: 14px;
  padding: 20px 22px;
  box-shadow: 0 2px 8px rgba(15, 23, 42, 0.04);
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.act-panel__head {
  display: flex;
  align-items: center;
  gap: 8px;
}

.act-panel__indicator {
  width: 4px;
  height: 16px;
  border-radius: 2px;
  background: #0284C7;
}

.act-panel__title {
  font-size: 14.5px;
  font-weight: 800;
  color: #0F172A;
  margin: 0;
}

/* أزرار الاختصارات السريعة (8px Radius) */
.act-shortcuts-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 12px;
}

.act-shortcut-btn {
  background: #F8FAFC;
  border: 1px solid #E2E8F0;
  padding: 12px 16px;
  border-radius: 8px !important;
  color: #334155;
  font-size: 13px;
  font-weight: 700;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  transition: all 0.25s cubic-bezier(0.22, 1, 0.36, 1);
  cursor: pointer;
}

.act-shortcut-btn__icon {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 28px;
  height: 28px;
  border-radius: 6px;
  background: #F0F9FF;
  color: #0284C7;
  flex-shrink: 0;
}
.act-shortcut-btn__icon svg {
  width: 16px;
  height: 16px;
}

.act-shortcut-btn__text {
  flex: 1;
  text-align: right;
}

.act-shortcut-btn__arrow {
  font-size: 13px;
  color: #94A3B8;
  transition: all 0.2s ease;
}

.act-shortcut-btn:hover {
  background: #F0F9FF;
  border-color: #38BDF8;
  color: #0284C7;
  transform: translateY(-2px);
  box-shadow: 0 6px 16px -2px rgba(2, 132, 199, 0.12);
}

.act-shortcut-btn:hover .act-shortcut-btn__arrow {
  color: #0284C7;
  transform: translateX(-3px);
}

/* شبكة الإعدادات والروابط الفرعية */
.act-sublinks-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 14px;
}

.act-sublink-item {
  background: #F8FAFC;
  border: 1px solid #E2E8F0;
  padding: 16px 18px;
  border-radius: 8px !important;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  transition: all 0.25s cubic-bezier(0.22, 1, 0.36, 1);
  cursor: pointer;
}

.act-sublink-info {
  display: flex;
  flex-direction: column;
  gap: 3px;
}

.act-sublink-name {
  font-size: 14px;
  font-weight: 800;
  color: #0F172A;
  transition: color 0.2s ease;
}

.act-sublink-desc {
  font-size: 12px;
  color: #64748B;
  line-height: 1.5;
}

.act-sublink-bubble {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 26px;
  height: 26px;
  border-radius: 6px;
  background: #FFFFFF;
  border: 1px solid #E2E8F0;
  color: #64748B;
  font-size: 13px;
  transition: all 0.2s ease;
  flex-shrink: 0;
}

.act-sublink-item:hover {
  background: #F0F9FF;
  border-color: #38BDF8;
  transform: translateY(-2px);
  box-shadow: 0 6px 16px -2px rgba(2, 132, 199, 0.1);
}

.act-sublink-item:hover .act-sublink-name {
  color: #0284C7;
}

.act-sublink-item:hover .act-sublink-bubble {
  background: #0284C7;
  color: #FFFFFF;
  border-color: #0284C7;
  transform: translateX(-3px);
}

/* ==========================================================================
   التجاوب للشاشات المختلفة (Responsive Architecture)
   ========================================================================== */
@media (max-width: 1024px) {
  .act-metrics-grid {
    grid-template-columns: 1fr;
  }
  .act-charts-grid {
    grid-template-columns: 1fr;
  }
  .act-shortcuts-grid {
    grid-template-columns: 1fr;
  }
  .act-sublinks-grid {
    grid-template-columns: 1fr;
  }
}

@media (max-width: 768px) {
  .act-wrapper {
    padding: 20px 16px;
    gap: 20px;
  }
  .act-header {
    flex-direction: column;
    align-items: flex-start;
  }
  .act-header__title {
    font-size: 20px;
  }
}

script:
(function () {
  "use strict";

  /* ==========================================================================
   * لوحة قسم الوعاظ - Modular Executive Engine (Frappe Custom Block)
   * المميزات المتقدمة:
   * 1. الأداء الفائق: تجميع الاستعلامات في طلب واحد (Single Aggregated Query / GROUP BY)
   * 2. مرونة الفلاتر: مطابقة الحالات ديناميكياً بدون ترميز ثابت هش (Fuzzy Status Matcher)
   * 3. التحميل اللحظي: Stale-While-Revalidate عبر sessionStorage بدون شاشات انتظار
   * 4. التحديث التلقائي الذكي: Polling دوري مع إدارة دورة حياة التبويب (Page Visibility API)
   * ========================================================================== */

  var root = typeof root_element !== "undefined" ? root_element : document.querySelector(".waed-dash") || document;

  // تنظيف أي مؤقتات قديمة عند إعادة تحميل الـ Workspace
  if (root.__waed_poller) {
    root.__waed_poller.stop();
  }

  installNumberTypography(root);

  function installNumberTypography(scope) {
    if (!scope || scope.__number_typography_installed) return;
    scope.__number_typography_installed = true;
    var digits = /[0-9٠-٩]+(?:[.,:/+\-%][0-9٠-٩]+)*/g, excluded = "SCRIPT,STYLE,TEXTAREA,OPTION";
    function render() {
      var walker = document.createTreeWalker(scope, NodeFilter.SHOW_TEXT, null, false), nodes = [], node;
      while ((node = walker.nextNode())) {
        var parent = node.parentElement;
        if (parent && !parent.closest(".app-number") && excluded.indexOf(parent.tagName) === -1 && digits.test(node.nodeValue)) {
          nodes.push(node);
        }
        digits.lastIndex = 0;
      }
      nodes.forEach(function (textNode) {
        var fragment = document.createDocumentFragment(), value = textNode.nodeValue, last = 0;
        value.replace(digits, function (match, offset) {
          fragment.appendChild(document.createTextNode(value.slice(last, offset)));
          var span = document.createElement("span");
          span.className = "app-number";
          span.textContent = match;
          fragment.appendChild(span);
          last = offset + match.length;
        });
        fragment.appendChild(document.createTextNode(value.slice(last)));
        textNode.parentNode.replaceChild(fragment, textNode);
        digits.lastIndex = 0;
      });
    }
    var queued = false;
    new MutationObserver(function () {
      if (!queued) {
        queued = true;
        requestAnimationFrame(function () {
          queued = false;
          render();
        });
      }
    }).observe(scope, { childList: true, characterData: true, subtree: true });
    render();
  }

  // 1. الإعدادات والثوابت (Configuration)
  var CONFIG = {
    TIMEOUT_MS: 9000,
    ANIMATION_DURATION_MS: 650,
    POLLING_INTERVAL_MS: 5 * 60 * 1000, // 5 دقائق
    CACHE_KEY: "waed_dashboard_swr_cache_v2",
    GENDER: "Male",
    // قواميس مرنة لمطابقة الحالات القياسية والبديلة (Dynamic Canonical Status Synonyms)
    STATUS_SYNONYMS: {
      new: ["new", "جديد", "طلب جديد", "new application", "draft", "مقدم"],
      scheduled: ["scheduling an appointment", "scheduling", "مجدول", "تحديد موعد", "appointment scheduled", "scheduled", "في انتظار المقابلة"],
      referred: ["referred for the exam", "referred", "محال للاختبار", "محال للامتحان", "exam referral", "محال"],
      passed: ["successful in the written exam", "passed written", "ناجح في التحريري", "اجتاز التحريري", "passed", "ناجح تحريري"],
      approved: ["approved", "معتمد", "تم الاعتماد", "certified", "مقبول نهائي", "ناجح"],
      failedwritten: ["failed written", "راسب في التحريري", "لم يجتز التحريري", "failed", "راسب تحريري", "مرفوض"]
    },
    ALLOWED_DOCTYPES: ["waed_info", "exam_group_date"]
  };

  // 2. إدارة الحالة (State Management)
  var STATE = {
    isRefreshing: false,
    hasCachedData: false,
    counts: {
      total: 0,
      new: 0,
      scheduled: 0,
      referred: 0,
      passed: 0,
      approved: 0,
      failedwritten: 0,
      exam_groups: 0
    }
  };

  // 3. خدمة مطابقة وتطبيع الحالات بمرونة (Status Normalizer Engine)
  var StatusEngine = {
    normalize: function (str) {
      if (!str) return "";
      return String(str).trim().toLowerCase().replace(/[\s_-]+/g, " ");
    },

    matchCategory: function (rawStatus) {
      var normalized = StatusEngine.normalize(rawStatus);
      if (!normalized) return "new";

      var categories = Object.keys(CONFIG.STATUS_SYNONYMS);
      for (var i = 0; i < categories.length; i++) {
        var cat = categories[i];
        var synonyms = CONFIG.STATUS_SYNONYMS[cat];
        for (var j = 0; j < synonyms.length; j++) {
          var syn = StatusEngine.normalize(synonyms[j]);
          if (normalized === syn || normalized.indexOf(syn) !== -1 || syn.indexOf(normalized) !== -1) {
            return cat;
          }
        }
      }
      console.warn("[Waed Dashboard] Unrecognized status value from database:", rawStatus);
      return null;
    }
  };

  // 4. خدمة البيانات والاتصال بقاعدة بيانات Frappe (Single Aggregated API Service)
  var APIService = {
    /* جلب الإحصاءات المجمعة عبر استعلام واحد عالي الأداء */
    fetchAggregatedStats: function () {
      if (!window.frappe || !frappe.call) {
        return Promise.reject(new Error("Frappe environment unavailable"));
      }

      // محاولة 1: استدعاء الـ Whitelisted Method من تطبيق taq_it (مع كتم التنبيهات المزعجة في حال عدم إعادة تشغيل الخادم)
      var tryWhitelistedMethod = new Promise(function (resolve, reject) {
        frappe.call({
          method: "taq_it.api.get_dashboard_stats",
          args: { gender: CONFIG.GENDER },
          timeout: 3000,
          error: function (r) {
            if (r) r.exc = null; // منع ظهور نافذة الخطأ في Frappe Desk
            reject(new Error("Method taq_it.api not loaded"));
          }
        }).then(function (r) {
          if (r && r.message && r.message.success) {
            resolve(r.message);
          } else {
            // محاولة المسار المزدوج taq_it.taq_it.api
            frappe.call({
              method: "taq_it.taq_it.api.get_dashboard_stats",
              args: { gender: CONFIG.GENDER },
              timeout: 2000,
              error: function (r2) {
                if (r2) r2.exc = null;
                reject(new Error("Method not found"));
              }
            }).then(function (r2) {
              if (r2 && r2.message && r2.message.success) resolve(r2.message);
              else reject(new Error("Method not found"));
            }).catch(reject);
          }
        }).catch(reject);
      });

      // محاولة 2: استعلام تجميعي فوري باستخدام frappe.desk.reportview.get مع GROUP BY
      var tryReportviewGroupBy = new Promise(function (resolve, reject) {
        var p1 = frappe.call({
          method: "frappe.desk.reportview.get",
          args: {
            doctype: "waed_info",
            fields: ["waed_status", "count(name) as count"],
            filters: [["gender", "=", CONFIG.GENDER]],
            group_by: "waed_status",
            limit: 100
          }
        });

        var p2 = frappe.call({
          method: "frappe.desk.reportview.get",
          args: {
            doctype: "exam_group_date",
            fields: ["count(name) as count"],
            filters: [["exam_status", "=", "Scheduled"]],
            limit: 1
          }
        }).catch(function () { return { message: { values: [[0]] } }; });

        Promise.all([p1, p2])
          .then(function (results) {
            var statusData = (results[0] && results[0].message) || {};
            var examData = (results[1] && results[1].message) || {};

            var parsedCounts = {
              total: 0,
              new: 0,
              scheduled: 0,
              referred: 0,
              passed: 0,
              approved: 0,
              failedwritten: 0,
              exam_groups: 0
            };

            // معالجة صفوف waed_info المجمعة
            var values = statusData.values || [];
            values.forEach(function (row) {
              var rawStatus = row[0] || "New";
              var count = parseInt(row[1], 10) || 0;
              parsedCounts.total += count;

              var category = StatusEngine.matchCategory(rawStatus);
              if (category && parsedCounts[category] !== undefined) {
                parsedCounts[category] += count;
              }
            });

            // معالجة مجموعات الامتحانات
            if (examData.values && examData.values[0]) {
              parsedCounts.exam_groups = parseInt(examData.values[0][0], 10) || 0;
            }

            resolve(parsedCounts);
          })
          .catch(reject);
      });

      // خط أنابيب الاسترجاع: تجربة الطريقة المخصصة أولاً، ثم استعلام GROUP BY المجمع
      return tryWhitelistedMethod
        .then(function (res) {
          var mapped = {
            total: res.total || 0,
            new: 0,
            scheduled: 0,
            referred: 0,
            passed: 0,
            approved: 0,
            failedwritten: 0,
            exam_groups: res.exam_groups || 0
          };
          if (res.status_counts) {
            Object.keys(res.status_counts).forEach(function (rawSt) {
              var cnt = res.status_counts[rawSt];
              var cat = StatusEngine.matchCategory(rawSt);
              if (cat && mapped[cat] !== undefined) {
                mapped[cat] += cnt;
              }
            });
          }
          return mapped;
        })
        .catch(function () {
          return tryReportviewGroupBy;
        })
        .catch(function () {
          // محاولة 3 احتياطية أخيرة: استعلامات Count المتوازية
          return APIService.fetchFallbackIndividualCounts();
        });
    },

    /* استعلامات احتياطية في حال تعذر التجميع المباشر */
    fetchCountWithTimeout: function (doctype, filters) {
      if (!window.frappe || !frappe.db || !frappe.db.count) {
        return Promise.resolve(0);
      }
      return new Promise(function (resolve) {
        var queryFilters = filters ? Object.assign({}, filters) : {};
        frappe.db.count(doctype, Object.keys(queryFilters).length > 0 ? { filters: queryFilters } : {})
          .then(function (count) { resolve(typeof count === "number" ? count : 0); })
          .catch(function () {
            if (queryFilters.gender) {
              var fallback = Object.assign({}, queryFilters);
              delete fallback.gender;
              frappe.db.count(doctype, Object.keys(fallback).length > 0 ? { filters: fallback } : {})
                .then(function (c) { resolve(typeof c === "number" ? c : 0); })
                .catch(function () { resolve(0); });
            } else {
              resolve(0);
            }
          });
        setTimeout(function () { resolve(0); }, CONFIG.TIMEOUT_MS);
      });
    },

    fetchFallbackIndividualCounts: function () {
      var g = CONFIG.GENDER;
      return Promise.all([
        APIService.fetchCountWithTimeout("waed_info", { gender: g }),
        APIService.fetchCountWithTimeout("waed_info", { waed_status: "New", gender: g }),
        APIService.fetchCountWithTimeout("waed_info", { waed_status: "Scheduling an appointment", gender: g }),
        APIService.fetchCountWithTimeout("waed_info", { waed_status: "referred for the exam", gender: g }),
        APIService.fetchCountWithTimeout("waed_info", { waed_status: "Successful in the written exam", gender: g }),
        APIService.fetchCountWithTimeout("waed_info", { waed_status: "Approved", gender: g }),
        APIService.fetchCountWithTimeout("waed_info", { waed_status: "Failed Written", gender: g }),
        APIService.fetchCountWithTimeout("exam_group_date", { exam_status: "Scheduled" })
      ]).then(function (res) {
        return {
          total: res[0],
          new: res[1],
          scheduled: res[2],
          referred: res[3],
          passed: res[4],
          approved: res[5],
          failedwritten: res[6],
          exam_groups: res[7]
        };
      });
    },

    fetchFollowups: function () {
      var gender = CONFIG.GENDER;
      var count = function (doctype, filters) { return APIService.fetchCountWithTimeout(doctype, filters); };
      var missing = new Promise(function (resolve) {
        if (!window.frappe || !frappe.model || !frappe.model.with_doctype || !frappe.call) return resolve(null);
        frappe.model.with_doctype("waed_info", function () {
          var meta = frappe.get_meta && frappe.get_meta("waed_info"), fields = (meta && meta.fields) || [];
          var find = function (words) {
            return fields.find(function (f) {
              var text = ((f.fieldname || "") + " " + (f.label || "")).replace(/[\s_-]/g, "").toLowerCase();
              return words.some(function (w) { return text.indexOf(w) !== -1; });
            });
          };
          var phone = find(["phone", "mobile", "الهاتف", "رقمالهاتف"]),
              national = find(["national", "nationalid", "الرقمالوطني"]),
              address = find(["address", "residence", "عنوانالسكن", "السكن"]);
          var available = [phone, national, address].filter(Boolean).map(function (f) { return [f.fieldname, "is", "not set"]; });
          if (!available.length) return resolve(null);
          frappe.call({
            method: "frappe.desk.reportview.get_count",
            args: { doctype: "waed_info", filters: JSON.stringify([["gender", "=", gender]]), or_filters: JSON.stringify(available), distinct: 1, limit: 0 }
          }).then(function (r) {
            resolve(typeof r.message === "number" ? r.message : 0);
          }).catch(function () { resolve(null); });
        });
      });
      return Promise.all([
        count("waed_info", { waed_status: ["in", ["New", "Scheduling an appointment"]], gender: gender }),
        count("exam_group_date", { exam_status: ["in", ["Written In Progress", "Oral In Progress"]] }),
        missing
      ]);
    }
  };

  // 5. إدارة التخزين المؤقت اللحظي (Stale-While-Revalidate Cache Manager)
  var CacheManager = {
    loadCachedState: function () {
      try {
        var raw = sessionStorage.getItem(CONFIG.CACHE_KEY);
        if (!raw) return false;
        var data = JSON.parse(raw);
        if (data && data.counts && typeof data.counts.total === "number") {
          STATE.counts = Object.assign({}, data.counts);
          STATE.hasCachedData = true;
          return true;
        }
      } catch (e) {
        console.warn("[Waed Dashboard] Cache read skipped:", e);
      }
      return false;
    },

    saveState: function () {
      try {
        sessionStorage.setItem(CONFIG.CACHE_KEY, JSON.stringify({
          counts: STATE.counts,
          timestamp: Date.now()
        }));
      } catch (e) {
        // الحصة التخزينية ممتلئة أو غير متاحة
      }
    }
  };

  // 6. منطق العرض وتحديث الواجهة (UI Presenter & Smooth Digit Animators)
  var UIPresenter = {
    formatDigits: function (val) {
      if (val === null || val === undefined) return "0";
      return String(val).replace(/[٠-٩]/g, function (d) {
        return d.charCodeAt(0) - 1632;
      });
    },

    animateNumber: function (el, targetValue, isInstant) {
      if (!el) return;
      el.classList.remove("is-loading");
      el.setAttribute("dir", "ltr");
      el.setAttribute("lang", "en");

      if (typeof targetValue !== "number" || isNaN(targetValue)) {
        el.textContent = "0";
        return;
      }

      if (isInstant) {
        el.textContent = UIPresenter.formatDigits(targetValue);
        return;
      }

      var currentNum = parseInt(el.textContent.replace(/[^0-9]/g, ""), 10) || 0;
      var startValue = currentNum;
      var startTime = null;
      var animDuration = CONFIG.ANIMATION_DURATION_MS;

      function step(timestamp) {
        if (!startTime) startTime = timestamp;
        var progress = Math.min((timestamp - startTime) / animDuration, 1);
        var easeProgress = 1 - Math.pow(1 - progress, 3);
        var current = Math.round(startValue + (targetValue - startValue) * easeProgress);

        el.textContent = UIPresenter.formatDigits(current);

        if (progress < 1) {
          window.requestAnimationFrame(step);
        } else {
          el.textContent = UIPresenter.formatDigits(targetValue);
        }
      }

      window.requestAnimationFrame(step);
    },

    setCount: function (selector, value, isInstant) {
      var targetEl = root.querySelector(selector);
      if (!targetEl) return;
      var numEl = targetEl.querySelector(".tq-count-value") || targetEl;
      UIPresenter.animateNumber(numEl, typeof value === "number" ? value : 0, isInstant);
    },

    setText: function (selector, text) {
      var targetEl = root.querySelector(selector);
      if (!targetEl) return;
      var numEl = targetEl.querySelector(".tq-count-value") || targetEl;
      numEl.classList.remove("is-loading");
      numEl.setAttribute("dir", "ltr");
      numEl.setAttribute("lang", "en");
      numEl.textContent = UIPresenter.formatDigits(text);
    },

    setError: function (selector) {
      var targetEl = root.querySelector(selector);
      if (!targetEl) return;
      var numEl = targetEl.querySelector(".tq-count-value") || targetEl;
      numEl.classList.remove("is-loading");
      numEl.textContent = "—";
    },

    updateAlertBanner: function (newCount) {
      var box = root.querySelector("#twd-waed-alerts-box");
      var alertItem = root.querySelector("#alert-new-waed");
      if (!box || !alertItem) return;

      if (newCount > 0) {
        var countEl = alertItem.querySelector(".twd-alert-count");
        if (countEl) {
          countEl.setAttribute("dir", "ltr");
          countEl.setAttribute("lang", "en");
          countEl.textContent = UIPresenter.formatDigits(newCount);
        }
        alertItem.style.display = "flex";
        box.style.display = "block";
      } else {
        alertItem.style.display = "none";
        box.style.display = "none";
      }
    },

    calculateSuccessRate: function () {
      var decided = STATE.counts.approved + STATE.counts.failedwritten;
      if (decided > 0) {
        return Math.round((STATE.counts.approved / decided) * 100);
      }
      if (STATE.counts.total > 0 && STATE.counts.approved > 0) {
        return Math.round((STATE.counts.approved / STATE.counts.total) * 100);
      }
      return null;
    },

    renderAll: function (isInstant) {
      UIPresenter.setCount("#stat-total", STATE.counts.total, isInstant);
      UIPresenter.setCount("#stat-new-kpi", STATE.counts.new, isInstant);
      UIPresenter.setCount("#stat-pipe-scheduled", STATE.counts.scheduled, isInstant);
      UIPresenter.setCount("#stat-referred-kpi", STATE.counts.referred, isInstant);
      UIPresenter.setCount("#stat-pipe-passed", STATE.counts.passed, isInstant);
      UIPresenter.setCount("#stat-approved", STATE.counts.approved, isInstant);
      UIPresenter.setCount("#stat-rejected", STATE.counts.failedwritten, isInstant);
      UIPresenter.setCount("#stat-exam-groups", STATE.counts.exam_groups, isInstant);

      var rate = UIPresenter.calculateSuccessRate();
      UIPresenter.setText("#stat-success-rate", rate === null ? "—" : UIPresenter.formatDigits(rate) + "%");
      UIPresenter.updateSuccessRateRing(rate);
      UIPresenter.updateAlertBanner(STATE.counts.new);
      UIPresenter.normalizeAllDigits();
    },

    updateSuccessRateRing: function (rate) {
      var ring = root.querySelector("#stat-success-rate .wd-rate-ring");
      if (!ring) return;
      var value = typeof rate === "number" && isFinite(rate) ? Math.max(0, Math.min(100, rate)) : 0;
      ring.style.setProperty("--rate-progress", value + "%");
      ring.classList.remove("rate--good", "rate--mid", "rate--low", "rate--neutral");
      ring.classList.add(rate === null ? "rate--neutral" : value >= 75 ? "rate--good" : value >= 50 ? "rate--mid" : "rate--low");
      ring.setAttribute("aria-label", rate === null ? "نسبة النجاح غير متاحة" : "نسبة النجاح " + UIPresenter.formatDigits(value) + " بالمائة");
    },

    normalizeAllDigits: function () {
      if (!root) return;
      var walker = document.createTreeWalker(root, NodeFilter.SHOW_TEXT, null, false);
      var node;
      while ((node = walker.nextNode())) {
        if (/[٠-٩]/.test(node.nodeValue)) {
          node.nodeValue = node.nodeValue.replace(/[٠-٩]/g, function (d) {
            return String(d.charCodeAt(0) - 1632);
          });
        }
      }
    },

    setRefreshSpinning: function (isSpinning) {
      var icon = root.querySelector(".wd-icon-refresh");
      if (icon) {
        if (isSpinning) icon.classList.add("is-spinning");
        else icon.classList.remove("is-spinning");
      }
    }
  };

  // 7. موجه الروابط والتنقل الآمن (Router)
  var Router = {
    navigate: function (target) {
      var doctype = target.getAttribute("data-doctype");
      if (!doctype || CONFIG.ALLOWED_DOCTYPES.indexOf(doctype) === -1) return;

      if (target.getAttribute("data-action") === "new") {
        if (window.frappe && frappe.new_doc) {
          frappe.new_doc(doctype);
        } else {
          window.location.href = "/app/" + encodeURIComponent(doctype.toLowerCase().replace(/ /g, "-")) + "/new";
        }
        return;
      }

      var filters = {};
      try {
        var rawFilters = target.getAttribute("data-filters");
        if (rawFilters) {
          filters = JSON.parse(rawFilters);
        }
      } catch (err) {
        filters = {};
      }

      if (window.frappe && frappe.set_route) {
        frappe.route_options = filters;
        frappe.set_route("list", doctype, filters);
      } else {
        var query = Object.keys(filters).length > 0 ? "?" + new URLSearchParams(filters).toString() : "";
        window.location.href = "/app/" + encodeURIComponent(doctype.toLowerCase().replace(/ /g, "-")) + query;
      }
    }
  };

  // 8. المتحكم الدوري الذكي (Smart Periodic Poller with Page Visibility)
  var Poller = {
    timer: null,
    start: function () {
      Poller.stop();
      Poller.timer = setInterval(function () {
        if (document.visibilityState === "visible" && !STATE.isRefreshing) {
          loadDashboardData(false);
        }
      }, CONFIG.POLLING_INTERVAL_MS);
    },
    stop: function () {
      if (Poller.timer) {
        clearInterval(Poller.timer);
        Poller.timer = null;
      }
    }
  };
  root.__waed_poller = Poller;

  // 9. تهيئة الأحداث (Event Controller)
  function initEvents() {
    if (root.__waed_events_bound) return;
    root.__waed_events_bound = true;

    root.addEventListener("click", function (e) {
      var refreshBtn = e.target.closest("#btn-waed-refresh");
      if (refreshBtn) {
        e.preventDefault();
        loadDashboardData(true);
        return;
      }

      var navTarget = e.target.closest("[data-doctype]");
      if (navTarget) {
        e.preventDefault();
        Router.navigate(navTarget);
      }
    });

    root.addEventListener("keydown", function (e) {
      if (e.key === "Enter" || e.key === " ") {
        var target = e.target.closest("[data-doctype], #btn-waed-refresh");
        if (target) {
          e.preventDefault();
          target.click();
        }
      }
    });

    // استماع لتغيير حالة تبويب المتصفح لتوفير الموارد
    document.addEventListener("visibilitychange", function () {
      if (document.visibilityState === "visible") {
        loadDashboardData(false);
        Poller.start();
      } else {
        Poller.stop();
      }
    });
  }

  // 10. دورة تحميل البيانات (Lifecycle Runner)
  function loadDashboardData(isManualRefresh) {
    if (STATE.isRefreshing) return;
    STATE.isRefreshing = true;

    if (isManualRefresh) {
      UIPresenter.setRefreshSpinning(true);
    }

    APIService.fetchAggregatedStats()
      .then(function (freshCounts) {
        STATE.counts = freshCounts;
        CacheManager.saveState();
        UIPresenter.renderAll(false);
      })
      .catch(function (err) {
        console.error("[Waed Dashboard] Load error:", err);
        if (!STATE.hasCachedData) {
          [
            "#stat-total",
            "#stat-new-kpi",
            "#stat-pipe-scheduled",
            "#stat-referred-kpi",
            "#stat-pipe-passed",
            "#stat-approved",
            "#stat-success-rate",
            "#stat-rejected",
            "#stat-exam-groups"
          ].forEach(UIPresenter.setError);
        }
      })
      .finally(function () {
        STATE.isRefreshing = false;
        if (isManualRefresh) {
          setTimeout(function () {
            UIPresenter.setRefreshSpinning(false);
          }, 400);
        }
      });
  }

  // 11. الإقلاع الفوري والتنفيذ اللحظي (Instant Boot via SWR)
  initEvents();

  // خطوة 1: قراءة الكاش وعرض الأرقام فوراً في 0ms
  var hasCache = CacheManager.loadCachedState();
  if (hasCache) {
    UIPresenter.renderAll(true);
  }

  // خطوة 2: جلب أحدث البيانات في الخلفية وبدء الـ Polling الدوري
  loadDashboardData(false);
  Poller.start();
})();

style:
/* ==========================================================================
   لوحة قسم الواعظات - FEMALE WAED DASHBOARD
   Modern Minimal + Bento + Editorial/Swiss Design Architecture
   ========================================================================== */

@import url('https://fonts.googleapis.com/css2?family=Poppins:wght@300;400;500;600;700;800;900&display=swap');

.waed-dash {
  --wd-font: 'GE SS Two';

  /* Neutrals (Light Mode) */
  --wd-bg-canvas:      transparent;
  --wd-bg-surface:     #ffffff;
  --wd-bg-subtle:      #f8fafc;
  --wd-bg-card-inner:  #ffffff;
  --wd-bg-island:      #f8fafc;

  --wd-text-primary:   #0f172a;
  --wd-text-secondary: #334155;
  --wd-text-muted:     #64748b;
  --wd-text-subtle:    #94a3b8;

  --wd-border-light:   #f1f5f9;
  --wd-border-default: #e2e8f0;
  --wd-border-focus:   #38bdf8;

  /* Brand Colors (Light Oceanic Blue) */
  --wd-sky-600:        #0284c7;
  --wd-sky-500:        #0ea5e9;
  --wd-sky-400:        #38bdf8;
  --wd-sky-200:        #bae6fd;
  --wd-sky-100:        #e0f2fe;
  --wd-sky-50:         #f0f9ff;

  /* Semantic Stages */
  --wd-stage-blue:     #0284c7;
  --wd-stage-blue-bg:  #f0f9ff;
  --wd-stage-blue-bd:  #bae6fd;

  --wd-stage-amber:    #d97706;
  --wd-stage-amber-bg: #fffbeb;
  --wd-stage-amber-bd: #fde68a;

  --wd-stage-indigo:   #4f46e5;
  --wd-stage-indigo-bg:#eef2ff;
  --wd-stage-indigo-bd:#c7d2fe;

  --wd-stage-teal:     #0d9488;
  --wd-stage-teal-bg:  #f0fdfa;
  --wd-stage-teal-bd:  #99f6e4;

  --wd-stage-emerald:  #059669;
  --wd-stage-emerald-bg:#ecfdf5;
  --wd-stage-emerald-bd:#a7f3d0;

  --wd-stage-rose:     #e11d48;
  --wd-stage-rose-bg:  #fff1f2;
  --wd-stage-rose-bd:  #fecdd3;

  /* Radii */
  --wd-radius-sm:      8px;
  --wd-radius-md:      12px;
  --wd-radius-lg:      14px;
  --wd-radius-xl:      20px;
  --wd-radius-pill:    9999px;

  /* Shadows */
  --wd-shadow-sm:      0 1px 3px 0 rgba(15, 23, 42, 0.03), 0 1px 2px -1px rgba(15, 23, 42, 0.02);
  --wd-shadow-bento:   0 1px 4px 0 rgba(15, 23, 42, 0.04);
  --wd-shadow-hover:   0 10px 24px -4px rgba(2, 132, 199, 0.08), 0 2px 6px -1px rgba(15, 23, 42, 0.03);

  --wd-transition:     all 0.22s cubic-bezier(0.16, 1, 0.3, 1);

  font-family: var(--wd-font) !important;
  color: var(--wd-text-secondary);
  background: var(--wd-bg-canvas);
  direction: rtl;
  text-align: right;
  line-height: 1.5;
  box-sizing: border-box;
  -webkit-font-smoothing: antialiased;
}

/* ==========================================================================
   دعم الوضع الليلي في نظام Frappe (Dark Mode Support)
   ========================================================================== */
[data-theme="dark"] .waed-dash,
body[data-theme="dark"] .waed-dash,
.theme-dark .waed-dash {
  --wd-bg-surface:     #111827;
  --wd-bg-subtle:      #1f2937;
  --wd-bg-card-inner:  #162032;
  --wd-bg-island:      #1f2937;

  --wd-text-primary:   #f8fafc;
  --wd-text-secondary: #cbd5e1;
  --wd-text-muted:     #94a3b8;
  --wd-text-subtle:    #64748b;

  --wd-border-light:   #1f2937;
  --wd-border-default: #334155;
  --wd-border-focus:   #38bdf8;

  --wd-sky-50:         #0c4a6e;
  --wd-sky-100:        #075985;
  --wd-sky-200:        #0284c7;

  --wd-stage-blue-bg:  #0c4a6e;
  --wd-stage-blue-bd:  #0284c7;

  --wd-stage-amber-bg: #451a03;
  --wd-stage-amber-bd: #92400e;

  --wd-stage-indigo-bg:#1e1b4b;
  --wd-stage-indigo-bd:#3730a3;

  --wd-stage-teal-bg:  #042f2e;
  --wd-stage-teal-bd:  #115e59;

  --wd-stage-emerald-bg:#022c22;
  --wd-stage-emerald-bd:#065f46;

  --wd-stage-rose-bg:  #4c0519;
  --wd-stage-rose-bd:  #9f1239;

  --wd-shadow-sm:      0 1px 3px 0 rgba(0, 0, 0, 0.3);
  --wd-shadow-bento:   0 4px 16px -2px rgba(0, 0, 0, 0.4);
  --wd-shadow-hover:   0 16px 32px -4px rgba(2, 132, 199, 0.25);
}

/* 1. تطبيق خط GE SS Two لجميع النصوص والعناصر بالكامل */
.waed-dash,
.waed-dash *,
.waed-dash *::before,
.waed-dash *::after,
.waed-dash h1,
.waed-dash h2,
.waed-dash h3,
.waed-dash h4,
.waed-dash p,
.waed-dash span,
.waed-dash a,
.waed-dash div,
.waed-dash strong,
.waed-dash button,
.waed-dash label {
  font-family: 'GE SS Two' !important;
  box-sizing: border-box;
}

/* 2. استثناء الأرقام فقط: خط Poppins الصريح والأرقام القياسية 1234 دائماً */
.tq-count-value,
.tq-count-value *,
.wd-bento-hero-number,
.wd-bento-hero-number *,
.wd-bento-card-number,
.wd-bento-card-number *,
.wd-pipe-num,
.wd-pipe-num *,
.wd-stage-count,
.wd-stage-count *,
.wd-failed-count,
.wd-failed-count *,
.twd-alert-count,
.wd-pipe-step-badge,
.wd-stage-step,
.num,
.number,
.digits,
.stat-number,
[data-num] {
  font-family: 'Poppins', sans-serif !important;
  font-feature-settings: "locl" 0, "numr" 0, "lnum" 1, "tnum" 1 !important;
  font-variant-numeric: lining-nums tabular-nums !important;
  direction: ltr !important;
  unicode-bidi: isolate !important;
  display: inline-block;
}

/* الأرقام وحقول الإدخال */
.waed-dash .app-number,
.waed-dash input[type="number"],
.waed-dash input[inputmode="numeric"],
.waed-dash input[inputmode="decimal"],
.waed-dash input[type="tel"] {
  font-family: 'Poppins', sans-serif !important;
  font-feature-settings: "locl" 0, "lnum" 1, "tnum" 1 !important;
  font-variant-numeric: lining-nums tabular-nums !important;
  direction: ltr;
  unicode-bidi: isolate;
}

/* إزالة أي خط سفلي */
.waed-dash a,
.waed-dash a:hover,
.waed-dash a:focus,
.waed-dash a:active,
.waed-dash a:visited,
.waed-dash a *,
.waed-dash a:hover *,
.waed-dash button,
.waed-dash button * {
  text-decoration: none !important;
  text-decoration-line: none !important;
}

/* ==========================================================================
   شريط التنبيهات الذكي (Smart Alert Bar)
   ========================================================================== */
.wd-alert-bar {
  width: 100%;
  margin-bottom: 12px;
}

.wd-alert-pill {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 10px 18px;
  background: var(--wd-stage-rose-bg);
  border: 1px solid var(--wd-stage-rose-bd);
  border-radius: var(--wd-radius-md);
  color: var(--wd-stage-rose);
  cursor: pointer;
  transition: var(--wd-transition);
}

.wd-alert-pill:hover {
  background: #ffe4e6;
  border-color: #fda4af;
  transform: translateY(-1px);
}

.wd-alert-content {
  display: flex;
  align-items: center;
  gap: 10px;
}

.wd-pulse-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--wd-stage-rose);
  animation: wdPulse 1.8s infinite ease-in-out;
}

@keyframes wdPulse {
  0% { transform: scale(0.95); opacity: 0.7; }
  50% { transform: scale(1.3); opacity: 1; box-shadow: 0 0 8px rgba(225, 29, 72, 0.4); }
  100% { transform: scale(0.95); opacity: 0.7; }
}

.wd-alert-tag {
  font-size: 0.72rem;
  font-weight: 800;
  background: #ffffff;
  padding: 2px 8px;
  border-radius: var(--wd-radius-pill);
  border: 1px solid var(--wd-stage-rose-bd);
  color: var(--wd-stage-rose);
}

.wd-alert-msg {
  font-size: 0.86rem;
  font-weight: 600;
  color: var(--wd-text-primary);
}

.wd-alert-msg strong {
  color: var(--wd-stage-rose);
  font-weight: 800;
}

.wd-alert-cta {
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: 0.82rem;
  font-weight: 700;
  color: var(--wd-stage-rose);
}

.wd-cta-bubble {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 22px;
  height: 22px;
  border-radius: 50%;
  background: rgba(225, 29, 72, 0.1);
}

.wd-cta-bubble svg {
  width: 12px;
  height: 12px;
}

/* ==========================================================================
   الهيكل العام للحاوية (Dashboard Shell)
   ========================================================================== */
.wd-shell {
  display: flex;
  flex-direction: column;
  gap: 16px;
  width: 100%;
}

/* ==========================================================================
   ترويسة القيادة والعمليات (Executive Island Header)
   ========================================================================== */
.wd-header-island {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  padding: 16px 20px;
  background: var(--wd-bg-surface);
  border: 1px solid var(--wd-border-default);
  border-radius: var(--wd-radius-lg);
  box-shadow: var(--wd-shadow-sm);
}

.wd-header-brand {
  display: flex;
  align-items: center;
  gap: 14px;
}

.wd-avatar-core {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 44px;
  height: 44px;
  border-radius: var(--wd-radius-md);
  background: var(--wd-sky-50);
  border: 1px solid var(--wd-sky-200);
  color: var(--wd-sky-600);
  flex-shrink: 0;
}

.wd-avatar-core svg {
  width: 22px;
  height: 22px;
}

.wd-brand-text {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.wd-status-badge-row {
  display: flex;
  align-items: center;
  gap: 8px;
}

.wd-badge-brand {
  font-size: 0.72rem;
  font-weight: 800;
  color: var(--wd-sky-600);
  background: var(--wd-sky-50);
  padding: 2px 8px;
  border-radius: 4px;
  border: 1px solid var(--wd-sky-200);
}

.wd-main-title {
  font-size: 1.35rem;
  font-weight: 900;
  color: var(--wd-text-primary);
  margin: 0;
  line-height: 1.25;
}

.wd-main-subtitle {
  font-size: 0.82rem;
  font-weight: 500;
  color: var(--wd-text-muted);
  margin: 0;
}

.wd-header-actions {
  display: flex;
  align-items: center;
  gap: 10px;
  flex-shrink: 0;
}

.wd-btn-island {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  padding: 8px 14px;
  border-radius: var(--wd-radius-sm);
  font-size: 0.84rem;
  font-weight: 700;
  cursor: pointer;
  transition: var(--wd-transition);
  border: 1px solid transparent;
}

.wd-btn-ghost {
  background: var(--wd-bg-subtle);
  border-color: var(--wd-border-default);
  color: var(--wd-text-secondary);
}

.wd-btn-ghost:hover {
  background: #f1f5f9;
  color: var(--wd-text-primary);
  border-color: #cbd5e1;
}

.wd-btn-secondary {
  background: var(--wd-sky-50);
  border-color: var(--wd-sky-200);
  color: var(--wd-sky-600);
}

.wd-btn-secondary:hover {
  background: var(--wd-sky-100);
  border-color: var(--wd-sky-400);
  color: #0369a1;
}

.wd-btn-primary {
  background: var(--wd-sky-600);
  color: #ffffff;
  border-color: var(--wd-sky-600);
  box-shadow: 0 1px 3px rgba(2, 132, 199, 0.2);
}

.wd-btn-primary:hover {
  background: #0369a1;
  border-color: #0369a1;
  box-shadow: 0 4px 12px rgba(2, 132, 199, 0.25);
  transform: translateY(-1px);
}

.wd-btn-icon-bubble {
  display: flex;
  align-items: center;
  justify-content: center;
}

.wd-btn-icon-bubble svg {
  width: 15px;
  height: 15px;
}

.wd-btn-text {
  display: inline-block;
}

.wd-icon-refresh.is-spinning {
  animation: wdSpin 0.75s linear infinite;
}

@keyframes wdSpin {
  from { transform: rotate(0deg); }
  to { transform: rotate(-360deg); }
}

/* ==========================================================================
   شبكة بينتو للمؤشرات الاستراتيجية (Executive Bento Grid - 2 Primary Hero Tiles)
   ========================================================================== */
.wd-bento-hero-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 16px;
  width: 100%;
}

.wd-bento-card {
  display: flex;
  flex-direction: column;
  background: var(--wd-bg-surface);
  border: 1px solid var(--wd-border-default);
  border-radius: var(--wd-radius-lg);
  box-shadow: var(--wd-shadow-sm);
  padding: 22px 24px;
  text-decoration: none;
  cursor: pointer;
  transition: var(--wd-transition);
  position: relative;
  overflow: hidden;
}

.wd-bento-card:hover {
  border-color: var(--wd-border-focus);
  box-shadow: var(--wd-shadow-hover);
  transform: translateY(-2px);
}

/* ==================== 1. بطاقة الكادر الكبرى (Hero Bento Total Card) ==================== */
.wd-bento-total {
  background: linear-gradient(180deg, #ffffff 0%, #f8fafc 100%);
  position: relative;
}

.wd-bento-total::before {
  content: "";
  position: absolute;
  top: 0;
  left: 15%;
  right: 15%;
  height: 2px;
  background: linear-gradient(90deg, transparent, var(--wd-sky-400), transparent);
  opacity: 0.85;
  border-radius: 2px;
}

/* ==================== 2. بطاقة نسبة النجاح والاعتماد (Success Rate Bento Card) ==================== */
.wd-bento-rate {
  background: linear-gradient(180deg, #ffffff 0%, #f8fafc 100%);
  position: relative;
}

.wd-bento-rate::before {
  content: "";
  position: absolute;
  top: 0;
  left: 15%;
  right: 15%;
  height: 2px;
  background: linear-gradient(90deg, transparent, #10b981, transparent);
  opacity: 0.85;
  border-radius: 2px;
}

[data-theme="dark"] .wd-bento-total,
[data-theme="dark"] .wd-bento-rate,
body[data-theme="dark"] .wd-bento-total,
body[data-theme="dark"] .wd-bento-rate {
  background: linear-gradient(180deg, #111827 0%, #0f172a 100%);
}

.wd-bento-inner {
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  height: 100%;
  gap: 16px;
}

.wd-bento-top {
  display: flex;
  align-items: center;
  justify-content: space-between;
  width: 100%;
}

.wd-bento-icon-box {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 38px;
  height: 38px;
  border-radius: var(--wd-radius-md);
  flex-shrink: 0;
}

.wd-bento-icon-box svg {
  width: 19px;
  height: 19px;
}

.wd-icon-sky {
  background: var(--wd-sky-50);
  border: 1px solid var(--wd-sky-200);
  color: var(--wd-sky-600);
}

.wd-icon-teal {
  background: var(--wd-stage-teal-bg);
  border: 1px solid var(--wd-stage-teal-bd);
  color: var(--wd-stage-teal);
}

.wd-bento-tag {
  font-size: 0.74rem;
  font-weight: 800;
  color: var(--wd-sky-600);
  background: var(--wd-sky-50);
  border: 1px solid var(--wd-sky-200);
  padding: 3px 10px;
  border-radius: var(--wd-radius-pill);
  letter-spacing: 0.01em;
}

.wd-tag-teal {
  color: var(--wd-stage-teal);
  background: var(--wd-stage-teal-bg);
  border-color: var(--wd-stage-teal-bd);
}

/* التوسيط البصري الجمالي للرقم والوصف */
.wd-bento-center {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.wd-bento-center-hero {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  text-align: center;
  padding: 8px 0;
  gap: 6px;
}

.wd-bento-total .wd-bento-hero-number {
  font-size: 3.4rem;
  font-weight: 900;
  line-height: 1;
  color: var(--wd-text-primary);
  font-family: 'Poppins', sans-serif !important;
  text-align: center;
  letter-spacing: -0.03em;
  margin: 0;
}

.wd-bento-hero-number {
  font-size: 2.4rem;
  font-weight: 900;
  line-height: 1.1;
  color: var(--wd-text-primary);
  font-family: 'Poppins', sans-serif !important;
}

.wd-bento-label {
  font-size: 0.88rem;
  font-weight: 600;
  color: var(--wd-text-muted);
  text-align: center;
}

.wd-bento-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding-top: 12px;
  border-top: 1px solid var(--wd-border-light);
  font-size: 0.8rem;
  font-weight: 700;
  color: var(--wd-text-muted);
}

.wd-bento-footer-hero {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding-top: 12px;
  border-top: 1px solid var(--wd-border-light);
}

.wd-footer-action-text {
  color: var(--wd-sky-600);
}

.wd-footer-arrow {
  color: var(--wd-sky-600);
  font-size: 0.95rem;
  transition: transform 0.22s cubic-bezier(0.16, 1, 0.3, 1);
}

.wd-bento-card:hover .wd-footer-arrow {
  transform: translateX(-5px);
}

.wd-footer-hint {
  font-size: 0.76rem;
  color: var(--wd-text-subtle);
  text-align: center;
}

/* مؤشر النسبة الدائري (Radial Progress Ring - Enhanced Centered) */
.wd-rate-ring {
  position: relative;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 82px;
  height: 82px;
  border-radius: 50%;
  background: conic-gradient(
    var(--ring-color, #10b981) var(--rate-progress, 0%),
    var(--wd-border-default) var(--rate-progress, 0%) 100%
  );
  margin-bottom: 4px;
}

.wd-rate-ring::before {
  content: "";
  position: absolute;
  inset: 7px;
  border-radius: 50%;
  background: var(--wd-bg-surface);
}

.wd-rate-ring .wd-bento-hero-number {
  position: relative;
  z-index: 2;
  font-size: 1.45rem;
  font-weight: 900;
  margin: 0;
  color: var(--wd-text-primary);
  font-family: 'Poppins', sans-serif !important;
}

.wd-rate-ring.rate--good { --ring-color: #10b981; }
.wd-rate-ring.rate--mid  { --ring-color: #0284c7; }
.wd-rate-ring.rate--low  { --ring-color: #d97706; }
.wd-rate-ring.rate--neutral { --ring-color: #94a3b8; }

/* ==========================================================================
   مسار رحلة وتأهيل الواعظات (5-Stage Pipeline)
   ========================================================================== */
.wd-pipeline-bento-section {
  display: flex;
  flex-direction: column;
  gap: 12px;
  background: var(--wd-bg-surface);
  border: 1px solid var(--wd-border-default);
  border-radius: var(--wd-radius-lg);
  padding: 18px 20px;
  box-shadow: var(--wd-shadow-sm);
}

.wd-section-header-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.wd-section-titles {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.wd-section-tag-wrap {
  display: flex;
  align-items: center;
  gap: 8px;
}

.wd-section-badge {
  font-size: 0.72rem;
  font-weight: 800;
  color: var(--wd-sky-600);
  background: var(--wd-sky-50);
  border: 1px solid var(--wd-sky-200);
  padding: 2px 8px;
  border-radius: 4px;
}

.wd-section-heading {
  font-size: 1.15rem;
  font-weight: 900;
  color: var(--wd-text-primary);
  margin: 0;
}

.wd-section-desc {
  font-size: 0.8rem;
  color: var(--wd-text-muted);
  margin: 0;
}

.wd-pipeline-bento-grid {
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  gap: 10px;
  width: 100%;
}

.wd-stage-card {
  display: flex;
  flex-direction: column;
  background: var(--wd-bg-subtle);
  border: 1px solid var(--wd-border-default);
  border-radius: var(--wd-radius-md);
  padding: 12px 14px;
  text-decoration: none;
  cursor: pointer;
  transition: var(--wd-transition);
}

.wd-stage-card:hover {
  background: #ffffff;
  border-color: var(--wd-border-focus);
  transform: translateY(-2px);
  box-shadow: 0 4px 12px rgba(2, 132, 199, 0.08);
}

.wd-stage-inner {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.wd-stage-top {
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.wd-stage-step {
  font-size: 0.74rem;
  font-weight: 800;
  color: var(--wd-text-subtle);
  background: #ffffff;
  padding: 1px 6px;
  border-radius: 4px;
  border: 1px solid var(--wd-border-default);
}

.wd-stage-icon {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 26px;
  height: 26px;
  border-radius: 6px;
}

.wd-stage-icon svg {
  width: 14px;
  height: 14px;
}

.wd-stage-new .wd-stage-icon {
  background: var(--wd-stage-blue-bg);
  border: 1px solid var(--wd-stage-blue-bd);
  color: var(--wd-stage-blue);
}

.wd-stage-scheduled .wd-stage-icon {
  background: var(--wd-stage-amber-bg);
  border: 1px solid var(--wd-stage-amber-bd);
  color: var(--wd-stage-amber);
}

.wd-stage-referred .wd-stage-icon {
  background: var(--wd-stage-indigo-bg);
  border: 1px solid var(--wd-stage-indigo-bd);
  color: var(--wd-stage-indigo);
}

.wd-stage-passed .wd-stage-icon {
  background: var(--wd-stage-teal-bg);
  border: 1px solid var(--wd-stage-teal-bd);
  color: var(--wd-stage-teal);
}

.wd-stage-approved .wd-stage-icon {
  background: var(--wd-stage-emerald-bg);
  border: 1px solid var(--wd-stage-emerald-bd);
  color: var(--wd-stage-emerald);
}

.wd-stage-body {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.wd-stage-name {
  font-size: 0.84rem;
  font-weight: 800;
  color: var(--wd-text-primary);
  line-height: 1.2;
}

.wd-stage-caption {
  font-size: 0.72rem;
  color: var(--wd-text-muted);
}

.wd-stage-count {
  font-size: 1.55rem;
  font-weight: 900;
  color: var(--wd-text-primary);
  line-height: 1.1;
  padding-top: 4px;
  border-top: 1px solid var(--wd-border-light);
}

/* ==========================================================================
   مسار الحالات الاستثنائية (الراسبات بالتحريري)
   ========================================================================== */
.wd-secondary-bento-row {
  width: 100%;
  margin-top: 4px;
}

.wd-failed-bento-card {
  display: flex;
  align-items: center;
  background: var(--wd-stage-rose-bg);
  border: 1px solid var(--wd-stage-rose-bd);
  border-radius: var(--wd-radius-md);
  padding: 12px 18px;
  text-decoration: none;
  cursor: pointer;
  transition: var(--wd-transition);
}

.wd-failed-bento-card:hover {
  background: #ffe4e6;
  border-color: #fda4af;
  transform: translateY(-1px);
}

.wd-failed-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  width: 100%;
  gap: 14px;
}

.wd-failed-icon-box {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 34px;
  height: 34px;
  border-radius: 8px;
  background: #ffffff;
  border: 1px solid var(--wd-stage-rose-bd);
  color: var(--wd-stage-rose);
  flex-shrink: 0;
}

.wd-failed-icon-box svg {
  width: 18px;
  height: 18px;
}

.wd-failed-info {
  display: flex;
  flex-direction: column;
  gap: 2px;
  flex-grow: 1;
}

.wd-failed-title {
  font-size: 0.88rem;
  font-weight: 800;
  color: var(--wd-stage-rose);
}

.wd-failed-subtitle {
  font-size: 0.76rem;
  color: var(--wd-text-muted);
}

.wd-failed-count {
  font-size: 1.55rem;
  font-weight: 900;
  color: var(--wd-stage-rose);
  padding-left: 8px;
}

.wd-failed-arrow {
  font-size: 1rem;
  color: var(--wd-stage-rose);
  transition: transform 0.2s ease;
}

.wd-failed-bento-card:hover .wd-failed-arrow {
  transform: translateX(-4px);
}

/* ==========================================================================
   حالة التحميل الشبحية (Zero-CLS Loading State)
   ========================================================================== */
.is-loading {
  position: relative;
  min-height: 24px;
}

/* ==========================================================================
   مؤشرات التحميل الشبحية (Zero-CLS Skeletons)
   ========================================================================== */
.wd-skeleton {
  display: inline-block;
  width: 48px;
  height: 28px;
  border-radius: 6px;
  background: linear-gradient(90deg, #f1f5f9 25%, #e2e8f0 50%, #f1f5f9 75%);
  background-size: 200% 100%;
  animation: wdBentoShimmer 1.5s infinite;
  vertical-align: middle;
}

.wd-skeleton-pipe {
  width: 32px;
  height: 22px;
}

@keyframes wdBentoShimmer {
  0% { background-position: 200% 0; }
  100% { background-position: -200% 0; }
}

/* ==========================================================================
   التجاوب مع الشاشات (Responsive Grid Architecture)
   ========================================================================== */
@media (max-width: 1024px) {
  

  .wd-pipeline-bento-grid {
    grid-template-columns: repeat(3, 1fr);
  }
}

@media (max-width: 768px) {
  .wd-header-island {
    flex-direction: column;
    align-items: flex-start;
    gap: 12px;
    padding: 14px 16px;
  }

  .wd-header-actions {
    width: 100%;
    justify-content: flex-start;
    flex-wrap: wrap;
  }

  .wd-bento-hero-grid {
    grid-template-columns: 1fr;
  }

  .wd-bento-total {
    grid-column: auto;
  }

  .wd-pipeline-bento-grid {
    grid-template-columns: repeat(2, 1fr);
  }

  .wd-failed-inner {
    flex-wrap: wrap;
  }
}

@media (max-width: 480px) {
  .wd-pipeline-bento-grid {
    grid-template-columns: 1fr;
  }
  
  .wd-main-title {
    font-size: 1.15rem;
  }

  .wd-bento-hero-number {
    font-size: 1.9rem;
  }
}

script:
/* ============================================================
   dashboard.js - لوحة "قسم الوعاظ"
   Frappe v15 Workspace - Custom HTML Block
   ------------------------------------------------------------
   يعتمد على `root_element` المتاح تلقائيًا داخل الـ Custom
   HTML Block في Frappe. لا تغيير في المنطق أو الفلاتر الأصلية،
   فقط إعادة تنظيم وإزالة التكرار وإضافة معالجة الأخطاء.
   ============================================================ */

(function () {
  "use strict";

  /* ---------------------------------------------------------
     أدوات مساعدة عامة (Helpers)
     --------------------------------------------------------- */

  /** يعبّئ قيمة رقمية داخل بطاقة إحصاء ويزيل حالة التحميل */
  function setNum(sel, value) {
    var el = root_element.querySelector(sel + " .tq-count-value");
    if (!el) return;
    el.classList.remove("is-loading");
    el.textContent = typeof value === "number" ? value.toLocaleString("ar") : "0";
  }

  /** يعرض قيمة "—" (تعذّر التحميل) بدل ترك الرقم عالقًا عند فشل الطلب */
  function setNumError(sel) {
    var el = root_element.querySelector(sel + " .tq-count-value");
    if (!el) return;
    el.classList.remove("is-loading");
    el.textContent = "—";
  }

  /** دالة تنقّل موحّدة: تمنع السلوك الافتراضي للرابط وتستخدم راوتر Frappe الداخلي */
  function bindRoute(sel, doctype, filters) {
    var el = root_element.querySelector(sel);
    if (!el) return;
    el.addEventListener("click", function (e) {
      e.preventDefault();
      if (doctype) {
        frappe.set_route("list", doctype, filters || {});
      } else {
        frappe.set_route(el.getAttribute("href").replace(/^\/app\//, ""));
      }
    });
  }

  /** يُظهر/يُخفي صندوق التنبيهات الرئيسي حسب وجود تنبيهات ظاهرة فعليًا */
  function checkAlertsBoxVisibility() {
    var box = root_element.querySelector("#tq-alerts-box");
    if (!box) return;
    var visibleAlerts = box.querySelectorAll('.tq-alert-item:not([style*="display: none"])');
    box.style.display = visibleAlerts.length > 0 ? "block" : "none";
  }

  /** يهيئ عنصر تنبيه: يعبّئ العدّاد، يُظهره، ويربط حدث النقر بمساره الخاص */
  function activateAlert(sel, count, doctype, filters) {
    var alertItem = root_element.querySelector(sel);
    if (!alertItem || !(count > 0)) return;

    var countEl = alertItem.querySelector(".tq-alert-count");
    if (countEl) countEl.textContent = count.toLocaleString("ar");

    alertItem.style.display = "flex";
    alertItem.addEventListener("click", function (e) {
      e.preventDefault();
      frappe.set_route("list", doctype, filters || {});
    });

    checkAlertsBoxVisibility();
  }

  /* ---------------------------------------------------------
     قسم الوعاظ: بطاقات الإحصاء + تنبيه الوعاظ الجدد
     --------------------------------------------------------- */

  frappe.db
    .count("waed_info", { filters: { waed_status: "New" } })
    .then(function (count) {
      setNum("#stat-waed-new", count);
      activateAlert("#alert-new-waed", count, "waed_info", { waed_status: "New" });
    })
    .catch(function () {
      setNumError("#stat-waed-new");
    });

  frappe.db
    .count("waed_info", { filters: { waed_status: "referred for the exam" } })
    .then(function (count) {
      setNum("#stat-waed-referred", count);
    })
    .catch(function () {
      setNumError("#stat-waed-referred");
    });

  frappe.db
    .count("exam_group_date")
    .then(function (count) {
      setNum("#stat-exam-groups", count);
    })
    .catch(function () {
      setNumError("#stat-exam-groups");
    });

  /* ---------------------------------------------------------
     قسم الامتحانات: بطاقات الإحصاء + تنبيه الامتحانات الجارية
     --------------------------------------------------------- */

  frappe.db
    .count("exam_group_date", { filters: { exam_status: "Scheduled" } })
    .then(function (count) {
      setNum("#stat-exam-scheduled", count);
    })
    .catch(function () {
      setNumError("#stat-exam-scheduled");
    });

  // "قيد الإجراء" تجمع حالتين: التحريري والشفوي
  var IN_PROGRESS_FILTER = { exam_status: ["in", ["Written In Progress", "Oral In Progress"]] };

  frappe.db
    .count("exam_group_date", { filters: IN_PROGRESS_FILTER })
    .then(function (count) {
      setNum("#stat-exam-inprogress", count);
      activateAlert("#alert-exam-progress", count, "exam_group_date", IN_PROGRESS_FILTER);
    })
    .catch(function () {
      setNumError("#stat-exam-inprogress");
    });

  frappe.db
    .count("exam_group_date", { filters: { exam_status: "Completed" } })
    .then(function (count) {
      setNum("#stat-exam-completed", count);
    })
    .catch(function () {
      setNumError("#stat-exam-completed");
    });

  /* ---------------------------------------------------------
     تنبيه أقرب موعد امتحان قادم
     --------------------------------------------------------- */

  function formatRemainingDays(daysDiff) {
    if (daysDiff === 0) return "اليوم";
    if (daysDiff === 1) return "غداً";
    if (daysDiff === 2) return "بعد غد";
    if (daysDiff <= 10) return "متبقي " + daysDiff.toLocaleString("ar") + " أيام";

    var months = Math.floor(daysDiff / 30);
    var remDays = daysDiff % 30;

    if (months > 0) {
      var text = "متبقي " + months.toLocaleString("ar") + " شهر";
      if (remDays > 0) text += " و " + remDays.toLocaleString("ar") + " يوم";
      return text;
    }
    return "متبقي " + daysDiff.toLocaleString("ar") + " يوم";
  }

  frappe.model
    .with_doctype("exam_group_date", function () {
      var meta = frappe.get_meta("exam_group_date");
      var dateField = "date";

      if (meta && meta.fields) {
        var found = meta.fields.find(function (f) {
          return f.fieldtype === "Date";
        });
        if (found) dateField = found.fieldname;
      }

      frappe.db
        .get_list("exam_group_date", {
          filters: { exam_status: "Scheduled" },
          fields: ["name", dateField],
          order_by: dateField + " asc",
          limit: 1
        })
        .then(function (records) {
          if (!records || !records.length || !records[0][dateField]) return;

          var examDate = new Date(records[0][dateField]);
          var today = new Date();
          today.setHours(0, 0, 0, 0);
          examDate.setHours(0, 0, 0, 0);

          var daysDiff = Math.ceil((examDate.getTime() - today.getTime()) / (1000 * 60 * 60 * 24));
          if (daysDiff < 0) return;

          var alertItem = root_element.querySelector("#alert-next-exam");
          if (!alertItem) return;

          var dateOptions = { year: "numeric", month: "long", day: "numeric" };
          alertItem.querySelector(".tq-alert-date").textContent = examDate.toLocaleDateString("ar-LY", dateOptions);
          alertItem.querySelector(".tq-alert-remaining").textContent = formatRemainingDays(daysDiff);
          alertItem.style.display = "flex";

          alertItem.addEventListener("click", function (e) {
            e.preventDefault();
            frappe.set_route("list", "exam_group_date", { exam_status: "Scheduled" });
          });

          checkAlertsBoxVisibility();
        })
        .catch(function () {
          /* تعذّر تحديد أقرب موعد امتحان - لا تنبيه يُعرض في هذه الحالة */
        });
    })
    .catch(function () {
      /* تعذّر تحميل تعريف نوع المستند exam_group_date */
    });

  /* ---------------------------------------------------------
     ربط التنقّل لكل بطاقات الإحصاء وأدوات الاختصارات
     --------------------------------------------------------- */

  // بطاقات الإحصاء
  bindRoute("#stat-waed-new", "waed_info", { waed_status: "New" });
  bindRoute("#stat-waed-referred", "waed_info", { waed_status: "referred for the exam" });
  bindRoute("#stat-exam-groups", "exam_group_date");
  bindRoute("#stat-exam-scheduled", "exam_group_date", { exam_status: "Scheduled" });
  bindRoute("#stat-exam-inprogress", "exam_group_date", IN_PROGRESS_FILTER);
  bindRoute("#stat-exam-completed", "exam_group_date", { exam_status: "Completed" });

  // أدوات الوعاظ
  bindRoute("#link-waed-new", "waed_info", { waed_status: "New" });
  bindRoute("#link-waed-scheduled", "waed_info", { waed_status: "Scheduling an appointment" });
  bindRoute("#link-waed-exam-set", "waed_info", { waed_status: "referred for the exam" });
  bindRoute("#link-waed-passed", "waed_info", { waed_status: "Successful in the written exam" });
  bindRoute("#link-waed-failed", "waed_info", { waed_status: "Rejected" });
  bindRoute("#link-waed-approved", "waed_info", { waed_status: "Approved" });

  // أدوات الامتحانات (تنقّل إلى مسار مباشر بدل قائمة مفلترة)
  bindRoute("#link-exam-create");
  bindRoute("#link-exam-date-create");
  bindRoute("#link-exam-grading");
  bindRoute("#link-exam-approve");
})();

style:
@import url('https://fonts.googleapis.com/css2?family=Tajawal:wght@400;500;700;800;900&display=swap');

/*
  ============================================================
  dashboard.css — لوحة "قسم الوعاظ وقسم الامتحانات"
  Frappe v15 Workspace - Custom HTML Block
  ------------------------------------------------------------
  إعادة تصميم بصري كامل (تنسيق فقط) — بلا أي تغيير في المنطق
  أو الأسماء أو المعرّفات التي يعتمد عليها dashboard.js.
  هوية اللون: أخضر زمردي عميق + ذهبي هادئ، بنمط SaaS/ERP حديث
  مع لمسات هندسية إسلامية خفيفة.
  ============================================================
*/

/* ============================================================
   1) نظام التصميم (Design Tokens)
   ============================================================ */
.tq-dash {
  /* أسطح محايدة دافئة */
  --tq-bg:            #fdfcfa;
  --tq-surface:       #ffffff;
  --tq-surface-alt:   #f6f8f7;
  --tq-border:        #e3e9e6;
  --tq-border-soft:   #edf2f0;

  /* حبر النص */
  --tq-ink:           #0e2a22;
  --tq-ink-soft:      #55655d;
  --tq-ink-faint:     #8d9c94;

  /* الأخضر الزمردي (اللون الأساسي) */
  --tq-accent:        #0d5445;
  --tq-accent-dark:   #082e26;
  --tq-accent-light:  #17795f;
  --tq-accent-soft:   #e5f3ee;
  --tq-accent-ring:   rgba(13, 84, 69, .15);

  /* الذهبي (لون ثانوي / تمييز) */
  --tq-gold:          #ad8a3f;
  --tq-gold-light:    #cba85e;
  --tq-gold-soft:     #faf5e7;
  --tq-gold-ring:     rgba(173, 138, 63, .16);

  --tq-emerald:       #1c8467;
  --tq-emerald-soft:  #e8f7f0;

  --tq-amber:         #a8720c;
  --tq-amber-soft:    #fcf1de;

  --tq-red:           #ad3f3f;
  --tq-red-soft:      #fbecec;

  --tq-grey:          #57616d;
  --tq-grey-soft:     #edf0f3;

  /* الهيدر (Hero) الداكن */
  --tq-hero-1:        #082019;
  --tq-hero-2:        #0d5445;
  --tq-hero-3:        #114a3d;
  --tq-cream:         #f5ebd7;
  --tq-cream-soft:    #bfdcd0;

  /* مقاييس موحّدة */
  --tq-radius-sm: 10px;
  --tq-radius-md: 14px;
  --tq-radius-lg: 20px;
  --tq-radius-xl: 26px;

  --tq-space-1: 6px;
  --tq-space-2: 10px;
  --tq-space-3: 16px;
  --tq-space-4: 24px;
  --tq-space-5: 36px;

  --tq-shadow-xs: 0 1px 2px rgba(8, 32, 25, .05);
  --tq-shadow-sm: 0 2px 8px rgba(8, 32, 25, .06);
  --tq-shadow-md: 0 10px 26px -6px rgba(8, 32, 25, .14);
  --tq-shadow-lg: 0 24px 48px -14px rgba(8, 32, 25, .22);

  --tq-ease: cubic-bezier(.22, 1, .36, 1);
  --tq-ease-soft: cubic-bezier(.4, 0, .2, 1);
  --tq-font: "Tajawal", "Segoe UI", "Cairo", "Geeza Pro", Arial, sans-serif;

  display: block;
  box-sizing: border-box;
  font-family: var(--tq-font);
  color: var(--tq-ink);
  background: var(--tq-bg);
  direction: rtl;
  text-align: right;
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
}

.tq-dash *,
.tq-dash *::before,
.tq-dash *::after {
  box-sizing: border-box;
}

.tq-dash ul {
  list-style: none;
  margin: 0;
  padding: 0;
}

.tq-dash a {
  text-decoration: none;
  color: inherit;
}

.tq-dash :focus-visible {
  outline: 2px solid var(--tq-accent);
  outline-offset: 2px;
  border-radius: var(--tq-radius-sm);
}

@media (prefers-reduced-motion: reduce) {
  .tq-dash * { transition: none !important; animation: none !important; }
}

/* ============================================================
   2) الهيدر الرئيسي (Hero)
   ============================================================ */
.tq-hero {
  position: relative;
  isolation: isolate;
  overflow: hidden;
  border-radius: var(--tq-radius-xl);
  padding: 46px 48px;
  margin-bottom: var(--tq-space-5);
  background:
    radial-gradient(120% 160% at 100% 0%, rgba(203, 168, 94, .16) 0%, transparent 45%),
    linear-gradient(120deg, var(--tq-hero-1) 0%, var(--tq-hero-2) 52%, var(--tq-hero-3) 100%);
  border: 1px solid rgba(203, 168, 94, .22);
  box-shadow: var(--tq-shadow-lg);
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--tq-space-4);
  color: var(--tq-cream);
}

/* نمط زخرفي هندسي خفيف مستوحى من الطراز الإسلامي */
.tq-hero::before {
  content: "";
  position: absolute;
  inset: 0;
  z-index: 0;
  pointer-events: none;
  opacity: .5;
  background-image:
    repeating-linear-gradient(45deg, rgba(203, 168, 94, .07) 0, rgba(203, 168, 94, .07) 1px, transparent 1px, transparent 30px),
    repeating-linear-gradient(-45deg, rgba(203, 168, 94, .07) 0, rgba(203, 168, 94, .07) 1px, transparent 1px, transparent 30px);
  -webkit-mask-image: linear-gradient(to left, black, transparent 75%);
          mask-image: linear-gradient(to left, black, transparent 75%);
}

.tq-hero::after {
  content: "";
  position: absolute;
  width: 260px;
  height: 260px;
  left: -80px;
  top: -90px;
  border: 1.5px solid rgba(203, 168, 94, .28);
  border-radius: 50%;
  pointer-events: none;
}

.tq-hero__content {
  position: relative;
  z-index: 1;
  max-width: 640px;
}

.tq-hero__eyebrow {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  font-size: 12px;
  font-weight: 700;
  letter-spacing: .4px;
  color: var(--tq-gold-light);
  background: rgba(203, 168, 94, .1);
  border: 1px solid rgba(203, 168, 94, .38);
  padding: 6px 15px;
  border-radius: 999px;
  margin-bottom: 16px;
}

.tq-hero__eyebrow::before {
  content: "◆";
  font-size: 8px;
}

.tq-hero__title {
  font-size: 30px;
  font-weight: 900;
  letter-spacing: -.2px;
  color: var(--tq-cream);
  margin: 0 0 10px 0;
}

.tq-hero__subtitle {
  font-size: 14px;
  color: var(--tq-cream-soft);
  margin: 0;
  max-width: 540px;
  opacity: .92;
  line-height: 1.9;
}

.tq-hero__seal {
  position: relative;
  z-index: 1;
  flex-shrink: 0;
  width: 90px;
  height: 90px;
  border-radius: 50%;
  background: rgba(255, 255, 255, .05);
  border: 1px solid rgba(203, 168, 94, .4);
  display: flex;
  align-items: center;
  justify-content: center;
  box-shadow: inset 0 0 0 1px rgba(203, 168, 94, .1), var(--tq-shadow-sm);
}

.tq-hero__seal svg {
  width: 42px;
  height: 42px;
  color: var(--tq-gold-light);
}

/* ============================================================
   3) نظام التنبيهات الذكي
   ============================================================ */
.tq-alerts-container {
  display: flex;
  flex-direction: column;
  gap: var(--tq-space-2);
  margin-bottom: var(--tq-space-4);
  animation: tqFadeInUp .45s var(--tq-ease);
}

.tq-alert-item {
  position: relative;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  padding: 15px 20px 15px 22px;
  border-radius: var(--tq-radius-md);
  font-size: 13.5px;
  font-weight: 600;
  background: var(--tq-surface);
  border: 1px solid var(--tq-border-soft);
  box-shadow: var(--tq-shadow-xs);
  transition: transform .2s var(--tq-ease), box-shadow .2s var(--tq-ease), border-color .2s var(--tq-ease);
  cursor: pointer;
  overflow: hidden;
}

.tq-alert-item::before {
  content: "";
  position: absolute;
  inset-inline-start: 0;
  top: 0;
  bottom: 0;
  width: 4px;
  background: var(--tq-alert-accent, var(--tq-accent));
}

.tq-alert-content-wrapper {
  display: flex;
  align-items: center;
  gap: 14px;
}

.tq-alert-icon {
  font-size: 16px;
  flex-shrink: 0;
  width: 34px;
  height: 34px;
  border-radius: 10px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  background: var(--tq-alert-soft, var(--tq-accent-soft));
}

.tq-alert-text {
  color: var(--tq-ink);
  line-height: 1.5;
}

.tq-alert-text strong {
  font-weight: 800;
  color: var(--tq-alert-accent, var(--tq-accent));
  background: var(--tq-alert-soft, var(--tq-accent-soft));
  padding: 2px 8px;
  border-radius: 6px;
  margin: 0 4px;
}

.tq-alert-arrow {
  font-size: 15px;
  color: var(--tq-ink-faint);
  opacity: .6;
  transition: transform .2s var(--tq-ease), opacity .2s var(--tq-ease), color .2s var(--tq-ease);
}

.tq-alert-item:hover {
  transform: translateY(-2px);
  box-shadow: var(--tq-shadow-md);
  border-color: var(--tq-border);
}

.tq-alert-item:hover .tq-alert-arrow {
  opacity: 1;
  color: var(--tq-alert-accent, var(--tq-accent));
  transform: translateX(-4px);
}

.tq-alert-item:active {
  transform: translateY(0);
}

.tq-alert-item--blue  { --tq-alert-accent: var(--tq-accent);  --tq-alert-soft: var(--tq-accent-soft); }
.tq-alert-item--amber { --tq-alert-accent: var(--tq-amber);   --tq-alert-soft: var(--tq-amber-soft); }
.tq-alert-item--gold  { --tq-alert-accent: var(--tq-gold);    --tq-alert-soft: var(--tq-gold-soft); }

@keyframes tqFadeInUp {
  from { opacity: 0; transform: translateY(10px); }
  to   { opacity: 1; transform: translateY(0); }
}

/* ============================================================
   4) عناوين الأقسام الرئيسية (Modules)
   ============================================================ */
.tq-module {
  margin-bottom: var(--tq-space-5);
}

.tq-module__header {
  display: flex;
  align-items: center;
  gap: 14px;
  margin-bottom: var(--tq-space-4);
  padding-bottom: var(--tq-space-3);
  border-bottom: 1px solid var(--tq-border-soft);
}

.tq-module__icon {
  flex-shrink: 0;
  width: 42px;
  height: 42px;
  border-radius: 13px;
  background: linear-gradient(155deg, var(--tq-accent-soft), #ffffff);
  border: 1px solid var(--tq-border-soft);
  color: var(--tq-accent);
  display: flex;
  align-items: center;
  justify-content: center;
  box-shadow: var(--tq-shadow-xs);
}

.tq-module__icon svg {
  width: 21px;
  height: 21px;
}

.tq-module__title {
  font-size: 19.5px;
  font-weight: 800;
  color: var(--tq-ink);
  margin: 0;
  letter-spacing: -.1px;
}

.tq-module__subtitle {
  font-size: 12.5px;
  color: var(--tq-ink-faint);
  margin: 3px 0 0 0;
}

.tq-subsection {
  margin-bottom: var(--tq-space-4);
}

.tq-subsection:last-child {
  margin-bottom: 0;
}

.tq-subsection-title {
  font-size: 13.5px;
  font-weight: 700;
  color: var(--tq-ink-soft);
  margin: 0 0 var(--tq-space-3) 0;
  display: flex;
  align-items: center;
  gap: 9px;
  text-transform: uppercase;
  letter-spacing: .3px;
}

.tq-subsection-title::before {
  content: "";
  width: 4px;
  height: 14px;
  border-radius: 3px;
  background: linear-gradient(180deg, var(--tq-gold-light), var(--tq-gold));
  display: inline-block;
}

/* ============================================================
   5) بطاقات الإحصاء (Stat Cards)
   ============================================================ */
.tq-stats {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: var(--tq-space-3);
  margin-bottom: var(--tq-space-4);
}

.tq-stat-card {
  position: relative;
  display: block;
  background: var(--tq-surface);
  border: 1px solid var(--tq-border-soft);
  border-radius: var(--tq-radius-lg);
  padding: 20px 22px;
  box-shadow: var(--tq-shadow-xs);
  overflow: hidden;
  transition: transform .2s var(--tq-ease), box-shadow .2s var(--tq-ease), border-color .2s var(--tq-ease);
}

.tq-stat-card::after {
  content: "";
  position: absolute;
  inset-inline-end: -30px;
  top: -30px;
  width: 100px;
  height: 100px;
  border-radius: 50%;
  background: var(--tq-card-accent, var(--tq-accent));
  opacity: .07;
  transition: opacity .2s var(--tq-ease), transform .3s var(--tq-ease);
}

.tq-stat-card:hover {
  transform: translateY(-4px);
  box-shadow: var(--tq-shadow-md);
  border-color: color-mix(in srgb, var(--tq-card-accent, var(--tq-accent)) 30%, var(--tq-border));
}

.tq-stat-card:hover::after {
  opacity: .12;
  transform: scale(1.15);
}

.tq-stat-card--blue    { --tq-card-accent: var(--tq-accent); }
.tq-stat-card--gold    { --tq-card-accent: var(--tq-gold); }
.tq-stat-card--emerald { --tq-card-accent: var(--tq-emerald); }
.tq-stat-card--amber   { --tq-card-accent: var(--tq-amber); }
.tq-stat-card--grey    { --tq-card-accent: var(--tq-grey); }

.tq-stat-card__top {
  position: relative;
  z-index: 1;
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 16px;
}

.tq-stat-card__icon {
  width: 38px;
  height: 38px;
  border-radius: 12px;
  display: flex;
  align-items: center;
  justify-content: center;
  background: color-mix(in srgb, var(--tq-card-accent) 12%, white);
  color: var(--tq-card-accent);
}

.tq-stat-card__icon svg {
  width: 18px;
  height: 18px;
}

.tq-stat-card__value {
  position: relative;
  z-index: 1;
  display: block;
  font-size: 27px;
  font-weight: 800;
  color: var(--tq-ink);
  line-height: 1;
  margin-bottom: 6px;
  font-variant-numeric: tabular-nums;
  transition: color .2s var(--tq-ease-soft);
}

.tq-stat-card__value.is-loading {
  color: var(--tq-ink-faint);
}

.tq-stat-card__label {
  position: relative;
  z-index: 1;
  display: block;
  font-size: 12.5px;
  color: var(--tq-ink-soft);
  font-weight: 600;
}

/* ============================================================
   6) بطاقات الأدوات / الاختصارات (Actions)
   ============================================================ */
.tq-actions__grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: var(--tq-space-2);
}

.tq-actions__grid--3 {
  grid-template-columns: repeat(3, 1fr);
}

.tq-action {
  position: relative;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 10px;
  text-align: center;
  background: var(--tq-surface);
  border: 1px solid var(--tq-border-soft);
  border-radius: var(--tq-radius-md);
  padding: 18px 12px;
  cursor: pointer;
  transition: border-color .18s var(--tq-ease), box-shadow .18s var(--tq-ease), transform .18s var(--tq-ease), background .18s var(--tq-ease);
}

.tq-action:hover {
  border-color: transparent;
  box-shadow: 0 0 0 1.5px var(--tq-action-color, var(--tq-accent)) inset, var(--tq-shadow-md);
  background: var(--tq-action-soft, var(--tq-accent-soft));
  transform: translateY(-3px);
}

.tq-action__icon {
  width: 38px;
  height: 38px;
  border-radius: 12px;
  background: var(--tq-action-soft, var(--tq-accent-soft));
  color: var(--tq-action-color, var(--tq-accent));
  display: flex;
  align-items: center;
  justify-content: center;
  transition: transform .18s var(--tq-ease);
}

.tq-action:hover .tq-action__icon {
  transform: scale(1.08);
  background: var(--tq-surface);
}

.tq-action__icon svg {
  width: 19px;
  height: 19px;
}

.tq-action__label {
  font-size: 12.5px;
  font-weight: 700;
  color: var(--tq-ink);
  line-height: 1.4;
}

.tq-action--green  { --tq-action-color: var(--tq-emerald); --tq-action-soft: var(--tq-emerald-soft); }
.tq-action--orange { --tq-action-color: var(--tq-amber);   --tq-action-soft: var(--tq-amber-soft); }
.tq-action--yellow,
.tq-action--gold   { --tq-action-color: var(--tq-gold);    --tq-action-soft: var(--tq-gold-soft); }
.tq-action--red    { --tq-action-color: var(--tq-red);     --tq-action-soft: var(--tq-red-soft); }
.tq-action--blue   { --tq-action-color: var(--tq-accent);  --tq-action-soft: var(--tq-accent-soft); }
.tq-action--grey   { --tq-action-color: var(--tq-grey);    --tq-action-soft: var(--tq-grey-soft); }

/* ============================================================
   7) الاستجابة (Responsive)
   ============================================================ */
@media (max-width: 1100px) {
  .tq-actions__grid,
  .tq-actions__grid--3 {
    grid-template-columns: repeat(3, 1fr);
  }
}

@media (max-width: 900px) {
  .tq-stats {
    grid-template-columns: repeat(2, 1fr);
  }
  .tq-hero {
    padding: 36px 34px;
  }
}

@media (max-width: 640px) {
  .tq-hero {
    flex-direction: column-reverse;
    align-items: flex-start;
    padding: 28px 22px;
    border-radius: var(--tq-radius-lg);
  }
  .tq-hero__seal {
    width: 60px;
    height: 60px;
  }
  .tq-hero__seal svg {
    width: 28px;
    height: 28px;
  }
  .tq-hero__title {
    font-size: 22px;
  }
  .tq-stats {
    grid-template-columns: 1fr;
  }
  .tq-actions__grid,
  .tq-actions__grid--3 {
    grid-template-columns: repeat(2, 1fr);
  }
  .tq-module__title {
    font-size: 17px;
  }
  .tq-alert-item {
    flex-direction: column;
    align-items: flex-start;
    gap: 10px;
    padding: 16px 18px;
  }
  .tq-alert-arrow {
    display: none;
  }
}

@media (max-width: 400px) {
  .tq-actions__grid,
  .tq-actions__grid--3 {
    grid-template-columns: 1fr;
  }
  .tq-hero {
    padding: 24px 18px;
  }
  .tq-hero__title {
    font-size: 20px;
  }
}

script:
(function () {
  "use strict";

  /* ==========================================================================
   * لوحة قسم الواعظات - Modular Executive Engine (Frappe Custom Block)
   * المميزات المتقدمة:
   * 1. الأداء الفائق: تجميع الاستعلامات في طلب واحد (Single Aggregated Query / GROUP BY)
   * 2. مرونة الفلاتر: مطابقة الحالات ديناميكياً بدون ترميز ثابت هش (Fuzzy Status Matcher)
   * 3. التحميل اللحظي: Stale-While-Revalidate عبر sessionStorage بدون شاشات انتظار
   * 4. التحديث التلقائي الذكي: Polling دوري مع إدارة دورة حياة التبويب (Page Visibility API)
   * ========================================================================== */

  var root = typeof root_element !== "undefined" ? root_element : document.querySelector(".waed-dash") || document;

  // تنظيف أي مؤقتات قديمة عند إعادة تحميل الـ Workspace
  if (root.__femalwaed_poller) {
    root.__femalwaed_poller.stop();
  }

  installNumberTypography(root);

  function installNumberTypography(scope) {
    if (!scope || scope.__number_typography_installed) return;
    scope.__number_typography_installed = true;
    var digits = /[0-9٠-٩]+(?:[.,:/+\-%][0-9٠-٩]+)*/g, excluded = "SCRIPT,STYLE,TEXTAREA,OPTION";
    function render() {
      var walker = document.createTreeWalker(scope, NodeFilter.SHOW_TEXT, null, false), nodes = [], node;
      while ((node = walker.nextNode())) {
        var parent = node.parentElement;
        if (parent && !parent.closest(".app-number") && excluded.indexOf(parent.tagName) === -1 && digits.test(node.nodeValue)) {
          nodes.push(node);
        }
        digits.lastIndex = 0;
      }
      nodes.forEach(function (textNode) {
        var fragment = document.createDocumentFragment(), value = textNode.nodeValue, last = 0;
        value.replace(digits, function (match, offset) {
          fragment.appendChild(document.createTextNode(value.slice(last, offset)));
          var span = document.createElement("span");
          span.className = "app-number";
          span.textContent = match;
          fragment.appendChild(span);
          last = offset + match.length;
        });
        fragment.appendChild(document.createTextNode(value.slice(last)));
        textNode.parentNode.replaceChild(fragment, textNode);
        digits.lastIndex = 0;
      });
    }
    var queued = false;
    new MutationObserver(function () {
      if (!queued) {
        queued = true;
        requestAnimationFrame(function () {
          queued = false;
          render();
        });
      }
    }).observe(scope, { childList: true, characterData: true, subtree: true });
    render();
  }

  // 1. الإعدادات والثوابت (Configuration)
  var CONFIG = {
    TIMEOUT_MS: 9000,
    ANIMATION_DURATION_MS: 650,
    POLLING_INTERVAL_MS: 5 * 60 * 1000, // 5 دقائق
    CACHE_KEY: "femalwaed_dashboard_swr_cache_v2",
    GENDER: "Female",
    // قواميس مرنة لمطابقة الحالات القياسية والبديلة (Dynamic Canonical Status Synonyms)
    STATUS_SYNONYMS: {
      new: ["new", "جديد", "طلب جديد", "new application", "draft", "مقدم"],
      scheduled: ["scheduling an appointment", "scheduling", "مجدول", "تحديد موعد", "appointment scheduled", "scheduled", "في انتظار المقابلة"],
      referred: ["referred for the exam", "referred", "محال للاختبار", "محال للامتحان", "exam referral", "محال"],
      passed: ["successful in the written exam", "passed written", "ناجح في التحريري", "اجتاز التحريري", "passed", "ناجح تحريري"],
      approved: ["approved", "معتمد", "تم الاعتماد", "certified", "مقبول نهائي", "ناجح"],
      failedwritten: ["failed written", "راسب في التحريري", "لم يجتز التحريري", "failed", "راسب تحريري", "مرفوض"]
    },
    ALLOWED_DOCTYPES: ["waed_info", "exam_group_date"]
  };

  // 2. إدارة الحالة (State Management)
  var STATE = {
    isRefreshing: false,
    hasCachedData: false,
    counts: {
      total: 0,
      new: 0,
      scheduled: 0,
      referred: 0,
      passed: 0,
      approved: 0,
      failedwritten: 0,
      exam_groups: 0
    }
  };

  // 3. خدمة مطابقة وتطبيع الحالات بمرونة (Status Normalizer Engine)
  var StatusEngine = {
    normalize: function (str) {
      if (!str) return "";
      return String(str).trim().toLowerCase().replace(/[\s_-]+/g, " ");
    },

    matchCategory: function (rawStatus) {
      var normalized = StatusEngine.normalize(rawStatus);
      if (!normalized) return "new";

      var categories = Object.keys(CONFIG.STATUS_SYNONYMS);
      for (var i = 0; i < categories.length; i++) {
        var cat = categories[i];
        var synonyms = CONFIG.STATUS_SYNONYMS[cat];
        for (var j = 0; j < synonyms.length; j++) {
          var syn = StatusEngine.normalize(synonyms[j]);
          if (normalized === syn || normalized.indexOf(syn) !== -1 || syn.indexOf(normalized) !== -1) {
            return cat;
          }
        }
      }
      console.warn("[Femalwaed Dashboard] Unrecognized status value from database:", rawStatus);
      return null;
    }
  };

  // 4. خدمة البيانات والاتصال بقاعدة بيانات Frappe (Single Aggregated API Service)
  var APIService = {
    fetchAggregatedStats: function () {
      if (!window.frappe || !frappe.call) {
        return Promise.reject(new Error("Frappe environment unavailable"));
      }

      // محاولة 1: استدعاء الـ Whitelisted Method من تطبيق taq_it (مع كتم التنبيهات المزعجة في حال عدم إعادة تشغيل الخادم)
      var tryWhitelistedMethod = new Promise(function (resolve, reject) {
        frappe.call({
          method: "taq_it.api.get_dashboard_stats",
          args: { gender: CONFIG.GENDER },
          timeout: 3000,
          error: function (r) {
            if (r) r.exc = null;
            reject(new Error("Method taq_it.api not loaded"));
          }
        }).then(function (r) {
          if (r && r.message && r.message.success) {
            resolve(r.message);
          } else {
            // محاولة المسار المزدوج taq_it.taq_it.api
            frappe.call({
              method: "taq_it.taq_it.api.get_dashboard_stats",
              args: { gender: CONFIG.GENDER },
              timeout: 2000,
              error: function (r2) {
                if (r2) r2.exc = null;
                reject(new Error("Method not found"));
              }
            }).then(function (r2) {
              if (r2 && r2.message && r2.message.success) resolve(r2.message);
              else reject(new Error("Method not found"));
            }).catch(reject);
          }
        }).catch(reject);
      });

      var tryReportviewGroupBy = new Promise(function (resolve, reject) {
        var p1 = frappe.call({
          method: "frappe.desk.reportview.get",
          args: {
            doctype: "waed_info",
            fields: ["waed_status", "count(name) as count"],
            filters: [["gender", "=", CONFIG.GENDER]],
            group_by: "waed_status",
            limit: 100
          }
        });

        var p2 = frappe.call({
          method: "frappe.desk.reportview.get",
          args: {
            doctype: "exam_group_date",
            fields: ["count(name) as count"],
            filters: [["exam_status", "=", "Scheduled"]],
            limit: 1
          }
        }).catch(function () { return { message: { values: [[0]] } }; });

        Promise.all([p1, p2])
          .then(function (results) {
            var statusData = (results[0] && results[0].message) || {};
            var examData = (results[1] && results[1].message) || {};

            var parsedCounts = {
              total: 0,
              new: 0,
              scheduled: 0,
              referred: 0,
              passed: 0,
              approved: 0,
              failedwritten: 0,
              exam_groups: 0
            };

            var values = statusData.values || [];
            values.forEach(function (row) {
              var rawStatus = row[0] || "New";
              var count = parseInt(row[1], 10) || 0;
              parsedCounts.total += count;

              var category = StatusEngine.matchCategory(rawStatus);
              if (category && parsedCounts[category] !== undefined) {
                parsedCounts[category] += count;
              }
            });

            if (examData.values && examData.values[0]) {
              parsedCounts.exam_groups = parseInt(examData.values[0][0], 10) || 0;
            }

            resolve(parsedCounts);
          })
          .catch(reject);
      });

      return tryWhitelistedMethod
        .then(function (res) {
          var mapped = {
            total: res.total || 0,
            new: 0,
            scheduled: 0,
            referred: 0,
            passed: 0,
            approved: 0,
            failedwritten: 0,
            exam_groups: res.exam_groups || 0
          };
          if (res.status_counts) {
            Object.keys(res.status_counts).forEach(function (rawSt) {
              var cnt = res.status_counts[rawSt];
              var cat = StatusEngine.matchCategory(rawSt);
              if (cat && mapped[cat] !== undefined) {
                mapped[cat] += cnt;
              }
            });
          }
          return mapped;
        })
        .catch(function () {
          return tryReportviewGroupBy;
        })
        .catch(function () {
          return APIService.fetchFallbackIndividualCounts();
        });
    },

    fetchCountWithTimeout: function (doctype, filters) {
      if (!window.frappe || !frappe.db || !frappe.db.count) {
        return Promise.resolve(0);
      }
      return new Promise(function (resolve) {
        var queryFilters = filters ? Object.assign({}, filters) : {};
        frappe.db.count(doctype, Object.keys(queryFilters).length > 0 ? { filters: queryFilters } : {})
          .then(function (count) { resolve(typeof count === "number" ? count : 0); })
          .catch(function () {
            if (queryFilters.gender) {
              var fallback = Object.assign({}, queryFilters);
              delete fallback.gender;
              frappe.db.count(doctype, Object.keys(fallback).length > 0 ? { filters: fallback } : {})
                .then(function (c) { resolve(typeof c === "number" ? c : 0); })
                .catch(function () { resolve(0); });
            } else {
              resolve(0);
            }
          });
        setTimeout(function () { resolve(0); }, CONFIG.TIMEOUT_MS);
      });
    },

    fetchFallbackIndividualCounts: function () {
      var g = CONFIG.GENDER;
      return Promise.all([
        APIService.fetchCountWithTimeout("waed_info", { gender: g }),
        APIService.fetchCountWithTimeout("waed_info", { waed_status: "New", gender: g }),
        APIService.fetchCountWithTimeout("waed_info", { waed_status: "Scheduling an appointment", gender: g }),
        APIService.fetchCountWithTimeout("waed_info", { waed_status: "referred for the exam", gender: g }),
        APIService.fetchCountWithTimeout("waed_info", { waed_status: "Successful in the written exam", gender: g }),
        APIService.fetchCountWithTimeout("waed_info", { waed_status: "Approved", gender: g }),
        APIService.fetchCountWithTimeout("waed_info", { waed_status: "Failed Written", gender: g }),
        APIService.fetchCountWithTimeout("exam_group_date", { exam_status: "Scheduled" })
      ]).then(function (res) {
        return {
          total: res[0],
          new: res[1],
          scheduled: res[2],
          referred: res[3],
          passed: res[4],
          approved: res[5],
          failedwritten: res[6],
          exam_groups: res[7]
        };
      });
    },

    fetchFollowups: function () {
      var gender = CONFIG.GENDER;
      var count = function (doctype, filters) { return APIService.fetchCountWithTimeout(doctype, filters); };
      var missing = new Promise(function (resolve) {
        if (!window.frappe || !frappe.model || !frappe.model.with_doctype || !frappe.call) return resolve(null);
        frappe.model.with_doctype("waed_info", function () {
          var meta = frappe.get_meta && frappe.get_meta("waed_info"), fields = (meta && meta.fields) || [];
          var find = function (words) {
            return fields.find(function (f) {
              var text = ((f.fieldname || "") + " " + (f.label || "")).replace(/[\s_-]/g, "").toLowerCase();
              return words.some(function (w) { return text.indexOf(w) !== -1; });
            });
          };
          var phone = find(["phone", "mobile", "الهاتف", "رقمالهاتف"]),
              national = find(["national", "nationalid", "الرقمالوطني"]),
              address = find(["address", "residence", "عنوانالسكن", "السكن"]);
          var available = [phone, national, address].filter(Boolean).map(function (f) { return [f.fieldname, "is", "not set"]; });
          if (!available.length) return resolve(null);
          frappe.call({
            method: "frappe.desk.reportview.get_count",
            args: { doctype: "waed_info", filters: JSON.stringify([["gender", "=", gender]]), or_filters: JSON.stringify(available), distinct: 1, limit: 0 }
          }).then(function (r) {
            resolve(typeof r.message === "number" ? r.message : 0);
          }).catch(function () { resolve(null); });
        });
      });
      return Promise.all([
        count("waed_info", { waed_status: ["in", ["New", "Scheduling an appointment"]], gender: gender }),
        count("exam_group_date", { exam_status: ["in", ["Written In Progress", "Oral In Progress"]] }),
        missing
      ]);
    }
  };

  // 5. إدارة التخزين المؤقت اللحظي (Stale-While-Revalidate Cache Manager)
  var CacheManager = {
    loadCachedState: function () {
      try {
        var raw = sessionStorage.getItem(CONFIG.CACHE_KEY);
        if (!raw) return false;
        var data = JSON.parse(raw);
        if (data && data.counts && typeof data.counts.total === "number") {
          STATE.counts = Object.assign({}, data.counts);
          STATE.hasCachedData = true;
          return true;
        }
      } catch (e) {
        console.warn("[Femalwaed Dashboard] Cache read skipped:", e);
      }
      return false;
    },

    saveState: function () {
      try {
        sessionStorage.setItem(CONFIG.CACHE_KEY, JSON.stringify({
          counts: STATE.counts,
          timestamp: Date.now()
        }));
      } catch (e) {
        // فشل التخزين المؤقت
      }
    }
  };

  // 6. منطق العرض وتحديث الواجهة (UI Presenter & Smooth Digit Animators)
  var UIPresenter = {
    formatDigits: function (val) {
      if (val === null || val === undefined) return "0";
      return String(val).replace(/[٠-٩]/g, function (d) {
        return d.charCodeAt(0) - 1632;
      });
    },

    animateNumber: function (el, targetValue, isInstant) {
      if (!el) return;
      el.classList.remove("is-loading");
      el.setAttribute("dir", "ltr");
      el.setAttribute("lang", "en");

      if (typeof targetValue !== "number" || isNaN(targetValue)) {
        el.textContent = "0";
        return;
      }

      if (isInstant) {
        el.textContent = UIPresenter.formatDigits(targetValue);
        return;
      }

      var currentNum = parseInt(el.textContent.replace(/[^0-9]/g, ""), 10) || 0;
      var startValue = currentNum;
      var startTime = null;
      var animDuration = CONFIG.ANIMATION_DURATION_MS;

      function step(timestamp) {
        if (!startTime) startTime = timestamp;
        var progress = Math.min((timestamp - startTime) / animDuration, 1);
        var easeProgress = 1 - Math.pow(1 - progress, 3);
        var current = Math.round(startValue + (targetValue - startValue) * easeProgress);

        el.textContent = UIPresenter.formatDigits(current);

        if (progress < 1) {
          window.requestAnimationFrame(step);
        } else {
          el.textContent = UIPresenter.formatDigits(targetValue);
        }
      }

      window.requestAnimationFrame(step);
    },

    setCount: function (selector, value, isInstant) {
      var targetEl = root.querySelector(selector);
      if (!targetEl) return;
      var numEl = targetEl.querySelector(".tq-count-value") || targetEl;
      UIPresenter.animateNumber(numEl, typeof value === "number" ? value : 0, isInstant);
    },

    setText: function (selector, text) {
      var targetEl = root.querySelector(selector);
      if (!targetEl) return;
      var numEl = targetEl.querySelector(".tq-count-value") || targetEl;
      numEl.classList.remove("is-loading");
      numEl.setAttribute("dir", "ltr");
      numEl.setAttribute("lang", "en");
      numEl.textContent = UIPresenter.formatDigits(text);
    },

    setError: function (selector) {
      var targetEl = root.querySelector(selector);
      if (!targetEl) return;
      var numEl = targetEl.querySelector(".tq-count-value") || targetEl;
      numEl.classList.remove("is-loading");
      numEl.textContent = "—";
    },

    updateAlertBanner: function (newCount) {
      var box = root.querySelector("#twd-waed-alerts-box");
      var alertItem = root.querySelector("#alert-new-waed");
      if (!box || !alertItem) return;

      if (newCount > 0) {
        var countEl = alertItem.querySelector(".twd-alert-count");
        if (countEl) {
          countEl.setAttribute("dir", "ltr");
          countEl.setAttribute("lang", "en");
          countEl.textContent = UIPresenter.formatDigits(newCount);
        }
        alertItem.style.display = "flex";
        box.style.display = "block";
      } else {
        alertItem.style.display = "none";
        box.style.display = "none";
      }
    },

    calculateSuccessRate: function () {
      var decided = STATE.counts.approved + STATE.counts.failedwritten;
      if (decided > 0) {
        return Math.round((STATE.counts.approved / decided) * 100);
      }
      if (STATE.counts.total > 0 && STATE.counts.approved > 0) {
        return Math.round((STATE.counts.approved / STATE.counts.total) * 100);
      }
      return null;
    },

    renderAll: function (isInstant) {
      UIPresenter.setCount("#stat-total", STATE.counts.total, isInstant);
      UIPresenter.setCount("#stat-new-kpi", STATE.counts.new, isInstant);
      UIPresenter.setCount("#stat-pipe-scheduled", STATE.counts.scheduled, isInstant);
      UIPresenter.setCount("#stat-referred-kpi", STATE.counts.referred, isInstant);
      UIPresenter.setCount("#stat-pipe-passed", STATE.counts.passed, isInstant);
      UIPresenter.setCount("#stat-approved", STATE.counts.approved, isInstant);
      UIPresenter.setCount("#stat-rejected", STATE.counts.failedwritten, isInstant);
      UIPresenter.setCount("#stat-exam-groups", STATE.counts.exam_groups, isInstant);

      var rate = UIPresenter.calculateSuccessRate();
      UIPresenter.setText("#stat-success-rate", rate === null ? "—" : UIPresenter.formatDigits(rate) + "%");
      UIPresenter.updateSuccessRateRing(rate);
      UIPresenter.updateAlertBanner(STATE.counts.new);
      UIPresenter.normalizeAllDigits();
    },

    updateSuccessRateRing: function (rate) {
      var ring = root.querySelector("#stat-success-rate .wd-rate-ring");
      if (!ring) return;
      var value = typeof rate === "number" && isFinite(rate) ? Math.max(0, Math.min(100, rate)) : 0;
      ring.style.setProperty("--rate-progress", value + "%");
      ring.classList.remove("rate--good", "rate--mid", "rate--low", "rate--neutral");
      ring.classList.add(rate === null ? "rate--neutral" : value >= 75 ? "rate--good" : value >= 50 ? "rate--mid" : "rate--low");
      ring.setAttribute("aria-label", rate === null ? "نسبة النجاح غير متاحة" : "نسبة النجاح " + UIPresenter.formatDigits(value) + " بالمائة");
    },

    normalizeAllDigits: function () {
      if (!root) return;
      var walker = document.createTreeWalker(root, NodeFilter.SHOW_TEXT, null, false);
      var node;
      while ((node = walker.nextNode())) {
        if (/[٠-٩]/.test(node.nodeValue)) {
          node.nodeValue = node.nodeValue.replace(/[٠-٩]/g, function (d) {
            return String(d.charCodeAt(0) - 1632);
          });
        }
      }
    },

    setRefreshSpinning: function (isSpinning) {
      var icon = root.querySelector(".wd-icon-refresh");
      if (icon) {
        if (isSpinning) icon.classList.add("is-spinning");
        else icon.classList.remove("is-spinning");
      }
    }
  };

  // 7. موجه الروابط والتنقل الآمن (Router)
  var Router = {
    navigate: function (target) {
      var doctype = target.getAttribute("data-doctype");
      if (!doctype || CONFIG.ALLOWED_DOCTYPES.indexOf(doctype) === -1) return;

      if (target.getAttribute("data-action") === "new") {
        if (window.frappe && frappe.new_doc) {
          frappe.new_doc(doctype);
        } else {
          window.location.href = "/app/" + encodeURIComponent(doctype.toLowerCase().replace(/ /g, "-")) + "/new";
        }
        return;
      }

      var filters = {};
      try {
        var rawFilters = target.getAttribute("data-filters");
        if (rawFilters) {
          filters = JSON.parse(rawFilters);
        }
      } catch (err) {
        filters = {};
      }

      if (window.frappe && frappe.set_route) {
        frappe.route_options = filters;
        frappe.set_route("list", doctype, filters);
      } else {
        var query = Object.keys(filters).length > 0 ? "?" + new URLSearchParams(filters).toString() : "";
        window.location.href = "/app/" + encodeURIComponent(doctype.toLowerCase().replace(/ /g, "-")) + query;
      }
    }
  };

  // 8. المتحكم الدوري الذكي (Smart Periodic Poller with Page Visibility)
  var Poller = {
    timer: null,
    start: function () {
      Poller.stop();
      Poller.timer = setInterval(function () {
        if (document.visibilityState === "visible" && !STATE.isRefreshing) {
          loadDashboardData(false);
        }
      }, CONFIG.POLLING_INTERVAL_MS);
    },
    stop: function () {
      if (Poller.timer) {
        clearInterval(Poller.timer);
        Poller.timer = null;
      }
    }
  };
  root.__femalwaed_poller = Poller;

  // 9. تهيئة الأحداث (Event Controller)
  function initEvents() {
    if (root.__femalwaed_events_bound) return;
    root.__femalwaed_events_bound = true;

    root.addEventListener("click", function (e) {
      var refreshBtn = e.target.closest("#btn-waed-refresh");
      if (refreshBtn) {
        e.preventDefault();
        loadDashboardData(true);
        return;
      }

      var navTarget = e.target.closest("[data-doctype]");
      if (navTarget) {
        e.preventDefault();
        Router.navigate(navTarget);
      }
    });

    root.addEventListener("keydown", function (e) {
      if (e.key === "Enter" || e.key === " ") {
        var target = e.target.closest("[data-doctype], #btn-waed-refresh");
        if (target) {
          e.preventDefault();
          target.click();
        }
      }
    });

    document.addEventListener("visibilitychange", function () {
      if (document.visibilityState === "visible") {
        loadDashboardData(false);
        Poller.start();
      } else {
        Poller.stop();
      }
    });
  }

  // 10. دورة تحميل البيانات (Lifecycle Runner)
  function loadDashboardData(isManualRefresh) {
    if (STATE.isRefreshing) return;
    STATE.isRefreshing = true;

    if (isManualRefresh) {
      UIPresenter.setRefreshSpinning(true);
    }

    APIService.fetchAggregatedStats()
      .then(function (freshCounts) {
        STATE.counts = freshCounts;
        CacheManager.saveState();
        UIPresenter.renderAll(false);
      })
      .catch(function (err) {
        console.error("[Femalwaed Dashboard] Load error:", err);
        if (!STATE.hasCachedData) {
          [
            "#stat-total",
            "#stat-new-kpi",
            "#stat-pipe-scheduled",
            "#stat-referred-kpi",
            "#stat-pipe-passed",
            "#stat-approved",
            "#stat-success-rate",
            "#stat-rejected",
            "#stat-exam-groups"
          ].forEach(UIPresenter.setError);
        }
      })
      .finally(function () {
        STATE.isRefreshing = false;
        if (isManualRefresh) {
          setTimeout(function () {
            UIPresenter.setRefreshSpinning(false);
          }, 400);
        }
      });
  }

  // 11. الإقلاع الفوري والتنفيذ اللحظي (Instant Boot via SWR)
  initEvents();

  var hasCache = CacheManager.loadCachedState();
  if (hasCache) {
    UIPresenter.renderAll(true);
  }

  loadDashboardData(false);
  Poller.start();
})();

style:
/* ==========================================================================
   لوحة قسم الواعظات - FEMALE WAED DASHBOARD
   Modern Minimal + Bento + Editorial/Swiss Design Architecture
   ========================================================================== */

@import url('https://fonts.googleapis.com/css2?family=Poppins:wght@300;400;500;600;700;800;900&display=swap');

.waed-dash {
  --wd-font: 'GE SS Two';

  /* Neutrals (Light Mode) */
  --wd-bg-canvas:      transparent;
  --wd-bg-surface:     #ffffff;
  --wd-bg-subtle:      #f8fafc;
  --wd-bg-card-inner:  #ffffff;
  --wd-bg-island:      #f8fafc;

  --wd-text-primary:   #0f172a;
  --wd-text-secondary: #334155;
  --wd-text-muted:     #64748b;
  --wd-text-subtle:    #94a3b8;

  --wd-border-light:   #f1f5f9;
  --wd-border-default: #e2e8f0;
  --wd-border-focus:   #38bdf8;

  /* Brand Colors (Light Oceanic Blue) */
  --wd-sky-600:        #0284c7;
  --wd-sky-500:        #0ea5e9;
  --wd-sky-400:        #38bdf8;
  --wd-sky-200:        #bae6fd;
  --wd-sky-100:        #e0f2fe;
  --wd-sky-50:         #f0f9ff;

  /* Semantic Stages */
  --wd-stage-blue:     #0284c7;
  --wd-stage-blue-bg:  #f0f9ff;
  --wd-stage-blue-bd:  #bae6fd;

  --wd-stage-amber:    #d97706;
  --wd-stage-amber-bg: #fffbeb;
  --wd-stage-amber-bd: #fde68a;

  --wd-stage-indigo:   #4f46e5;
  --wd-stage-indigo-bg:#eef2ff;
  --wd-stage-indigo-bd:#c7d2fe;

  --wd-stage-teal:     #0d9488;
  --wd-stage-teal-bg:  #f0fdfa;
  --wd-stage-teal-bd:  #99f6e4;

  --wd-stage-emerald:  #059669;
  --wd-stage-emerald-bg:#ecfdf5;
  --wd-stage-emerald-bd:#a7f3d0;

  --wd-stage-rose:     #e11d48;
  --wd-stage-rose-bg:  #fff1f2;
  --wd-stage-rose-bd:  #fecdd3;

  /* Radii */
  --wd-radius-sm:      8px;
  --wd-radius-md:      12px;
  --wd-radius-lg:      14px;
  --wd-radius-xl:      20px;
  --wd-radius-pill:    9999px;

  /* Shadows */
  --wd-shadow-sm:      0 1px 3px 0 rgba(15, 23, 42, 0.03), 0 1px 2px -1px rgba(15, 23, 42, 0.02);
  --wd-shadow-bento:   0 1px 4px 0 rgba(15, 23, 42, 0.04);
  --wd-shadow-hover:   0 10px 24px -4px rgba(2, 132, 199, 0.08), 0 2px 6px -1px rgba(15, 23, 42, 0.03);

  --wd-transition:     all 0.22s cubic-bezier(0.16, 1, 0.3, 1);

  font-family: var(--wd-font) !important;
  color: var(--wd-text-secondary);
  background: var(--wd-bg-canvas);
  direction: rtl;
  text-align: right;
  line-height: 1.5;
  box-sizing: border-box;
  -webkit-font-smoothing: antialiased;
}

/* ==========================================================================
   دعم الوضع الليلي في نظام Frappe (Dark Mode Support)
   ========================================================================== */
[data-theme="dark"] .waed-dash,
body[data-theme="dark"] .waed-dash,
.theme-dark .waed-dash {
  --wd-bg-surface:     #111827;
  --wd-bg-subtle:      #1f2937;
  --wd-bg-card-inner:  #162032;
  --wd-bg-island:      #1f2937;

  --wd-text-primary:   #f8fafc;
  --wd-text-secondary: #cbd5e1;
  --wd-text-muted:     #94a3b8;
  --wd-text-subtle:    #64748b;

  --wd-border-light:   #1f2937;
  --wd-border-default: #334155;
  --wd-border-focus:   #38bdf8;

  --wd-sky-50:         #0c4a6e;
  --wd-sky-100:        #075985;
  --wd-sky-200:        #0284c7;

  --wd-stage-blue-bg:  #0c4a6e;
  --wd-stage-blue-bd:  #0284c7;

  --wd-stage-amber-bg: #451a03;
  --wd-stage-amber-bd: #92400e;

  --wd-stage-indigo-bg:#1e1b4b;
  --wd-stage-indigo-bd:#3730a3;

  --wd-stage-teal-bg:  #042f2e;
  --wd-stage-teal-bd:  #115e59;

  --wd-stage-emerald-bg:#022c22;
  --wd-stage-emerald-bd:#065f46;

  --wd-stage-rose-bg:  #4c0519;
  --wd-stage-rose-bd:  #9f1239;

  --wd-shadow-sm:      0 1px 3px 0 rgba(0, 0, 0, 0.3);
  --wd-shadow-bento:   0 4px 16px -2px rgba(0, 0, 0, 0.4);
  --wd-shadow-hover:   0 16px 32px -4px rgba(2, 132, 199, 0.25);
}

/* 1. تطبيق خط GE SS Two لجميع النصوص والعناصر بالكامل */
.waed-dash,
.waed-dash *,
.waed-dash *::before,
.waed-dash *::after,
.waed-dash h1,
.waed-dash h2,
.waed-dash h3,
.waed-dash h4,
.waed-dash p,
.waed-dash span,
.waed-dash a,
.waed-dash div,
.waed-dash strong,
.waed-dash button,
.waed-dash label {
  font-family: 'GE SS Two' !important;
  box-sizing: border-box;
}

/* 2. استثناء الأرقام فقط: خط Poppins الصريح والأرقام القياسية 1234 دائماً */
.tq-count-value,
.tq-count-value *,
.wd-bento-hero-number,
.wd-bento-hero-number *,
.wd-bento-card-number,
.wd-bento-card-number *,
.wd-pipe-num,
.wd-pipe-num *,
.wd-stage-count,
.wd-stage-count *,
.wd-failed-count,
.wd-failed-count *,
.twd-alert-count,
.wd-pipe-step-badge,
.wd-stage-step,
.num,
.number,
.digits,
.stat-number,
[data-num] {
  font-family: 'Poppins', sans-serif !important;
  font-feature-settings: "locl" 0, "numr" 0, "lnum" 1, "tnum" 1 !important;
  font-variant-numeric: lining-nums tabular-nums !important;
  direction: ltr !important;
  unicode-bidi: isolate !important;
  display: inline-block;
}

/* الأرقام وحقول الإدخال */
.waed-dash .app-number,
.waed-dash input[type="number"],
.waed-dash input[inputmode="numeric"],
.waed-dash input[inputmode="decimal"],
.waed-dash input[type="tel"] {
  font-family: 'Poppins', sans-serif !important;
  font-feature-settings: "locl" 0, "lnum" 1, "tnum" 1 !important;
  font-variant-numeric: lining-nums tabular-nums !important;
  direction: ltr;
  unicode-bidi: isolate;
}

/* إزالة أي خط سفلي */
.waed-dash a,
.waed-dash a:hover,
.waed-dash a:focus,
.waed-dash a:active,
.waed-dash a:visited,
.waed-dash a *,
.waed-dash a:hover *,
.waed-dash button,
.waed-dash button * {
  text-decoration: none !important;
  text-decoration-line: none !important;
}

/* ==========================================================================
   شريط التنبيهات الذكي (Smart Alert Bar)
   ========================================================================== */
.wd-alert-bar {
  width: 100%;
  margin-bottom: 12px;
}

.wd-alert-pill {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 10px 18px;
  background: var(--wd-stage-rose-bg);
  border: 1px solid var(--wd-stage-rose-bd);
  border-radius: var(--wd-radius-md);
  color: var(--wd-stage-rose);
  cursor: pointer;
  transition: var(--wd-transition);
}

.wd-alert-pill:hover {
  background: #ffe4e6;
  border-color: #fda4af;
  transform: translateY(-1px);
}

.wd-alert-content {
  display: flex;
  align-items: center;
  gap: 10px;
}

.wd-pulse-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--wd-stage-rose);
  animation: wdPulse 1.8s infinite ease-in-out;
}

@keyframes wdPulse {
  0% { transform: scale(0.95); opacity: 0.7; }
  50% { transform: scale(1.3); opacity: 1; box-shadow: 0 0 8px rgba(225, 29, 72, 0.4); }
  100% { transform: scale(0.95); opacity: 0.7; }
}

.wd-alert-tag {
  font-size: 0.72rem;
  font-weight: 800;
  background: #ffffff;
  padding: 2px 8px;
  border-radius: var(--wd-radius-pill);
  border: 1px solid var(--wd-stage-rose-bd);
  color: var(--wd-stage-rose);
}

.wd-alert-msg {
  font-size: 0.86rem;
  font-weight: 600;
  color: var(--wd-text-primary);
}

.wd-alert-msg strong {
  color: var(--wd-stage-rose);
  font-weight: 800;
}

.wd-alert-cta {
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: 0.82rem;
  font-weight: 700;
  color: var(--wd-stage-rose);
}

.wd-cta-bubble {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 22px;
  height: 22px;
  border-radius: 50%;
  background: rgba(225, 29, 72, 0.1);
}

.wd-cta-bubble svg {
  width: 12px;
  height: 12px;
}

/* ==========================================================================
   الهيكل العام للحاوية (Dashboard Shell)
   ========================================================================== */
.wd-shell {
  display: flex;
  flex-direction: column;
  gap: 16px;
  width: 100%;
}

/* ==========================================================================
   ترويسة القيادة والعمليات (Executive Island Header)
   ========================================================================== */
.wd-header-island {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  padding: 16px 20px;
  background: var(--wd-bg-surface);
  border: 1px solid var(--wd-border-default);
  border-radius: var(--wd-radius-lg);
  box-shadow: var(--wd-shadow-sm);
}

.wd-header-brand {
  display: flex;
  align-items: center;
  gap: 14px;
}

.wd-avatar-core {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 44px;
  height: 44px;
  border-radius: var(--wd-radius-md);
  background: var(--wd-sky-50);
  border: 1px solid var(--wd-sky-200);
  color: var(--wd-sky-600);
  flex-shrink: 0;
}

.wd-avatar-core svg {
  width: 22px;
  height: 22px;
}

.wd-brand-text {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.wd-status-badge-row {
  display: flex;
  align-items: center;
  gap: 8px;
}

.wd-badge-brand {
  font-size: 0.72rem;
  font-weight: 800;
  color: var(--wd-sky-600);
  background: var(--wd-sky-50);
  padding: 2px 8px;
  border-radius: 4px;
  border: 1px solid var(--wd-sky-200);
}

.wd-main-title {
  font-size: 1.35rem;
  font-weight: 900;
  color: var(--wd-text-primary);
  margin: 0;
  line-height: 1.25;
}

.wd-main-subtitle {
  font-size: 0.82rem;
  font-weight: 500;
  color: var(--wd-text-muted);
  margin: 0;
}

.wd-header-actions {
  display: flex;
  align-items: center;
  gap: 10px;
  flex-shrink: 0;
}

.wd-btn-island {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  padding: 8px 14px;
  border-radius: var(--wd-radius-sm);
  font-size: 0.84rem;
  font-weight: 700;
  cursor: pointer;
  transition: var(--wd-transition);
  border: 1px solid transparent;
}

.wd-btn-ghost {
  background: var(--wd-bg-subtle);
  border-color: var(--wd-border-default);
  color: var(--wd-text-secondary);
}

.wd-btn-ghost:hover {
  background: #f1f5f9;
  color: var(--wd-text-primary);
  border-color: #cbd5e1;
}

.wd-btn-secondary {
  background: var(--wd-sky-50);
  border-color: var(--wd-sky-200);
  color: var(--wd-sky-600);
}

.wd-btn-secondary:hover {
  background: var(--wd-sky-100);
  border-color: var(--wd-sky-400);
  color: #0369a1;
}

.wd-btn-primary {
  background: var(--wd-sky-600);
  color: #ffffff;
  border-color: var(--wd-sky-600);
  box-shadow: 0 1px 3px rgba(2, 132, 199, 0.2);
}

.wd-btn-primary:hover {
  background: #0369a1;
  border-color: #0369a1;
  box-shadow: 0 4px 12px rgba(2, 132, 199, 0.25);
  transform: translateY(-1px);
}

.wd-btn-icon-bubble {
  display: flex;
  align-items: center;
  justify-content: center;
}

.wd-btn-icon-bubble svg {
  width: 15px;
  height: 15px;
}

.wd-btn-text {
  display: inline-block;
}

.wd-icon-refresh.is-spinning {
  animation: wdSpin 0.75s linear infinite;
}

@keyframes wdSpin {
  from { transform: rotate(0deg); }
  to { transform: rotate(-360deg); }
}

/* ==========================================================================
   شبكة بينتو للمؤشرات الاستراتيجية (Executive Bento Grid)
   ========================================================================== */
.wd-bento-hero-grid {
  display: grid;
  grid-template-columns: 1.35fr 1fr 1fr;
  gap: 14px;
  width: 100%;
}

.wd-bento-card {
  display: flex;
  flex-direction: column;
  background: var(--wd-bg-surface);
  border: 1px solid var(--wd-border-default);
  border-radius: var(--wd-radius-lg);
  box-shadow: var(--wd-shadow-sm);
  padding: 18px 20px;
  text-decoration: none;
  cursor: pointer;
  transition: var(--wd-transition);
  position: relative;
  overflow: hidden;
}

.wd-bento-card:hover {
  border-color: var(--wd-border-focus);
  box-shadow: var(--wd-shadow-hover);
  transform: translateY(-2px);
}

.wd-bento-total {
  /* Card specific highlight */
}

.wd-bento-rate {
  /* Rate specific highlight */
}

.wd-bento-exams {
  /* Exams specific highlight */
}

.wd-bento-inner {
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  height: 100%;
  gap: 12px;
}

.wd-bento-top {
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.wd-bento-icon-box {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 36px;
  height: 36px;
  border-radius: var(--wd-radius-md);
  flex-shrink: 0;
}

.wd-bento-icon-box svg {
  width: 18px;
  height: 18px;
}

.wd-icon-sky {
  background: var(--wd-sky-50);
  border: 1px solid var(--wd-sky-200);
  color: var(--wd-sky-600);
}

.wd-icon-teal {
  background: var(--wd-stage-teal-bg);
  border: 1px solid var(--wd-stage-teal-bd);
  color: var(--wd-stage-teal);
}

.wd-icon-amber {
  background: var(--wd-stage-amber-bg);
  border: 1px solid var(--wd-stage-amber-bd);
  color: var(--wd-stage-amber);
}

.wd-bento-tag {
  font-size: 0.72rem;
  font-weight: 800;
  color: var(--wd-sky-600);
  background: var(--wd-sky-50);
  border: 1px solid var(--wd-sky-200);
  padding: 2px 8px;
  border-radius: var(--wd-radius-pill);
}

.wd-tag-teal {
  color: var(--wd-stage-teal);
  background: var(--wd-stage-teal-bg);
  border-color: var(--wd-stage-teal-bd);
}

.wd-tag-amber {
  color: var(--wd-stage-amber);
  background: var(--wd-stage-amber-bg);
  border-color: var(--wd-stage-amber-bd);
}

.wd-bento-center {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.wd-bento-hero-number {
  font-size: 2.3rem;
  font-weight: 900;
  line-height: 1.1;
  color: var(--wd-text-primary);
}

.wd-bento-label {
  font-size: 0.84rem;
  font-weight: 600;
  color: var(--wd-text-muted);
}

.wd-bento-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding-top: 10px;
  border-top: 1px solid var(--wd-border-light);
  font-size: 0.78rem;
  font-weight: 700;
  color: var(--wd-text-muted);
}

.wd-footer-action-text {
  color: var(--wd-sky-600);
}

.wd-footer-arrow {
  color: var(--wd-sky-600);
  transition: transform 0.2s ease;
}

.wd-bento-card:hover .wd-footer-arrow {
  transform: translateX(-4px);
}

.wd-footer-hint {
  font-size: 0.74rem;
  color: var(--wd-text-subtle);
}

/* مؤشر النسبة الدائري (Radial Progress Ring) */
.wd-rate-ring {
  position: relative;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 68px;
  height: 68px;
  border-radius: 50%;
  background: conic-gradient(
    var(--ring-color, #0284c7) var(--rate-progress, 0%),
    var(--wd-border-default) var(--rate-progress, 0%) 100%
  );
  margin-bottom: 4px;
}

.wd-rate-ring::before {
  content: "";
  position: absolute;
  inset: 6px;
  border-radius: 50%;
  background: var(--wd-bg-surface);
}

.wd-rate-ring .wd-bento-hero-number {
  position: relative;
  z-index: 2;
  font-size: 1.15rem;
  font-weight: 900;
  margin: 0;
}

.wd-rate-ring.rate--good { --ring-color: #059669; }
.wd-rate-ring.rate--mid  { --ring-color: #0284c7; }
.wd-rate-ring.rate--low  { --ring-color: #d97706; }
.wd-rate-ring.rate--neutral { --ring-color: #94a3b8; }

/* ==========================================================================
   مسار رحلة وتأهيل الواعظات (5-Stage Pipeline)
   ========================================================================== */
.wd-pipeline-bento-section {
  display: flex;
  flex-direction: column;
  gap: 12px;
  background: var(--wd-bg-surface);
  border: 1px solid var(--wd-border-default);
  border-radius: var(--wd-radius-lg);
  padding: 18px 20px;
  box-shadow: var(--wd-shadow-sm);
}

.wd-section-header-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.wd-section-titles {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.wd-section-tag-wrap {
  display: flex;
  align-items: center;
  gap: 8px;
}

.wd-section-badge {
  font-size: 0.72rem;
  font-weight: 800;
  color: var(--wd-sky-600);
  background: var(--wd-sky-50);
  border: 1px solid var(--wd-sky-200);
  padding: 2px 8px;
  border-radius: 4px;
}

.wd-section-heading {
  font-size: 1.15rem;
  font-weight: 900;
  color: var(--wd-text-primary);
  margin: 0;
}

.wd-section-desc {
  font-size: 0.8rem;
  color: var(--wd-text-muted);
  margin: 0;
}

.wd-pipeline-bento-grid {
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  gap: 10px;
  width: 100%;
}

.wd-stage-card {
  display: flex;
  flex-direction: column;
  background: var(--wd-bg-subtle);
  border: 1px solid var(--wd-border-default);
  border-radius: var(--wd-radius-md);
  padding: 12px 14px;
  text-decoration: none;
  cursor: pointer;
  transition: var(--wd-transition);
}

.wd-stage-card:hover {
  background: #ffffff;
  border-color: var(--wd-border-focus);
  transform: translateY(-2px);
  box-shadow: 0 4px 12px rgba(2, 132, 199, 0.08);
}

.wd-stage-inner {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.wd-stage-top {
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.wd-stage-step {
  font-size: 0.74rem;
  font-weight: 800;
  color: var(--wd-text-subtle);
  background: #ffffff;
  padding: 1px 6px;
  border-radius: 4px;
  border: 1px solid var(--wd-border-default);
}

.wd-stage-icon {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 26px;
  height: 26px;
  border-radius: 6px;
}

.wd-stage-icon svg {
  width: 14px;
  height: 14px;
}

.wd-stage-new .wd-stage-icon {
  background: var(--wd-stage-blue-bg);
  border: 1px solid var(--wd-stage-blue-bd);
  color: var(--wd-stage-blue);
}

.wd-stage-scheduled .wd-stage-icon {
  background: var(--wd-stage-amber-bg);
  border: 1px solid var(--wd-stage-amber-bd);
  color: var(--wd-stage-amber);
}

.wd-stage-referred .wd-stage-icon {
  background: var(--wd-stage-indigo-bg);
  border: 1px solid var(--wd-stage-indigo-bd);
  color: var(--wd-stage-indigo);
}

.wd-stage-passed .wd-stage-icon {
  background: var(--wd-stage-teal-bg);
  border: 1px solid var(--wd-stage-teal-bd);
  color: var(--wd-stage-teal);
}

.wd-stage-approved .wd-stage-icon {
  background: var(--wd-stage-emerald-bg);
  border: 1px solid var(--wd-stage-emerald-bd);
  color: var(--wd-stage-emerald);
}

.wd-stage-body {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.wd-stage-name {
  font-size: 0.84rem;
  font-weight: 800;
  color: var(--wd-text-primary);
  line-height: 1.2;
}

.wd-stage-caption {
  font-size: 0.72rem;
  color: var(--wd-text-muted);
}

.wd-stage-count {
  font-size: 1.55rem;
  font-weight: 900;
  color: var(--wd-text-primary);
  line-height: 1.1;
  padding-top: 4px;
  border-top: 1px solid var(--wd-border-light);
}

/* ==========================================================================
   مسار الحالات الاستثنائية (الراسبات بالتحريري)
   ========================================================================== */
.wd-secondary-bento-row {
  width: 100%;
  margin-top: 4px;
}

.wd-failed-bento-card {
  display: flex;
  align-items: center;
  background: var(--wd-stage-rose-bg);
  border: 1px solid var(--wd-stage-rose-bd);
  border-radius: var(--wd-radius-md);
  padding: 12px 18px;
  text-decoration: none;
  cursor: pointer;
  transition: var(--wd-transition);
}

.wd-failed-bento-card:hover {
  background: #ffe4e6;
  border-color: #fda4af;
  transform: translateY(-1px);
}

.wd-failed-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  width: 100%;
  gap: 14px;
}

.wd-failed-icon-box {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 34px;
  height: 34px;
  border-radius: 8px;
  background: #ffffff;
  border: 1px solid var(--wd-stage-rose-bd);
  color: var(--wd-stage-rose);
  flex-shrink: 0;
}

.wd-failed-icon-box svg {
  width: 18px;
  height: 18px;
}

.wd-failed-info {
  display: flex;
  flex-direction: column;
  gap: 2px;
  flex-grow: 1;
}

.wd-failed-title {
  font-size: 0.88rem;
  font-weight: 800;
  color: var(--wd-stage-rose);
}

.wd-failed-subtitle {
  font-size: 0.76rem;
  color: var(--wd-text-muted);
}

.wd-failed-count {
  font-size: 1.55rem;
  font-weight: 900;
  color: var(--wd-stage-rose);
  padding-left: 8px;
}

.wd-failed-arrow {
  font-size: 1rem;
  color: var(--wd-stage-rose);
  transition: transform 0.2s ease;
}

.wd-failed-bento-card:hover .wd-failed-arrow {
  transform: translateX(-4px);
}

/* ==========================================================================
   حالة التحميل الشبحية (Zero-CLS Loading State)
   ========================================================================== */
.is-loading {
  position: relative;
  min-height: 24px;
}

/* ==========================================================================
   مؤشرات التحميل الشبحية (Zero-CLS Skeletons)
   ========================================================================== */
.wd-skeleton {
  display: inline-block;
  width: 48px;
  height: 28px;
  border-radius: 6px;
  background: linear-gradient(90deg, #f1f5f9 25%, #e2e8f0 50%, #f1f5f9 75%);
  background-size: 200% 100%;
  animation: wdBentoShimmer 1.5s infinite;
  vertical-align: middle;
}

.wd-skeleton-pipe {
  width: 32px;
  height: 22px;
}

@keyframes wdBentoShimmer {
  0% { background-position: 200% 0; }
  100% { background-position: -200% 0; }
}

/* ==========================================================================
   التجاوب مع الشاشات (Responsive Grid Architecture)
   ========================================================================== */
@media (max-width: 1024px) {
  .wd-bento-hero-grid {
    grid-template-columns: 1fr 1fr;
  }
  
  .wd-bento-total {
    grid-column: span 2;
  }

  .wd-pipeline-bento-grid {
    grid-template-columns: repeat(3, 1fr);
  }
}

@media (max-width: 768px) {
  .wd-header-island {
    flex-direction: column;
    align-items: flex-start;
    gap: 12px;
    padding: 14px 16px;
  }

  .wd-header-actions {
    width: 100%;
    justify-content: flex-start;
    flex-wrap: wrap;
  }

  .wd-bento-hero-grid {
    grid-template-columns: 1fr;
  }

  .wd-bento-total {
    grid-column: auto;
  }

  .wd-pipeline-bento-grid {
    grid-template-columns: repeat(2, 1fr);
  }

  .wd-failed-inner {
    flex-wrap: wrap;
  }
}

@media (max-width: 480px) {
  .wd-pipeline-bento-grid {
    grid-template-columns: 1fr;
  }
  
  .wd-main-title {
    font-size: 1.15rem;
  }

  .wd-bento-hero-number {
    font-size: 1.9rem;
  }
}

script:
(function () {
  "use strict";

  /* ==========================================================================
   * لوحة قسم الامتحانات (الواعظات) - Modular Executive Engine (Frappe Custom Block)
   * Built according to clean architecture, SWR caching, Single Query Group By,
   * flexible status matching, and Page Visibility Polling.
   * ========================================================================== */

  var root = typeof root_element !== "undefined" ? root_element : document.querySelector(".exam-dash") || document;

  if (root.__femalexam_poller) {
    root.__femalexam_poller.stop();
  }

  installNumberTypography(root);

  function installNumberTypography(scope) {
    if (!scope || scope.__number_typography_installed) return;
    scope.__number_typography_installed = true;
    var digits = /[0-9٠-٩]+(?:[.,:/+\-%][0-9٠-٩]+)*/g, excluded = "SCRIPT,STYLE,TEXTAREA,OPTION";
    function render() {
      var walker = document.createTreeWalker(scope, NodeFilter.SHOW_TEXT, null, false), nodes = [], node;
      while ((node = walker.nextNode())) {
        var parent = node.parentElement;
        if (parent && !parent.closest(".app-number") && excluded.indexOf(parent.tagName) === -1 && digits.test(node.nodeValue)) {
          nodes.push(node);
        }
        digits.lastIndex = 0;
      }
      nodes.forEach(function (textNode) {
        var fragment = document.createDocumentFragment(), value = textNode.nodeValue, last = 0;
        value.replace(digits, function (match, offset) {
          fragment.appendChild(document.createTextNode(value.slice(last, offset)));
          var span = document.createElement("span");
          span.className = "app-number";
          span.textContent = match;
          fragment.appendChild(span);
          last = offset + match.length;
        });
        fragment.appendChild(document.createTextNode(value.slice(last)));
        textNode.parentNode.replaceChild(fragment, textNode);
        digits.lastIndex = 0;
      });
    }
    var queued = false;
    new MutationObserver(function () {
      if (!queued) {
        queued = true;
        requestAnimationFrame(function () {
          queued = false;
          render();
        });
      }
    }).observe(scope, { childList: true, characterData: true, subtree: true });
    render();
  }

  // 1. الإعدادات والثوابت (Configuration)
  var CONFIG = {
    TIMEOUT_MS: 9000,
    ANIMATION_DURATION_MS: 650,
    POLLING_INTERVAL_MS: 5 * 60 * 1000,
    CACHE_KEY: "femalwaed_exam_swr_cache_v2",
    STATUS_SYNONYMS: {
      scheduled: ["scheduled", "مجدول", "في انتظار الاختبار"],
      written: ["written in progress", "written", "تحريري جارٍ", "جارٍ التحريري"],
      oral: ["oral in progress", "oral", "شفوي جارٍ", "جارٍ الشفوي"],
      completed: ["completed", "مكتمل", "تمت الامتحانات", "تم الاختبار"]
    },
    ALLOWED_DOCTYPES: ["exam_group_date", "exam_form"]
  };

  // 2. إدارة الحالة (State Management)
  var STATE = {
    isRefreshing: false,
    hasCachedData: false,
    counts: {
      forms: 0,
      total: 0,
      scheduled: 0,
      written: 0,
      oral: 0,
      completed: 0,
      inProgress: 0
    }
  };

  // 3. مطابقة وتطبيع حالات الامتحانات (Status Engine)
  var StatusEngine = {
    normalize: function (str) {
      if (!str) return "";
      return String(str).trim().toLowerCase().replace(/[\s_-]+/g, " ");
    },
    matchCategory: function (rawStatus) {
      var normalized = StatusEngine.normalize(rawStatus);
      if (!normalized) return "scheduled";

      var categories = Object.keys(CONFIG.STATUS_SYNONYMS);
      for (var i = 0; i < categories.length; i++) {
        var cat = categories[i];
        var synonyms = CONFIG.STATUS_SYNONYMS[cat];
        for (var j = 0; j < synonyms.length; j++) {
          var syn = StatusEngine.normalize(synonyms[j]);
          if (normalized === syn || normalized.indexOf(syn) !== -1 || syn.indexOf(normalized) !== -1) {
            return cat;
          }
        }
      }
      return null;
    }
  };

  // 4. خدمة البيانات والاتصال بقاعدة بيانات Frappe (API Service)
  var APIService = {
    fetchAggregatedStats: function () {
      if (!window.frappe || !frappe.call) {
        return APIService.fetchFallbackIndividualCounts();
      }

      return frappe.call({
        method: "taq_it.api.get_exam_dashboard_stats",
        timeout: 3000,
        error: function (r) {
          if (r) r.exc = null;
        }
      }).then(function (r) {
        if (r && r.message && r.message.success) {
          var res = r.message;
          return {
            forms: res.forms || 0,
            total: res.total || 0,
            scheduled: res.scheduled || 0,
            written: res.written || 0,
            oral: res.oral || 0,
            completed: res.completed || 0,
            inProgress: res.inProgress || 0
          };
        }
        throw new Error("Fallback needed");
      }).catch(function () {
        var pForms = frappe.call({
          method: "frappe.desk.reportview.get",
          args: { doctype: "exam_form", fields: ["count(name) as count"], limit: 1 }
        }).catch(function () { return { message: { values: [[0]] } }; });

        var pGroups = frappe.call({
          method: "frappe.desk.reportview.get",
          args: {
            doctype: "exam_group_date",
            fields: ["exam_status", "count(name) as count"],
            group_by: "exam_status",
            limit: 100
          }
        });

        return Promise.all([pForms, pGroups])
          .then(function (results) {
            var formsMsg = (results[0] && results[0].message) || {};
            var groupsMsg = (results[1] && results[1].message) || {};

            var parsed = {
              forms: 0,
              total: 0,
              scheduled: 0,
              written: 0,
              oral: 0,
              completed: 0,
              inProgress: 0
            };

            if (formsMsg.values && formsMsg.values[0]) {
              parsed.forms = parseInt(formsMsg.values[0][0], 10) || 0;
            }

            var values = groupsMsg.values || [];
            values.forEach(function (row) {
              var rawStatus = row[0] || "Scheduled";
              var count = parseInt(row[1], 10) || 0;
              parsed.total += count;

              var cat = StatusEngine.matchCategory(rawStatus);
              if (cat && parsed[cat] !== undefined) {
                parsed[cat] += count;
              }
            });

            parsed.inProgress = parsed.written + parsed.oral;
            return parsed;
          })
          .catch(function () {
            return APIService.fetchFallbackIndividualCounts();
          });
      });
    },

    fetchCountWithTimeout: function (doctype, filters) {
      if (!window.frappe || !frappe.db || !frappe.db.count) {
        return Promise.resolve(0);
      }
      return new Promise(function (resolve) {
        var queryFilters = filters ? Object.assign({}, filters) : {};
        frappe.db.count(doctype, Object.keys(queryFilters).length > 0 ? { filters: queryFilters } : {})
          .then(function (count) { resolve(typeof count === "number" ? count : 0); })
          .catch(function () { resolve(0); });
        setTimeout(function () { resolve(0); }, CONFIG.TIMEOUT_MS);
      });
    },

    fetchFallbackIndividualCounts: function () {
      return Promise.all([
        APIService.fetchCountWithTimeout("exam_form", null),
        APIService.fetchCountWithTimeout("exam_group_date", null),
        APIService.fetchCountWithTimeout("exam_group_date", { exam_status: "Scheduled" }),
        APIService.fetchCountWithTimeout("exam_group_date", { exam_status: "Written In Progress" }),
        APIService.fetchCountWithTimeout("exam_group_date", { exam_status: "Oral In Progress" }),
        APIService.fetchCountWithTimeout("exam_group_date", { exam_status: "Completed" })
      ]).then(function (results) {
        return {
          forms: results[0],
          total: results[1],
          scheduled: results[2],
          written: results[3],
          oral: results[4],
          completed: results[5],
          inProgress: results[3] + results[4]
        };
      });
    },

    fetchNextScheduledExam: function () {
      if (!window.frappe || !frappe.db || !frappe.db.get_list) {
        return Promise.resolve(null);
      }
      return new Promise(function (resolve) {
        if (frappe.model && frappe.model.with_doctype) {
          frappe.model.with_doctype("exam_group_date", function () {
            var meta = frappe.get_meta ? frappe.get_meta("exam_group_date") : null;
            var dateField = "date";
            if (meta && meta.fields) {
              var found = meta.fields.find(function (f) { return f.fieldtype === "Date"; });
              if (found) dateField = found.fieldname;
            }

            frappe.db.get_list("exam_group_date", {
              filters: { exam_status: "Scheduled" },
              fields: ["name", dateField],
              order_by: dateField + " asc",
              limit: 1
            }).then(function (records) {
              if (records && records.length && records[0][dateField]) {
                resolve({ dateStr: records[0][dateField] });
              } else {
                resolve(null);
              }
            }).catch(function () { resolve(null); });
          });
        } else {
          resolve(null);
        }
      });
    }
  };

  // 5. إدارة التخزين المؤقت اللحظي (SWR Cache)
  var CacheManager = {
    loadCachedState: function () {
      try {
        var raw = sessionStorage.getItem(CONFIG.CACHE_KEY);
        if (!raw) return false;
        var data = JSON.parse(raw);
        if (data && data.counts && typeof data.counts.total === "number") {
          STATE.counts = Object.assign({}, data.counts);
          STATE.hasCachedData = true;
          return true;
        }
      } catch (e) {
        console.warn("[Femalwaed Exam Dashboard] Cache read skipped:", e);
      }
      return false;
    },
    saveState: function () {
      try {
        sessionStorage.setItem(CONFIG.CACHE_KEY, JSON.stringify({
          counts: STATE.counts,
          timestamp: Date.now()
        }));
      } catch (e) {}
    }
  };

  // 6. منطق العرض وتحديث الواجهة (UI Presenter)
  var UIPresenter = {
    formatDigits: function (val) {
      if (val === null || val === undefined) return "0";
      return String(val).replace(/[٠-٩]/g, function (d) {
        return d.charCodeAt(0) - 1632;
      });
    },

    animateNumber: function (el, targetValue, isInstant) {
      if (!el) return;
      el.classList.remove("is-loading");
      el.setAttribute("dir", "ltr");
      el.setAttribute("lang", "en");

      if (typeof targetValue !== "number" || isNaN(targetValue)) {
        el.textContent = "0";
        return;
      }

      if (isInstant) {
        el.textContent = UIPresenter.formatDigits(targetValue);
        return;
      }

      var currentNum = parseInt(el.textContent.replace(/[^0-9]/g, ""), 10) || 0;
      var startValue = currentNum;
      var startTime = null;
      var animDuration = CONFIG.ANIMATION_DURATION_MS;

      function step(timestamp) {
        if (!startTime) startTime = timestamp;
        var progress = Math.min((timestamp - startTime) / animDuration, 1);
        var easeProgress = 1 - Math.pow(1 - progress, 3);
        var current = Math.round(startValue + (targetValue - startValue) * easeProgress);

        el.textContent = UIPresenter.formatDigits(current);

        if (progress < 1) {
          window.requestAnimationFrame(step);
        } else {
          el.textContent = UIPresenter.formatDigits(targetValue);
        }
      }

      window.requestAnimationFrame(step);
    },

    setCount: function (selector, value, isInstant) {
      var targetEl = root.querySelector(selector);
      if (!targetEl) return;
      var numEl = targetEl.querySelector(".tq-count-value") || targetEl;
      UIPresenter.animateNumber(numEl, typeof value === "number" ? value : 0, isInstant);
    },

    setText: function (selector, text) {
      var targetEl = root.querySelector(selector);
      if (!targetEl) return;
      var numEl = targetEl.querySelector(".tq-count-value") || targetEl;
      numEl.classList.remove("is-loading");
      numEl.setAttribute("dir", "ltr");
      numEl.setAttribute("lang", "en");
      numEl.textContent = UIPresenter.formatDigits(text);
    },

    setError: function (selector) {
      var targetEl = root.querySelector(selector);
      if (!targetEl) return;
      var numEl = targetEl.querySelector(".tq-count-value") || targetEl;
      numEl.classList.remove("is-loading");
      numEl.textContent = "—";
    },

    updateAlertBanner: function (nextExamData) {
      var box = root.querySelector("#twd-exam-alerts-box");
      var alertNext = root.querySelector("#alert-next-exam");
      if (!box || !alertNext) return;

      var hasVisibleAlert = false;
      if (nextExamData && nextExamData.dateStr) {
        var examDate = new Date(nextExamData.dateStr);
        if (!isNaN(examDate.getTime())) {
          var today = new Date();
          today.setHours(0, 0, 0, 0);
          examDate.setHours(0, 0, 0, 0);

          var daysDiff = Math.ceil((examDate.getTime() - today.getTime()) / (1000 * 60 * 60 * 24));
          if (daysDiff >= 0) {
            var monthsArr = ["يناير", "فبراير", "مارس", "أبريل", "مايو", "يونيو", "يوليو", "أغسطس", "سبتمبر", "أكتوبر", "نوفمبر", "ديسمبر"];
            var dateEl = alertNext.querySelector(".twd-alert__date");
            var remEl = alertNext.querySelector(".twd-alert__remaining");
            
            if (dateEl) {
              dateEl.innerHTML = '<span class="num">' + UIPresenter.formatDigits(examDate.getDate()) + '</span> ' + monthsArr[examDate.getMonth()] + ' <span class="num">' + UIPresenter.formatDigits(examDate.getFullYear()) + '</span>';
            }
            if (remEl) {
              var remText = "";
              if (daysDiff === 0) remText = "اليوم";
              else if (daysDiff === 1) remText = "غداً";
              else if (daysDiff === 2) remText = "بعد غد";
              else remText = 'متبقي <span class="num">' + UIPresenter.formatDigits(daysDiff) + '</span> يوم';
              remEl.innerHTML = remText;
            }

            alertNext.style.display = "flex";
            hasVisibleAlert = true;
          } else {
            alertNext.style.display = "none";
          }
        } else {
          alertNext.style.display = "none";
        }
      }

      box.style.display = hasVisibleAlert ? "flex" : "none";
    },

    calculateCompletionRate: function () {
      if (STATE.counts.total > 0) {
        return Math.round((STATE.counts.completed / STATE.counts.total) * 100);
      }
      return null;
    },

    renderAll: function (isInstant) {
      UIPresenter.setCount("#stat-exam-forms", STATE.counts.forms, isInstant);
      UIPresenter.setCount("#stat-exam-total", STATE.counts.total, isInstant);
      UIPresenter.setCount("#stat-exam-scheduled", STATE.counts.scheduled, isInstant);
      UIPresenter.setCount("#stat-exam-written", STATE.counts.written, isInstant);
      UIPresenter.setCount("#stat-exam-oral", STATE.counts.oral, isInstant);
      UIPresenter.setCount("#stat-exam-completed", STATE.counts.completed, isInstant);
      UIPresenter.setCount("#stat-exam-inprogress", STATE.counts.inProgress, isInstant);

      var rate = UIPresenter.calculateCompletionRate();
      UIPresenter.setText("#stat-exam-rate", rate === null ? "—" : UIPresenter.formatDigits(rate) + "%");
      UIPresenter.normalizeAllDigits();
    },

    normalizeAllDigits: function () {
      if (!root) return;
      var walker = document.createTreeWalker(root, NodeFilter.SHOW_TEXT, null, false);
      var node;
      while ((node = walker.nextNode())) {
        if (/[٠-٩]/.test(node.nodeValue)) {
          node.nodeValue = node.nodeValue.replace(/[٠-٩]/g, function (d) {
            return String(d.charCodeAt(0) - 1632);
          });
        }
      }
    },

    setRefreshSpinning: function (isSpinning) {
      var icon = root.querySelector(".ex-icon-refresh");
      if (icon) {
        if (isSpinning) icon.classList.add("is-spinning");
        else icon.classList.remove("is-spinning");
      }
    }
  };

  // 7. موجه التنقل (Router)
  var Router = {
    navigate: function (target) {
      var doctype = target.getAttribute("data-doctype");
      if (!doctype || CONFIG.ALLOWED_DOCTYPES.indexOf(doctype) === -1) return;

      if (target.getAttribute("data-action") === "new") {
        if (window.frappe && frappe.new_doc) {
          frappe.new_doc(doctype);
        } else {
          window.location.href = "/app/" + encodeURIComponent(doctype.toLowerCase().replace(/ /g, "-")) + "/new";
        }
        return;
      }

      var filters = {};
      try {
        var rawFilters = target.getAttribute("data-filters");
        if (rawFilters) filters = JSON.parse(rawFilters);
      } catch (err) {
        filters = {};
      }

      if (window.frappe && frappe.set_route) {
        frappe.route_options = filters;
        frappe.set_route("list", doctype, filters);
      } else {
        var query = Object.keys(filters).length > 0 ? "?" + new URLSearchParams(filters).toString() : "";
        window.location.href = "/app/" + encodeURIComponent(doctype.toLowerCase().replace(/ /g, "-")) + query;
      }
    }
  };

  // 8. المتحكم الدوري الذكي (Smart Poller)
  var Poller = {
    timer: null,
    start: function () {
      Poller.stop();
      Poller.timer = setInterval(function () {
        if (document.visibilityState === "visible" && !STATE.isRefreshing) {
          loadDashboardData(false);
        }
      }, CONFIG.POLLING_INTERVAL_MS);
    },
    stop: function () {
      if (Poller.timer) {
        clearInterval(Poller.timer);
        Poller.timer = null;
      }
    }
  };
  root.__femalexam_poller = Poller;

  // 9. تهيئة الأحداث
  function initEvents() {
    if (root.__exam_events_bound) return;
    root.__exam_events_bound = true;

    root.addEventListener("click", function (e) {
      var refreshBtn = e.target.closest("#btn-exam-refresh");
      if (refreshBtn) {
        e.preventDefault();
        loadDashboardData(true);
        return;
      }

      var navTarget = e.target.closest("[data-doctype]");
      if (navTarget) {
        e.preventDefault();
        Router.navigate(navTarget);
      }
    });

    root.addEventListener("keydown", function (e) {
      if (e.key === "Enter" || e.key === " ") {
        var target = e.target.closest("[data-doctype], #btn-exam-refresh");
        if (target) {
          e.preventDefault();
          target.click();
        }
      }
    });

    document.addEventListener("visibilitychange", function () {
      if (document.visibilityState === "visible") {
        loadDashboardData(false);
        Poller.start();
      } else {
        Poller.stop();
      }
    });
  }

  // 10. دورة تحميل البيانات
  function loadDashboardData(isManualRefresh) {
    if (STATE.isRefreshing) return;
    STATE.isRefreshing = true;

    if (isManualRefresh) {
      UIPresenter.setRefreshSpinning(true);
    }

    var statsPromise = APIService.fetchAggregatedStats();
    var nextExamPromise = APIService.fetchNextScheduledExam();

    Promise.all([statsPromise, nextExamPromise])
      .then(function (results) {
        STATE.counts = results[0];
        CacheManager.saveState();
        UIPresenter.renderAll(false);
        UIPresenter.updateAlertBanner(results[1]);
      })
      .catch(function (err) {
        console.error("[Femalwaed Exam Dashboard] Load error:", err);
        if (!STATE.hasCachedData) {
          [
            "#stat-exam-forms",
            "#stat-exam-total",
            "#stat-exam-scheduled",
            "#stat-exam-written",
            "#stat-exam-oral",
            "#stat-exam-completed",
            "#stat-exam-inprogress",
            "#stat-exam-rate"
          ].forEach(UIPresenter.setError);
        }
      })
      .finally(function () {
        STATE.isRefreshing = false;
        if (isManualRefresh) {
          setTimeout(function () {
            UIPresenter.setRefreshSpinning(false);
          }, 400);
        }
      });
  }

  // 11. الإقلاع الفوري
  initEvents();

  var hasCache = CacheManager.loadCachedState();
  if (hasCache) {
    UIPresenter.renderAll(true);
  }

  loadDashboardData(false);
  Poller.start();
})();

