/* ==========================================================================
   نظام الخطوط الموحد: GE SS Two للنصوص و Poppins حصرياً للأرقام القياسية (1234)
   ========================================================================== */
@import url('https://fonts.googleapis.com/css2?family=Poppins:wght@300;400;500;600;700;800;900&display=swap');

.exam-dash {
  --ex-font: 'GE SS Two';

  /* Neutrals (Light Mode) */
  --ex-bg-canvas:      transparent;
  --ex-bg-surface:     #ffffff;
  --ex-bg-subtle:      #f8fafc;
  --ex-bg-card-inner:  #ffffff;
  --ex-bg-island:      #f8fafc;

  --ex-text-primary:   #0f172a;
  --ex-text-secondary: #334155;
  --ex-text-muted:     #64748b;
  --ex-text-subtle:    #94a3b8;

  --ex-border-light:   #f1f5f9;
  --ex-border-default: #e2e8f0;
  --ex-border-focus:   #38bdf8;

  /* Brand Colors (Light Oceanic Blue) */
  --ex-sky-600:        #0284c7;
  --ex-sky-500:        #0ea5e9;
  --ex-sky-400:        #38bdf8;
  --ex-sky-200:        #bae6fd;
  --ex-sky-100:        #e0f2fe;
  --ex-sky-50:         #f0f9ff;

  /* Semantic Stages */
  --ex-stage-blue:     #0284c7;
  --ex-stage-blue-bg:  #f0f9ff;
  --ex-stage-blue-bd:  #bae6fd;

  --ex-stage-amber:    #d97706;
  --ex-stage-amber-bg: #fffbeb;
  --ex-stage-amber-bd: #fde68a;

  --ex-stage-indigo:   #4f46e5;
  --ex-stage-indigo-bg:#eef2ff;
  --ex-stage-indigo-bd:#c7d2fe;

  --ex-stage-teal:     #0d9488;
  --ex-stage-teal-bg:  #f0fdfa;
  --ex-stage-teal-bd:  #99f6e4;

  --ex-stage-emerald:  #059669;
  --ex-stage-emerald-bg:#ecfdf5;
  --ex-stage-emerald-bd:#a7f3d0;

  --ex-stage-rose:     #e11d48;
  --ex-stage-rose-bg:  #fff1f2;
  --ex-stage-rose-bd:  #fecdd3;

  /* Radii */
  --ex-radius-sm:      6px;
  --ex-radius-md:      10px;
  --ex-radius-lg:      16px;
  --ex-radius-xl:      22px;
  --ex-radius-pill:    9999px;

  /* Elevation Shadows */
  --ex-shadow-sm:      0 1px 2px rgba(15, 23, 42, 0.04);
  --ex-shadow-card:    0 2px 8px -2px rgba(15, 23, 42, 0.05), 0 1px 3px rgba(15, 23, 42, 0.03);
  --ex-shadow-bento:   0 10px 25px -5px rgba(15, 23, 42, 0.04), 0 8px 10px -6px rgba(15, 23, 42, 0.02);
  --ex-shadow-hover:   0 16px 32px -4px rgba(2, 132, 199, 0.16);

  /* Animation */
  --ex-transition:     all 0.24s cubic-bezier(0.16, 1, 0.3, 1);
  --ex-ease-spring:    cubic-bezier(0.34, 1.56, 0.64, 1);

  font-family: var(--ex-font) !important;
  color: var(--ex-text-secondary);
  background: var(--ex-bg-canvas);
  direction: rtl;
  text-align: right;
  line-height: 1.5;
  box-sizing: border-box;
  -webkit-font-smoothing: antialiased;
}

/* ==========================================================================
   دعم الوضع الليلي (Dark Mode Support)
   ========================================================================== */
[data-theme="dark"] .exam-dash,
body[data-theme="dark"] .exam-dash,
.theme-dark .exam-dash {
  --ex-bg-surface:     #111827;
  --ex-bg-subtle:      #1f2937;
  --ex-bg-card-inner:  #162032;
  --ex-bg-island:      #1f2937;

  --ex-text-primary:   #f8fafc;
  --ex-text-secondary: #cbd5e1;
  --ex-text-muted:     #94a3b8;
  --ex-text-subtle:    #64748b;

  --ex-border-light:   #1f2937;
  --ex-border-default: #334155;
  --ex-border-focus:   #38bdf8;

  --ex-sky-50:         #0c4a6e;
  --ex-sky-100:        #075985;
  --ex-sky-200:        #0284c7;

  --ex-stage-blue-bg:  #0c4a6e;
  --ex-stage-blue-bd:  #0284c7;

  --ex-stage-amber-bg: #451a03;
  --ex-stage-amber-bd: #92400e;

  --ex-stage-indigo-bg:#1e1b4b;
  --ex-stage-indigo-bd:#3730a3;

  --ex-stage-teal-bg:  #042f2e;
  --ex-stage-teal-bd:  #115e59;

  --ex-stage-emerald-bg:#022c22;
  --ex-stage-emerald-bd:#065f46;

  --ex-stage-rose-bg:  #4c0519;
  --ex-stage-rose-bd:  #881337;

  --ex-shadow-bento:   0 10px 25px -5px rgba(0, 0, 0, 0.4);
  --ex-shadow-hover:   0 16px 32px -4px rgba(2, 132, 199, 0.25);
}

/* 1. تطبيق خط GE SS Two لجميع النصوص والعناصر بالكامل */
.exam-dash,
.exam-dash *,
.exam-dash *::before,
.exam-dash *::after,
.exam-dash h1,
.exam-dash h2,
.exam-dash h3,
.exam-dash h4,
.exam-dash p,
.exam-dash span,
.exam-dash a,
.exam-dash div,
.exam-dash strong,
.exam-dash button,
.exam-dash label,
.exam-dash input {
  font-family: 'GE SS Two' !important;
  box-sizing: border-box;
}

/* 2. استثناء الأرقام فقط: خط Poppins الصريح والأرقام القياسية 1234 دائماً */
.tq-count-value,
.tq-count-value *,
.ex-bento-hero-number,
.ex-bento-hero-number *,
.ex-stage-count,
.ex-stage-count *,
.twd-alert-count,
.ex-stage-step,
.ex-kpi-val,
.ex-pipe-count,
.ex-stat-num,
.num,
.number,
.digits,
.stat-number,
[data-num] {
  font-family: 'Poppins', sans-serif !important;
  font-feature-settings: "locl" 0, "numr" 0, "lnum" 1, "tnum" 1 !important;
  font-variant-numeric: lining-nums tabular-nums !important;
  direction: ltr !important;
  unicode-bidi: isolate !important;
  display: inline-block;
}

/* Poppins is limited to digit-only spans created by the typography runtime. */
.exam-dash .app-number,
.exam-dash input[type="number"],
.exam-dash input[inputmode="numeric"],
.exam-dash input[inputmode="decimal"],
.exam-dash input[type="tel"] { font-family: 'Poppins', sans-serif !important; font-feature-settings: "locl" 0, "lnum" 1, "tnum" 1 !important; font-variant-numeric: lining-nums tabular-nums !important; direction: ltr; unicode-bidi: isolate; }

/* إزالة أي خط سفلي عند التحويم والتفاعل */
.exam-dash a,
.exam-dash a:hover,
.exam-dash a:focus,
.exam-dash a:active,
.exam-dash a:visited,
.exam-dash a *,
.exam-dash a:hover *,
.exam-dash button,
.exam-dash button:hover {
  text-decoration: none !important;
  text-decoration-line: none !important;
}

/* Focus Visible Rings for Keyboard Accessibility */
.exam-dash a:focus-visible,
.exam-dash button:focus-visible {
  outline: 2px solid var(--ex-sky-400) !important;
  outline-offset: 3px !important;
  box-shadow: 0 0 0 4px rgba(56, 189, 248, 0.25) !important;
  text-decoration: none !important;
}

/* ==========================================================================
   الغلاف الرئيسي (Master Bento Shell)
   ========================================================================== */
.ex-shell {
  display: flex;
  flex-direction: column;
  gap: 24px;
  background: var(--ex-bg-surface);
  border: 1px solid var(--ex-border-default);
  border-radius: var(--ex-radius-xl);
  padding: 28px;
  box-shadow: var(--ex-shadow-bento);
  position: relative;
}

/* ==========================================================================
   شريط التنبيهات الذكية (Smart Alert Pills)
   ========================================================================== */
.ex-alert-bar {
  margin-bottom: 16px;
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.ex-alert-pill {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  background: linear-gradient(135deg, var(--ex-sky-50) 0%, var(--ex-bg-surface) 100%);
  border: 1px solid var(--ex-sky-200);
  border-radius: var(--ex-radius-lg);
  padding: 12px 18px;
  box-shadow: var(--ex-shadow-sm);
  transition: var(--ex-transition);
  text-decoration: none;
  cursor: pointer;
}

.ex-alert-date {
  background: linear-gradient(135deg, var(--ex-stage-amber-bg) 0%, var(--ex-bg-surface) 100%);
  border-color: var(--ex-stage-amber-bd);
}

.ex-alert-content {
  display: flex;
  align-items: center;
  gap: 12px;
  flex-wrap: wrap;
}

.ex-pulse-dot {
  width: 10px;
  height: 10px;
  border-radius: 50%;
  background: #ef4444;
  box-shadow: 0 0 0 0 rgba(239, 68, 68, 0.7);
  animation: exPulse 1.8s infinite;
  flex-shrink: 0;
}

@keyframes exPulse {
  0% { transform: scale(0.95); box-shadow: 0 0 0 0 rgba(239, 68, 68, 0.7); }
  70% { transform: scale(1); box-shadow: 0 0 0 8px rgba(239, 68, 68, 0); }
  100% { transform: scale(0.95); box-shadow: 0 0 0 0 rgba(239, 68, 68, 0); }
}

.ex-alert-icon-wrap {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 22px;
  height: 22px;
  color: var(--ex-stage-amber);
}

.ex-alert-icon-wrap svg {
  width: 18px;
  height: 18px;
}

.ex-alert-tag {
  font-size: 0.74rem;
  font-weight: 800;
  background: var(--ex-sky-600);
  color: #ffffff;
  padding: 2px 9px;
  border-radius: var(--ex-radius-pill);
}

.ex-tag-amber {
  background: var(--ex-stage-amber);
}

.ex-alert-msg {
  font-size: 0.92rem;
  font-weight: 500;
  color: var(--ex-text-primary);
}

.twd-alert-count {
  font-weight: 900;
  color: var(--ex-sky-600);
}

.ex-alert-cta {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  font-size: 0.85rem;
  font-weight: 700;
  color: var(--ex-sky-600);
  background: var(--ex-bg-surface);
  padding: 5px 6px 5px 14px;
  border-radius: var(--ex-radius-pill);
  border: 1px solid var(--ex-sky-200);
  white-space: nowrap;
  transition: var(--ex-transition);
}

.ex-cta-bubble {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 24px;
  height: 24px;
  border-radius: 50%;
  background: var(--ex-sky-50);
  color: var(--ex-sky-600);
  transition: var(--ex-transition);
}

.ex-cta-bubble svg {
  width: 14px;
  height: 14px;
}

.ex-alert-pill:hover .ex-alert-cta {
  background: var(--ex-sky-600);
  color: #ffffff;
  border-color: var(--ex-sky-600);
}

.ex-alert-pill:hover .ex-cta-bubble {
  background: rgba(255, 255, 255, 0.25);
  color: #ffffff;
  transform: translateX(-2px);
}

/* ==========================================================================
   ترويسة العمليات التنفيذية (Executive Island Header)
   ========================================================================== */
.ex-header-island {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 20px;
  padding-bottom: 22px;
  border-bottom: 1px solid var(--ex-border-light);
  flex-wrap: wrap;
}

.ex-header-brand {
  display: flex;
  align-items: center;
  gap: 16px;
}

.ex-avatar-core {
  width: 52px;
  height: 52px;
  border-radius: var(--ex-radius-lg);
  background: linear-gradient(135deg, var(--ex-sky-50) 0%, var(--ex-sky-100) 100%);
  border: 1px solid var(--ex-sky-200);
  color: var(--ex-sky-600);
  display: flex;
  align-items: center;
  justify-content: center;
  box-shadow: 0 4px 12px rgba(2, 132, 199, 0.12);
  flex-shrink: 0;
}

.ex-avatar-core svg {
  width: 28px;
  height: 28px;
}

.ex-brand-text {
  display: flex;
  flex-direction: column;
}

.ex-status-badge-row {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-bottom: 4px;
}

.ex-badge-brand {
  font-size: 0.76rem;
  font-weight: 800;
  color: var(--ex-sky-600);
  letter-spacing: 0.01em;
}

.ex-badge-live {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  font-size: 0.7rem;
  font-weight: 700;
  background: var(--ex-stage-emerald-bg);
  color: var(--ex-stage-emerald);
  padding: 2px 8px;
  border-radius: var(--ex-radius-pill);
  border: 1px solid var(--ex-stage-emerald-bd);
}

.ex-live-beacon {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: var(--ex-stage-emerald);
}

.ex-main-title {
  font-size: 1.4rem;
  font-weight: 900;
  color: var(--ex-text-primary);
  margin: 0 0 2px 0;
  line-height: 1.25;
}

.ex-main-subtitle {
  font-size: 0.85rem;
  color: var(--ex-text-muted);
  margin: 0;
  font-weight: 500;
}

/* هندسة أزرار الجزيرة (Rectangular Subtle Radius) */
.ex-header-actions {
  display: flex;
  align-items: center;
  gap: 10px;
  flex-wrap: wrap;
}

.ex-btn-island {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  font-size: 0.88rem;
  font-weight: 700;
  padding: 8px 14px;
  border-radius: 8px;
  text-decoration: none !important;
  cursor: pointer;
  transition: var(--ex-transition);
  white-space: nowrap;
  border: none;
}

.ex-btn-icon-bubble {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 24px;
  height: 24px;
  border-radius: 6px;
  transition: var(--ex-transition);
  flex-shrink: 0;
}

.ex-btn-icon-bubble svg {
  width: 15px;
  height: 15px;
}

/* زر التحديث الحي */
.ex-btn-ghost {
  background: var(--ex-bg-subtle);
  color: var(--ex-text-secondary) !important;
  border: 1px solid var(--ex-border-default);
  box-shadow: var(--ex-shadow-sm);
  padding: 8px 14px 8px 8px;
}

.ex-btn-ghost .ex-btn-icon-bubble {
  background: var(--ex-bg-surface);
  color: var(--ex-text-secondary);
}

.ex-btn-ghost:hover {
  background: var(--ex-sky-50);
  border-color: var(--ex-sky-200);
  color: var(--ex-sky-600) !important;
  transform: translateY(-2px);
}

.ex-btn-ghost:hover .ex-btn-icon-bubble {
  color: var(--ex-sky-600);
  background: #ffffff;
}

.ex-icon-refresh.is-spinning {
  animation: exSpin 0.75s linear infinite;
}

@keyframes exSpin {
  100% { transform: rotate(-360deg); }
}

/* زر إنشاء امتحان */
.ex-btn-primary {
  background: linear-gradient(135deg, var(--ex-sky-500) 0%, var(--ex-sky-600) 100%);
  color: #ffffff !important;
  box-shadow: 0 4px 14px rgba(2, 132, 199, 0.28);
  border: 1px solid transparent;
}

.ex-btn-primary .ex-btn-icon-bubble {
  background: rgba(255, 255, 255, 0.22);
  color: #ffffff;
}

.ex-btn-primary:hover {
  transform: translateY(-2px);
  box-shadow: 0 8px 20px rgba(2, 132, 199, 0.38);
  color: #ffffff !important;
}

.ex-btn-primary:hover .ex-btn-icon-bubble {
  transform: scale(1.1);
  background: rgba(255, 255, 255, 0.35);
}

/* زر نموذج امتحان */
.ex-btn-secondary {
  background: var(--ex-bg-surface);
  color: var(--ex-text-secondary) !important;
  border: 1px solid var(--ex-border-default);
  box-shadow: var(--ex-shadow-sm);
}

.ex-btn-secondary .ex-btn-icon-bubble {
  background: var(--ex-bg-subtle);
  color: var(--ex-sky-600);
}

.ex-btn-secondary:hover {
  background: var(--ex-bg-subtle);
  border-color: var(--ex-sky-200);
  color: var(--ex-sky-600) !important;
  transform: translateY(-2px);
}

/* ==========================================================================
   شبكة بينتو للمؤشرات الاستراتيجية (Executive Minimal Bento Row)
   ========================================================================== */
.ex-bento-hero-grid {
  display: grid;
  grid-template-columns: 1.35fr 1fr 1fr;
  gap: 14px;
}

.ex-bento-card {
  position: relative;
  background: var(--ex-bg-surface);
  border: 1px solid var(--ex-border-default);
  border-radius: 14px;
  padding: 0;
  text-decoration: none !important;
  color: inherit;
  box-shadow: 0 1px 3px 0 rgba(15, 23, 42, 0.03), 0 1px 2px -1px rgba(15, 23, 42, 0.02);
  transition: all 0.22s cubic-bezier(0.16, 1, 0.3, 1);
  display: flex;
  flex-direction: column;
  overflow: hidden;
}

.ex-bento-inner {
  background: transparent;
  border: none;
  border-radius: 0;
  padding: 20px 22px;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  height: 100%;
  box-shadow: none;
  transition: var(--ex-transition);
}

.ex-bento-card:hover {
  transform: translateY(-2px);
  border-color: var(--ex-sky-400);
  box-shadow: 0 10px 24px -4px rgba(2, 132, 199, 0.10), 0 2px 6px -1px rgba(15, 23, 42, 0.03);
}

.ex-bento-top {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 12px;
}

.ex-bento-icon-box {
  width: 36px;
  height: 36px;
  border-radius: 10px;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  transition: transform 0.2s ease;
}

.ex-bento-icon-box svg {
  width: 18px;
  height: 18px;
}

.ex-bento-card:hover .ex-bento-icon-box {
  transform: scale(1.05);
}

.ex-icon-sky {
  background: #f0f9ff;
  color: #0284c7;
  border: none;
}

.ex-icon-teal {
  background: #f0fdfa;
  color: #0d9488;
  border: none;
}

.ex-icon-gold {
  background: #fffbeb;
  color: #d97706;
  border: none;
}

.ex-bento-tag {
  font-size: 0.72rem;
  font-weight: 700;
  padding: 2px 8px;
  border-radius: 6px;
  background: var(--ex-bg-subtle);
  color: var(--ex-text-muted);
  border: 1px solid var(--ex-border-light);
}

.ex-tag-teal {
  background: #f0fdfa;
  color: #0d9488;
  border-color: #ccfbf1;
}

.ex-tag-gold {
  background: #fffbeb;
  color: #d97706;
  border-color: #fef3c7;
}

.ex-bento-center {
  margin: 4px 0 12px 0;
}

.ex-bento-hero-number {
  font-size: 2.1rem;
  font-weight: 900;
  color: var(--ex-text-primary);
  line-height: 1.1;
  letter-spacing: -0.02em;
  margin-bottom: 3px;
}

.ex-bento-label {
  font-size: 0.84rem;
  color: var(--ex-text-secondary);
  font-weight: 600;
}

.ex-bento-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding-top: 10px;
  border-top: 1px solid var(--ex-border-light);
  font-size: 0.78rem;
  color: var(--ex-text-muted);
  font-weight: 600;
}

.ex-footer-action-text {
  color: var(--ex-sky-600);
}

.ex-footer-arrow {
  font-size: 0.95rem;
  transition: transform 0.2s ease;
}

.ex-bento-card:hover .ex-footer-arrow {
  color: var(--ex-sky-600);
  transform: translateX(-3px);
}

.ex-footer-hint {
  font-size: 0.76rem;
  color: var(--ex-text-muted);
}

/* ==========================================================================
   مسار دورة حياة الامتحانات (Lifecycle Pipeline Minimal Grid)
   ========================================================================== */
.ex-pipeline-bento-section {
  display: flex;
  flex-direction: column;
  gap: 14px;
  background: var(--ex-bg-surface);
  border: 1px solid var(--ex-border-default);
  border-radius: 14px;
  padding: 18px 20px;
}

.ex-section-header-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.ex-section-tag-wrap {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-bottom: 2px;
}

.ex-section-badge {
  font-size: 0.72rem;
  font-weight: 800;
  background: #f0f9ff;
  color: #0284c7;
  padding: 2px 8px;
  border-radius: 6px;
  border: 1px solid #bae6fd;
}

.ex-section-heading {
  font-size: 1.05rem;
  font-weight: 900;
  color: var(--ex-text-primary);
  margin: 0;
}

.ex-section-desc {
  font-size: 0.8rem;
  color: var(--ex-text-muted);
  margin: 0;
}

/* شبكة المراحل الخمس */
.ex-pipeline-bento-grid {
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  gap: 10px;
}

.ex-stage-card {
  position: relative;
  background: #ffffff;
  border: 1px solid var(--ex-border-default);
  border-radius: 12px;
  padding: 0;
  text-decoration: none !important;
  color: inherit;
  box-shadow: 0 1px 2px 0 rgba(15, 23, 42, 0.02);
  transition: all 0.2s cubic-bezier(0.16, 1, 0.3, 1);
  overflow: hidden;
}

.ex-stage-inner {
  background: transparent;
  border: none;
  border-radius: 0;
  padding: 14px;
  display: flex;
  flex-direction: column;
  gap: 8px;
  height: 100%;
  box-sizing: border-box;
  box-shadow: none;
  transition: var(--ex-transition);
}

.ex-stage-card:hover {
  transform: translateY(-2px);
  box-shadow: 0 8px 18px -3px rgba(2, 132, 199, 0.10);
  border-color: var(--ex-sky-400);
}

.ex-stage-top {
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.ex-stage-step {
  font-size: 0.78rem;
  font-weight: 900;
  color: var(--ex-text-subtle);
  letter-spacing: 0.05em;
}

.ex-stage-icon {
  width: 32px;
  height: 32px;
  border-radius: var(--ex-radius-sm);
  display: flex;
  align-items: center;
  justify-content: center;
}

.ex-stage-icon svg {
  width: 17px;
  height: 17px;
}

.ex-stage-forms .ex-stage-icon     { background: var(--ex-stage-teal-bg); color: var(--ex-stage-teal); }
.ex-stage-scheduled .ex-stage-icon { background: var(--ex-sky-50); color: var(--ex-sky-600); }
.ex-stage-written .ex-stage-icon   { background: var(--ex-stage-indigo-bg); color: var(--ex-stage-indigo); }
.ex-stage-oral .ex-stage-icon      { background: var(--ex-stage-amber-bg); color: var(--ex-stage-amber); }
.ex-stage-completed .ex-stage-icon { background: var(--ex-stage-emerald-bg); color: var(--ex-stage-emerald); }

.ex-stage-card:hover.ex-stage-forms     { border-color: var(--ex-stage-teal); }
.ex-stage-card:hover.ex-stage-scheduled { border-color: var(--ex-sky-400); }
.ex-stage-card:hover.ex-stage-written   { border-color: var(--ex-stage-indigo); }
.ex-stage-card:hover.ex-stage-oral      { border-color: var(--ex-stage-amber); }
.ex-stage-card:hover.ex-stage-completed { border-color: var(--ex-stage-emerald); }

.ex-stage-body {
  display: flex;
  flex-direction: column;
}

.ex-stage-reusable-tag {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  font-size: 0.68rem;
  font-weight: 800;
  color: var(--ex-stage-teal);
  background: var(--ex-stage-teal-bg);
  padding: 1px 6px;
  border-radius: 4px;
  border: 1px solid var(--ex-stage-teal-bd);
  width: fit-content;
  margin-bottom: 4px;
}

.ex-reusable-dot {
  width: 5px;
  height: 5px;
  border-radius: 50%;
  background: var(--ex-stage-teal);
}

.ex-stage-name {
  font-size: 0.92rem;
  font-weight: 800;
  color: var(--ex-text-primary);
}

.ex-stage-caption {
  font-size: 0.74rem;
  color: var(--ex-text-muted);
  line-height: 1.4;
}

.ex-stage-count {
  font-size: 1.55rem;
  font-weight: 900;
  color: var(--ex-text-primary);
  line-height: 1.2;
}

/* ==========================================================================
   أدوات الامتحانات السريعة (Quick Exam Grading Tools)
   ========================================================================== */
.ex-tools-bento-row {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 14px;
  margin-top: 4px;
}

.ex-tool-card {
  position: relative;
  background: var(--ex-bg-subtle);
  border: 1px solid var(--ex-border-default);
  border-radius: var(--ex-radius-lg);
  padding: 5px;
  text-decoration: none !important;
  color: inherit;
  transition: var(--ex-transition);
}

.ex-tool-inner {
  background: var(--ex-bg-card-inner);
  border: 1px solid rgba(255, 255, 255, 0.6);
  border-radius: 12px;
  padding: 14px 18px;
  display: flex;
  align-items: center;
  gap: 14px;
  height: 100%;
  box-shadow: var(--ex-shadow-sm);
  transition: var(--ex-transition);
}

.ex-tool-card:hover {
  transform: translateY(-2px);
  box-shadow: var(--ex-shadow-hover);
}

.ex-tool-icon-box {
  width: 44px;
  height: 44px;
  border-radius: var(--ex-radius-md);
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
}

.ex-tool-icon-box svg {
  width: 22px;
  height: 22px;
}

.ex-icon-indigo {
  background: var(--ex-stage-indigo-bg);
  color: var(--ex-stage-indigo);
  border: 1px solid var(--ex-stage-indigo-bd);
}

.ex-icon-emerald {
  background: var(--ex-stage-emerald-bg);
  color: var(--ex-stage-emerald);
  border: 1px solid var(--ex-stage-emerald-bd);
}

.ex-tool-info {
  display: flex;
  flex-direction: column;
  flex: 1;
}

.ex-tool-title {
  font-size: 0.95rem;
  font-weight: 800;
  color: var(--ex-text-primary);
}

.ex-tool-desc {
  font-size: 0.78rem;
  color: var(--ex-text-muted);
}

.ex-tool-arrow {
  font-size: 1.1rem;
  color: var(--ex-sky-600);
  transition: transform 0.2s ease;
}

.ex-tool-card:hover .ex-tool-arrow {
  transform: translateX(-4px);
}

/* ==========================================================================
   هياكل التحميل (Zero CLS Skeleton Loaders)
   ========================================================================== */
.ex-skeleton {
  display: inline-block;
  height: 2.2rem;
  width: 52px;
  background: linear-gradient(90deg, var(--ex-border-light) 25%, var(--ex-bg-subtle) 50%, var(--ex-border-light) 75%);
  background-size: 200% 100%;
  animation: exShimmer 1.4s infinite;
  border-radius: var(--ex-radius-sm);
}

.ex-skeleton-pipe {
  height: 1.55rem;
  width: 44px;
}

@keyframes exShimmer {
  0% { background-position: 200% 0; }
  100% { background-position: -200% 0; }
}

.is-loading .ex-skeleton {
  display: inline-block;
}

/* ==========================================================================
   التجاوب مع الشاشات (Responsive Design)
   ========================================================================== */
@media (max-width: 1024px) {
  .ex-bento-hero-grid {
    grid-template-columns: 1fr;
  }

  .ex-pipeline-bento-grid {
    grid-template-columns: repeat(2, 1fr);
  }

  .ex-tools-bento-row {
    grid-template-columns: 1fr;
  }
}

@media (max-width: 640px) {
  .ex-shell {
    padding: 16px;
  }

  .ex-header-island {
    flex-direction: column;
    align-items: flex-start;
  }

  .ex-pipeline-bento-grid {
    grid-template-columns: 1fr;
  }
}

