script:
(function () {
  "use strict";

  /* ==========================================================================
   * لوحة قسم الامتحانات - Modular Executive Engine (Frappe Custom Block)
   * Built according to clean architecture, SWR caching, Single Query Group By,
   * flexible status matching, and Page Visibility Polling.
   * ========================================================================== */

  var root = typeof root_element !== "undefined" ? root_element : document.querySelector(".exam-dash") || document;

  if (root.__exam_poller) {
    root.__exam_poller.stop();
  }

  installNumberTypography(root);

  function installNumberTypography(scope) {
    if (!scope || scope.__number_typography_installed) return;
    scope.__number_typography_installed = true;
    var digits = /[0-9٠-٩]+(?:[.,:/+\-%][0-9٠-٩]+)*/g, excluded = "SCRIPT,STYLE,TEXTAREA,OPTION";
    function render() {
      var walker = document.createTreeWalker(scope, NodeFilter.SHOW_TEXT, null, false), nodes = [], node;
      while ((node = walker.nextNode())) {
        var parent = node.parentElement;
        if (parent && !parent.closest(".app-number") && excluded.indexOf(parent.tagName) === -1 && digits.test(node.nodeValue)) {
          nodes.push(node);
        }
        digits.lastIndex = 0;
      }
      nodes.forEach(function (textNode) {
        var fragment = document.createDocumentFragment(), value = textNode.nodeValue, last = 0;
        value.replace(digits, function (match, offset) {
          fragment.appendChild(document.createTextNode(value.slice(last, offset)));
          var span = document.createElement("span");
          span.className = "app-number";
          span.textContent = match;
          fragment.appendChild(span);
          last = offset + match.length;
        });
        fragment.appendChild(document.createTextNode(value.slice(last)));
        textNode.parentNode.replaceChild(fragment, textNode);
        digits.lastIndex = 0;
      });
    }
    var queued = false;
    new MutationObserver(function () {
      if (!queued) {
        queued = true;
        requestAnimationFrame(function () {
          queued = false;
          render();
        });
      }
    }).observe(scope, { childList: true, characterData: true, subtree: true });
    render();
  }

  // 1. الإعدادات والثوابت (Configuration)
  var CONFIG = {
    TIMEOUT_MS: 9000,
    ANIMATION_DURATION_MS: 650,
    POLLING_INTERVAL_MS: 5 * 60 * 1000,
    CACHE_KEY: "exam_dashboard_swr_cache_v2",
    STATUS_SYNONYMS: {
      scheduled: ["scheduled", "مجدول", "في انتظار الاختبار"],
      written: ["written in progress", "written", "تحريري جارٍ", "جارٍ التحريري"],
      oral: ["oral in progress", "oral", "شفوي جارٍ", "جارٍ الشفوي"],
      completed: ["completed", "مكتمل", "تمت الامتحانات", "تم الاختبار"]
    },
    ALLOWED_DOCTYPES: ["exam_group_date", "exam_form"]
  };

  // 2. إدارة الحالة (State Management)
  var STATE = {
    isRefreshing: false,
    hasCachedData: false,
    counts: {
      forms: 0,
      total: 0,
      scheduled: 0,
      written: 0,
      oral: 0,
      completed: 0,
      inProgress: 0
    }
  };

  // 3. مطابقة وتطبيع حالات الامتحانات (Status Engine)
  var StatusEngine = {
    normalize: function (str) {
      if (!str) return "";
      return String(str).trim().toLowerCase().replace(/[\s_-]+/g, " ");
    },
    matchCategory: function (rawStatus) {
      var normalized = StatusEngine.normalize(rawStatus);
      if (!normalized) return "scheduled";

      var categories = Object.keys(CONFIG.STATUS_SYNONYMS);
      for (var i = 0; i < categories.length; i++) {
        var cat = categories[i];
        var synonyms = CONFIG.STATUS_SYNONYMS[cat];
        for (var j = 0; j < synonyms.length; j++) {
          var syn = StatusEngine.normalize(synonyms[j]);
          if (normalized === syn || normalized.indexOf(syn) !== -1 || syn.indexOf(normalized) !== -1) {
            return cat;
          }
        }
      }
      return null;
    }
  };

  // 4. خدمة البيانات والاتصال بقاعدة بيانات Frappe (API Service)
  var APIService = {
    fetchAggregatedStats: function () {
      if (!window.frappe || !frappe.call) {
        return APIService.fetchFallbackIndividualCounts();
      }

      // محاولة 1: استدعاء الـ Whitelisted Method من تطبيق taq_it
      return frappe.call({
        method: "taq_it.api.get_exam_dashboard_stats",
        timeout: 3000,
        error: function (r) {
          if (r) r.exc = null;
        }
      }).then(function (r) {
        if (r && r.message && r.message.success) {
          var res = r.message;
          return {
            forms: res.forms || 0,
            total: res.total || 0,
            scheduled: res.scheduled || 0,
            written: res.written || 0,
            oral: res.oral || 0,
            completed: res.completed || 0,
            inProgress: res.inProgress || 0
          };
        }
        throw new Error("Fallback needed");
      }).catch(function () {
        var pForms = frappe.call({
          method: "frappe.desk.reportview.get",
          args: { doctype: "exam_form", fields: ["count(name) as count"], limit: 1 }
        }).catch(function () { return { message: { values: [[0]] } }; });

        var pGroups = frappe.call({
          method: "frappe.desk.reportview.get",
          args: {
            doctype: "exam_group_date",
            fields: ["exam_status", "count(name) as count"],
            group_by: "exam_status",
            limit: 100
          }
        });

        return Promise.all([pForms, pGroups])
          .then(function (results) {
            var formsMsg = (results[0] && results[0].message) || {};
            var groupsMsg = (results[1] && results[1].message) || {};

            var parsed = {
              forms: 0,
              total: 0,
              scheduled: 0,
              written: 0,
              oral: 0,
              completed: 0,
              inProgress: 0
            };

            if (formsMsg.values && formsMsg.values[0]) {
              parsed.forms = parseInt(formsMsg.values[0][0], 10) || 0;
            }

            var values = groupsMsg.values || [];
            values.forEach(function (row) {
              var rawStatus = row[0] || "Scheduled";
              var count = parseInt(row[1], 10) || 0;
              parsed.total += count;

              var cat = StatusEngine.matchCategory(rawStatus);
              if (cat && parsed[cat] !== undefined) {
                parsed[cat] += count;
              }
            });

            parsed.inProgress = parsed.written + parsed.oral;
            return parsed;
          })
          .catch(function () {
            return APIService.fetchFallbackIndividualCounts();
          });
      });
    },

    fetchCountWithTimeout: function (doctype, filters) {
      if (!window.frappe || !frappe.db || !frappe.db.count) {
        return Promise.resolve(0);
      }
      return new Promise(function (resolve) {
        var queryFilters = filters ? Object.assign({}, filters) : {};
        frappe.db.count(doctype, Object.keys(queryFilters).length > 0 ? { filters: queryFilters } : {})
          .then(function (count) { resolve(typeof count === "number" ? count : 0); })
          .catch(function () { resolve(0); });
        setTimeout(function () { resolve(0); }, CONFIG.TIMEOUT_MS);
      });
    },

    fetchFallbackIndividualCounts: function () {
      return Promise.all([
        APIService.fetchCountWithTimeout("exam_form", null),
        APIService.fetchCountWithTimeout("exam_group_date", null),
        APIService.fetchCountWithTimeout("exam_group_date", { exam_status: "Scheduled" }),
        APIService.fetchCountWithTimeout("exam_group_date", { exam_status: "Written In Progress" }),
        APIService.fetchCountWithTimeout("exam_group_date", { exam_status: "Oral In Progress" }),
        APIService.fetchCountWithTimeout("exam_group_date", { exam_status: "Completed" })
      ]).then(function (results) {
        return {
          forms: results[0],
          total: results[1],
          scheduled: results[2],
          written: results[3],
          oral: results[4],
          completed: results[5],
          inProgress: results[3] + results[4]
        };
      });
    },

    fetchNextScheduledExam: function () {
      if (!window.frappe || !frappe.db || !frappe.db.get_list) {
        return Promise.resolve(null);
      }
      return new Promise(function (resolve) {
        if (frappe.model && frappe.model.with_doctype) {
          frappe.model.with_doctype("exam_group_date", function () {
            var meta = frappe.get_meta ? frappe.get_meta("exam_group_date") : null;
            var dateField = "date";
            if (meta && meta.fields) {
              var found = meta.fields.find(function (f) { return f.fieldtype === "Date"; });
              if (found) dateField = found.fieldname;
            }

            frappe.db.get_list("exam_group_date", {
              filters: { exam_status: "Scheduled" },
              fields: ["name", dateField],
              order_by: dateField + " asc",
              limit: 1
            }).then(function (records) {
              if (records && records.length && records[0][dateField]) {
                resolve({ dateStr: records[0][dateField] });
              } else {
                resolve(null);
              }
            }).catch(function () { resolve(null); });
          });
        } else {
          resolve(null);
        }
      });
    }
  };

  // 5. إدارة التخزين المؤقت اللحظي (SWR Cache)
  var CacheManager = {
    loadCachedState: function () {
      try {
        var raw = sessionStorage.getItem(CONFIG.CACHE_KEY);
        if (!raw) return false;
        var data = JSON.parse(raw);
        if (data && data.counts && typeof data.counts.total === "number") {
          STATE.counts = Object.assign({}, data.counts);
          STATE.hasCachedData = true;
          return true;
        }
      } catch (e) {
        console.warn("[Exam Dashboard] Cache read skipped:", e);
      }
      return false;
    },
    saveState: function () {
      try {
        sessionStorage.setItem(CONFIG.CACHE_KEY, JSON.stringify({
          counts: STATE.counts,
          timestamp: Date.now()
        }));
      } catch (e) {}
    }
  };

  // 6. منطق العرض وتحديث الواجهة (UI Presenter)
  var UIPresenter = {
    formatDigits: function (val) {
      if (val === null || val === undefined) return "0";
      return String(val).replace(/[٠-٩]/g, function (d) {
        return d.charCodeAt(0) - 1632;
      });
    },

    animateNumber: function (el, targetValue, isInstant) {
      if (!el) return;
      el.classList.remove("is-loading");
      el.setAttribute("dir", "ltr");
      el.setAttribute("lang", "en");

      if (typeof targetValue !== "number" || isNaN(targetValue)) {
        el.textContent = "0";
        return;
      }

      if (isInstant) {
        el.textContent = UIPresenter.formatDigits(targetValue);
        return;
      }

      var currentNum = parseInt(el.textContent.replace(/[^0-9]/g, ""), 10) || 0;
      var startValue = currentNum;
      var startTime = null;
      var animDuration = CONFIG.ANIMATION_DURATION_MS;

      function step(timestamp) {
        if (!startTime) startTime = timestamp;
        var progress = Math.min((timestamp - startTime) / animDuration, 1);
        var easeProgress = 1 - Math.pow(1 - progress, 3);
        var current = Math.round(startValue + (targetValue - startValue) * easeProgress);

        el.textContent = UIPresenter.formatDigits(current);

        if (progress < 1) {
          window.requestAnimationFrame(step);
        } else {
          el.textContent = UIPresenter.formatDigits(targetValue);
        }
      }

      window.requestAnimationFrame(step);
    },

    setCount: function (selector, value, isInstant) {
      var targetEl = root.querySelector(selector);
      if (!targetEl) return;
      var numEl = targetEl.querySelector(".tq-count-value") || targetEl;
      UIPresenter.animateNumber(numEl, typeof value === "number" ? value : 0, isInstant);
    },

    setText: function (selector, text) {
      var targetEl = root.querySelector(selector);
      if (!targetEl) return;
      var numEl = targetEl.querySelector(".tq-count-value") || targetEl;
      numEl.classList.remove("is-loading");
      numEl.setAttribute("dir", "ltr");
      numEl.setAttribute("lang", "en");
      numEl.textContent = UIPresenter.formatDigits(text);
    },

    setError: function (selector) {
      var targetEl = root.querySelector(selector);
      if (!targetEl) return;
      var numEl = targetEl.querySelector(".tq-count-value") || targetEl;
      numEl.classList.remove("is-loading");
      numEl.textContent = "—";
    },

    updateAlertBanner: function (nextExamData) {
      var box = root.querySelector("#twd-exam-alerts-box");
      var alertNext = root.querySelector("#alert-next-exam");
      if (!box || !alertNext) return;

      var hasVisibleAlert = false;
      if (nextExamData && nextExamData.dateStr) {
        var examDate = new Date(nextExamData.dateStr);
        if (!isNaN(examDate.getTime())) {
          var today = new Date();
          today.setHours(0, 0, 0, 0);
          examDate.setHours(0, 0, 0, 0);

          var daysDiff = Math.ceil((examDate.getTime() - today.getTime()) / (1000 * 60 * 60 * 24));
          if (daysDiff >= 0) {
            var monthsArr = ["يناير", "فبراير", "مارس", "أبريل", "مايو", "يونيو", "يوليو", "أغسطس", "سبتمبر", "أكتوبر", "نوفمبر", "ديسمبر"];
            var dateEl = alertNext.querySelector(".twd-alert__date");
            var remEl = alertNext.querySelector(".twd-alert__remaining");
            
            if (dateEl) {
              dateEl.innerHTML = '<span class="num">' + UIPresenter.formatDigits(examDate.getDate()) + '</span> ' + monthsArr[examDate.getMonth()] + ' <span class="num">' + UIPresenter.formatDigits(examDate.getFullYear()) + '</span>';
            }
            if (remEl) {
              var remText = "";
              if (daysDiff === 0) remText = "اليوم";
              else if (daysDiff === 1) remText = "غداً";
              else if (daysDiff === 2) remText = "بعد غد";
              else remText = 'متبقي <span class="num">' + UIPresenter.formatDigits(daysDiff) + '</span> يوم';
              remEl.innerHTML = remText;
            }

            alertNext.style.display = "flex";
            hasVisibleAlert = true;
          } else {
            alertNext.style.display = "none";
          }
        } else {
          alertNext.style.display = "none";
        }
      }

      box.style.display = hasVisibleAlert ? "flex" : "none";
    },

    calculateCompletionRate: function () {
      if (STATE.counts.total > 0) {
        return Math.round((STATE.counts.completed / STATE.counts.total) * 100);
      }
      return null;
    },

    renderAll: function (isInstant) {
      UIPresenter.setCount("#stat-exam-forms", STATE.counts.forms, isInstant);
      UIPresenter.setCount("#stat-exam-total", STATE.counts.total, isInstant);
      UIPresenter.setCount("#stat-exam-scheduled", STATE.counts.scheduled, isInstant);
      UIPresenter.setCount("#stat-exam-written", STATE.counts.written, isInstant);
      UIPresenter.setCount("#stat-exam-oral", STATE.counts.oral, isInstant);
      UIPresenter.setCount("#stat-exam-completed", STATE.counts.completed, isInstant);
      UIPresenter.setCount("#stat-exam-inprogress", STATE.counts.inProgress, isInstant);

      var rate = UIPresenter.calculateCompletionRate();
      UIPresenter.setText("#stat-exam-rate", rate === null ? "—" : UIPresenter.formatDigits(rate) + "%");
      UIPresenter.normalizeAllDigits();
    },

    normalizeAllDigits: function () {
      if (!root) return;
      var walker = document.createTreeWalker(root, NodeFilter.SHOW_TEXT, null, false);
      var node;
      while ((node = walker.nextNode())) {
        if (/[٠-٩]/.test(node.nodeValue)) {
          node.nodeValue = node.nodeValue.replace(/[٠-٩]/g, function (d) {
            return String(d.charCodeAt(0) - 1632);
          });
        }
      }
    },

    setRefreshSpinning: function (isSpinning) {
      var icon = root.querySelector(".ex-icon-refresh");
      if (icon) {
        if (isSpinning) icon.classList.add("is-spinning");
        else icon.classList.remove("is-spinning");
      }
    }
  };

  // 7. موجه التنقل (Router)
  var Router = {
    navigate: function (target) {
      var doctype = target.getAttribute("data-doctype");
      if (!doctype || CONFIG.ALLOWED_DOCTYPES.indexOf(doctype) === -1) return;

      if (target.getAttribute("data-action") === "new") {
        if (window.frappe && frappe.new_doc) {
          frappe.new_doc(doctype);
        } else {
          window.location.href = "/app/" + encodeURIComponent(doctype.toLowerCase().replace(/ /g, "-")) + "/new";
        }
        return;
      }

      var filters = {};
      try {
        var rawFilters = target.getAttribute("data-filters");
        if (rawFilters) filters = JSON.parse(rawFilters);
      } catch (err) {
        filters = {};
      }

      if (window.frappe && frappe.set_route) {
        frappe.route_options = filters;
        frappe.set_route("list", doctype, filters);
      } else {
        var query = Object.keys(filters).length > 0 ? "?" + new URLSearchParams(filters).toString() : "";
        window.location.href = "/app/" + encodeURIComponent(doctype.toLowerCase().replace(/ /g, "-")) + query;
      }
    }
  };

  // 8. المتحكم الدوري الذكي (Smart Poller)
  var Poller = {
    timer: null,
    start: function () {
      Poller.stop();
      Poller.timer = setInterval(function () {
        if (document.visibilityState === "visible" && !STATE.isRefreshing) {
          loadDashboardData(false);
        }
      }, CONFIG.POLLING_INTERVAL_MS);
    },
    stop: function () {
      if (Poller.timer) {
        clearInterval(Poller.timer);
        Poller.timer = null;
      }
    }
  };
  root.__exam_poller = Poller;

  // 9. تهيئة الأحداث
  function initEvents() {
    if (root.__exam_events_bound) return;
    root.__exam_events_bound = true;

    root.addEventListener("click", function (e) {
      var refreshBtn = e.target.closest("#btn-exam-refresh");
      if (refreshBtn) {
        e.preventDefault();
        loadDashboardData(true);
        return;
      }

      var navTarget = e.target.closest("[data-doctype]");
      if (navTarget) {
        e.preventDefault();
        Router.navigate(navTarget);
      }
    });

    root.addEventListener("keydown", function (e) {
      if (e.key === "Enter" || e.key === " ") {
        var target = e.target.closest("[data-doctype], #btn-exam-refresh");
        if (target) {
          e.preventDefault();
          target.click();
        }
      }
    });

    document.addEventListener("visibilitychange", function () {
      if (document.visibilityState === "visible") {
        loadDashboardData(false);
        Poller.start();
      } else {
        Poller.stop();
      }
    });
  }

  // 10. دورة تحميل البيانات
  function loadDashboardData(isManualRefresh) {
    if (STATE.isRefreshing) return;
    STATE.isRefreshing = true;

    if (isManualRefresh) {
      UIPresenter.setRefreshSpinning(true);
    }

    var statsPromise = APIService.fetchAggregatedStats();
    var nextExamPromise = APIService.fetchNextScheduledExam();

    Promise.all([statsPromise, nextExamPromise])
      .then(function (results) {
        STATE.counts = results[0];
        CacheManager.saveState();
        UIPresenter.renderAll(false);
        UIPresenter.updateAlertBanner(results[1]);
      })
      .catch(function (err) {
        console.error("[Exam Dashboard] Load error:", err);
        if (!STATE.hasCachedData) {
          [
            "#stat-exam-forms",
            "#stat-exam-total",
            "#stat-exam-scheduled",
            "#stat-exam-written",
            "#stat-exam-oral",
            "#stat-exam-completed",
            "#stat-exam-inprogress",
            "#stat-exam-rate"
          ].forEach(UIPresenter.setError);
        }
      })
      .finally(function () {
        STATE.isRefreshing = false;
        if (isManualRefresh) {
          setTimeout(function () {
            UIPresenter.setRefreshSpinning(false);
          }, 400);
        }
      });
  }

  // 11. الإقلاع الفوري
  initEvents();

  var hasCache = CacheManager.loadCachedState();
  if (hasCache) {
    UIPresenter.renderAll(true);
  }

  loadDashboardData(false);
  Poller.start();
})();

